export const COMPONENT_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeBridgeInk.h\"\n#include \"NarrativeInventoryAuthority.h\"\n#include \"NarrativeLocalization.h\"\n#include \"NarrativeSaveStorage.h\"\n#include \"NarrativeSettings.h\"\n#include \"Components/AudioComponent.h\"\n#include \"Dom/JsonObject.h\"\n#include \"Engine/Engine.h\"\n#include \"Engine/Texture2D.h\"\n#include \"Engine/World.h\"\n#include \"HAL/FileManager.h\"\n#include \"ImageUtils.h\"\n#include \"Kismet/GameplayStatics.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/Paths.h\"\n#include \"Serialization/JsonReader.h\"\n#include \"Serialization/JsonSerializer.h\"\n#include \"Serialization/JsonWriter.h\"\n#include \"Sound/SoundBase.h\"\n#include \"UObject/StrongObjectPtr.h\"\n\nnamespace\n{\n    /** How a jump (ResumeAt) is written in a save's choice path. */\n    const FString JumpMark = FString(TEXT(\"\\u2192\"));\n\n    bool IsPassage(const FNarrativeStoryInfo& D, const FString& Name) { return D.Passages.ContainsByPredicate([&Name](const FNarrativeStoryPassage& P) { return P.Id == Name; }); }\n    bool IsLine(const FNarrativeStoryInfo& D, const FString& Name) { return D.Lines.ContainsByPredicate([&Name](const FNarrativeStoryLine& L) { return L.Path == Name; }); }\n\n    /** The passage a start point is in: the name itself, or the passage of a line (\"garden\" for \"garden.line_…\"). */\n    FString PassageOfName(const FString& Name)\n    {\n        int32 Dot = INDEX_NONE;\n        return Name.FindChar(TEXT('.'), Dot) ? Name.Left(Dot) : Name;\n    }\n\n    /**\n     * The Ink path to choose for a start point. A line is reached through its entry knot, \"passage__line_…\", which\n     * diverts to the line's label (a label after a Continue break sits inside the weave, where a path can't name it).\n     */\n    FString InkPathOf(const FNarrativeStoryInfo& D, const FString& Name) { return IsLine(D, Name) ? Name.Replace(TEXT(\".\"), TEXT(\"__\")) : Name; }\n    bool IsItemVariable(const FNarrativeStoryInfo& D, const FString& Name) { return D.ItemVariables.Contains(Name); }\n    bool IsStoryVariable(const FNarrativeStoryInfo& D, const FString& Name) { return D.Variables.Contains(Name); }\n\n    FString KnotOf(const FNarrativeStoryInfo& D, const FString& Path)\n    {\n        if (Path.IsEmpty()) return FString();\n        FString Knot = Path;\n        int32 Dot = INDEX_NONE;\n        if (Path.FindChar(TEXT('.'), Dot)) Knot = Path.Left(Dot);\n        return IsPassage(D, Knot) ? Knot : FString();\n    }\n\n    /** A name and value from a tag (\"music:calm\" → \"music\", \"calm\"). */\n    void SplitTag(const FString& Raw, FString& Name, FString& Value)\n    {\n        const FString Tag = Raw.TrimStartAndEnd();\n        Name = Tag;\n        Value.Reset();\n        int32 Colon = INDEX_NONE;\n        if (Tag.FindChar(TEXT(':'), Colon))\n        {\n            Name = Tag.Left(Colon).TrimStartAndEnd();\n            Value = Tag.Mid(Colon + 1).TrimStartAndEnd();\n        }\n    }\n\n    bool IsStoryTag(const FNarrativeStoryInfo& D, const FString& Tag)\n    {\n        FString Name, Value;\n        SplitTag(Tag, Name, Value);\n        return D.ReservedTags.Contains(Name);\n    }\n\n    bool Ordered(const FString& Op, int32 C)\n    {\n        if (Op == TEXT(\"==\")) return C == 0;\n        if (Op == TEXT(\"!=\")) return C != 0;\n        if (Op == TEXT(\"<\")) return C < 0;\n        if (Op == TEXT(\"<=\")) return C <= 0;\n        if (Op == TEXT(\">\")) return C > 0;\n        if (Op == TEXT(\">=\")) return C >= 0;\n        return false;\n    }\n\n    /** Reads the story's variables for the conditions of locked choices (the story data's locked choices), the way ink compares them. */\n    class FNarrativeReader final : public FNarrativeVariableReader\n    {\n    public:\n        explicit FNarrativeReader(const FNarrativeInk* InInk) : Ink(InInk) {}\n\n        virtual bool Has(const TCHAR* Name) const override\n        {\n            FNarrativeValue V;\n            if (!Read(Name, V)) return false;\n            switch (V.Type)\n            {\n            case ENarrativeValueType::Bool: return V.bValue;\n            case ENarrativeValueType::Int: return V.IntValue != 0;\n            case ENarrativeValueType::Float: return V.FloatValue != 0.f;\n            default: return false;\n            }\n        }\n\n        virtual bool CompareNumber(const TCHAR* Name, const TCHAR* Op, double Value) const override\n        {\n            FNarrativeValue V;\n            const FString O = Op;\n            if (!Read(Name, V)) return O == TEXT(\"!=\");\n            double X = 0;\n            if (V.Type == ENarrativeValueType::Int) X = V.IntValue;\n            else if (V.Type == ENarrativeValueType::Float) X = V.FloatValue;\n            else if (V.Type == ENarrativeValueType::Bool)\n            {\n                // Ink compares true/false with a number as 1/0, for == and != only.\n                return O == TEXT(\"==\") ? V.bValue == (Value != 0) : O == TEXT(\"!=\") ? V.bValue != (Value != 0) : false;\n            }\n            else return O == TEXT(\"!=\");\n            return Ordered(O, X < Value ? -1 : X > Value ? 1 : 0);\n        }\n\n        virtual bool CompareText(const TCHAR* Name, const TCHAR* Op, const TCHAR* Value) const override\n        {\n            FNarrativeValue V;\n            const FString O = Op;\n            if (!Read(Name, V) || V.Type != ENarrativeValueType::String) return O == TEXT(\"!=\");\n            return Ordered(O, V.StringValue.Compare(Value, ESearchCase::CaseSensitive));\n        }\n\n        virtual bool CompareBool(const TCHAR* Name, const TCHAR* Op, bool Value) const override\n        {\n            const bool B = Has(Name);\n            const FString O = Op;\n            return O == TEXT(\"==\") ? B == Value : O == TEXT(\"!=\") ? B != Value : false;\n        }\n\n    private:\n        bool Read(const TCHAR* Name, FNarrativeValue& Out) const { return Ink && Ink->Get(Name, Out); }\n\n        const FNarrativeInk* Ink;\n    };\n\n    /** The choices on offer (always current), or none before the story starts. */\n    TArray<FNarrativeInkChoice> InkChoices(const TSharedPtr<FNarrativeInk>& Ink)\n    {\n        return Ink.IsValid() ? Ink->CurrentChoices() : TArray<FNarrativeInkChoice>();\n    }\n\n    TMap<FString, TStrongObjectPtr<UTexture2D>>& Pictures()\n    {\n        static TMap<FString, TStrongObjectPtr<UTexture2D>> Loaded;\n        return Loaded;\n    }\n\n    FString SlotKey(int32 Slot) { return Slot == UNarrativeBridgeComponent::AutosaveSlot ? FString(TEXT(\"autosave\")) : Slot < 0 ? FString(TEXT(\"quicksave\")) : FString::Printf(TEXT(\"slot-%d\"), Slot); }\n    FString SaveFile(const FNarrativeStoryInfo& D, const FString& Key) { return FPaths::ProjectSavedDir() / TEXT(\"SaveGames/NarrativeBridge\") / D.SaveFolder / Key + TEXT(\".json\"); }\n    FString ChosenFile(const FNarrativeStoryInfo& D) { return FPaths::ProjectSavedDir() / TEXT(\"SaveGames/NarrativeBridge\") / D.SaveFolder / TEXT(\"chosen.txt\"); }\n\n    /** How a choice is remembered once taken: its knot and its text as written (\"harbour|Take the boat\"). */\n    FString ChosenKeyOf(const FNarrativeInkChoice& Choice)\n    {\n        FString Knot = Choice.SourcePath;\n        int32 Dot = INDEX_NONE;\n        if (Knot.FindChar(TEXT('.'), Dot)) Knot = Knot.Left(Dot);\n        return Knot + TEXT(\"|\") + Choice.Text.TrimStartAndEnd();\n    }\n}\n\nUNarrativeBridgeComponent::UNarrativeBridgeComponent()\n{\n    PrimaryComponentTick.bCanEverTick = true;\n    PrimaryComponentTick.bStartWithTickEnabled = true;\n    // Voice clips go on while a Narrative Story Trigger pauses the game for the dialogue.\n    PrimaryComponentTick.bTickEvenWhenPaused = true;\n}\n\nvoid UNarrativeBridgeComponent::BeginPlay()\n{\n    Super::BeginPlay();\n    LanguageHandle = UNarrativeLocalization::OnChanged().AddUObject(this, &UNarrativeBridgeComponent::Relocalize);\n    if (bStartOnBeginPlay) StartStory();\n}\n\nvoid UNarrativeBridgeComponent::EndPlay(const EEndPlayReason::Type Reason)\n{\n    UNarrativeLocalization::OnChanged().Remove(LanguageHandle);\n    StopVoice();\n    if (Ink.IsValid()) Ink->End();\n    Ink.Reset();\n    Super::EndPlay(Reason);\n}\n\nvoid UNarrativeBridgeComponent::StartStory()\n{\n    Begin(FString());\n}\n\nvoid UNarrativeBridgeComponent::StartAt(const FString& Passage)\n{\n    if (!IsStartPoint(Passage)) { ReportError(FString::Printf(TEXT(\"There is no passage or line called %s.\"), *Passage)); return; }\n    Begin(Passage);\n}\n\nbool UNarrativeBridgeComponent::IsStartPoint(const FString& Name) const\n{\n    return !Name.IsEmpty() && (IsPassage(StoryInfo(), Name) || IsLine(StoryInfo(), Name));\n}\n\nvoid UNarrativeBridgeComponent::EnterAt(const FString& Name)\n{\n    if (!Ink.IsValid()) { StartAt(Name); return; }\n    if (!IsStartPoint(Name)) { ReportError(FString::Printf(TEXT(\"There is no passage or line called %s.\"), *Name)); return; }\n    const bool bExited = IsAtExit();\n    // Saved as a jump, like ResumeAt, so a save carries over to a revised story.\n    ChoicePath.Add(JumpMark + Name);\n    Transcript.Reset();\n    bHasEnded = false;\n    LastPassage = PassageOfName(Name);\n    SetStatus(FString());\n    StopVoice();\n    Ink->GoTo(InkPathOf(StoryInfo(), Name));\n    OnRestarted.Broadcast();\n    if (bExited) OnResumed.Broadcast();\n    Advance();\n}\n\nbool UNarrativeBridgeComponent::HasItem(const FString& ItemId) const\n{\n    if (UObject* Inventory = Authority()) return INarrativeInventoryAuthority::Execute_HasItem(Inventory, ItemId);\n    const FString Var = TEXT(\"has_\") + ItemId;\n    if (!Ink.IsValid() || !IsItemVariable(StoryInfo(), Var)) return false;\n    bool bFound = false;\n    const FNarrativeValue Value = GetStoryValue(Var, bFound);\n    return bFound && Value.Type == ENarrativeValueType::Bool && Value.bValue;\n}\n\nvoid UNarrativeBridgeComponent::Begin(const FString& Passage)\n{\n    if (!StoryAsset) StoryAsset = FNarrativeInk::LoadStoryAsset(NarrativeBridge::StoryAssetPath);\n    if (!StoryData) StoryData = UNarrativeStoryData::GetDefault();\n    if (StoryData && !StoryData->GetError().IsEmpty()) { ReportError(StoryData->GetError()); return; }\n    FString Error;\n    Ink = FNarrativeInk::Begin(StoryAsset, Error);\n    if (!Ink.IsValid()) { ReportError(Error); return; }\n    TArray<FString> Watched;\n    Watched.Append(StoryInfo().ItemVariables);\n    Watched.Append(StoryInfo().Variables);\n    const TWeakObjectPtr<UNarrativeBridgeComponent> Self(this);\n    Ink->Observe(Watched, [Self](const FString& Name, const FNarrativeValue& Value)\n    {\n        if (UNarrativeBridgeComponent* Component = Self.Get()) Component->HandleVariableChange(Name, Value);\n    });\n    ChoicePath.Reset();\n    Transcript.Reset();\n    bHasEnded = false;\n    StartPassage = Passage;\n    LastPassage = PassageOfName(Passage);\n    LoadNote.Reset();\n    SetStatus(FString());\n    StopVoice();\n    if (!Passage.IsEmpty()) Ink->GoTo(InkPathOf(StoryInfo(), Passage));\n    OnRestarted.Broadcast();\n    Advance();\n}\n\nbool UNarrativeBridgeComponent::IsWaitingForContinue() const\n{\n    const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n    return Choices.Num() == 1 && Choices[0].Text == NarrativeBridge::ContinueText;\n}\n\nFString UNarrativeBridgeComponent::GetCurrentExit() const\n{\n    const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n    if (Choices.Num() != 1) return FString();\n    const FString Text = Choices[0].Text;\n    return Text.StartsWith(NarrativeBridge::ExitPrefix, ESearchCase::CaseSensitive) ? Text.Mid(FCString::Strlen(NarrativeBridge::ExitPrefix)) : FString();\n}\n\nTArray<FString> UNarrativeBridgeComponent::GetSourceChoices() const\n{\n    TArray<FString> Labels;\n    if (IsWaitingForContinue() || IsAtExit()) return Labels;\n    for (const FNarrativeInkChoice& Choice : InkChoices(Ink)) Labels.Add(Choice.Text);\n    return Labels;\n}\n\nTArray<FString> UNarrativeBridgeComponent::GetChoices() const\n{\n    TArray<FString> Labels = GetSourceChoices();\n    for (FString& Label : Labels) Label = UNarrativeLocalization::Translate(Label);\n    return Labels;\n}\n\nFString UNarrativeBridgeComponent::GetCurrentPassage() const\n{\n    const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n    if (Choices.Num() > 0)\n    {\n        const FString Knot = KnotOf(StoryInfo(), Choices[0].SourcePath);\n        if (!Knot.IsEmpty()) return Knot;\n    }\n    return LastPassage;\n}\n\nTArray<FNarrativeLockedChoice> UNarrativeBridgeComponent::GetLockedChoices() const\n{\n    TArray<FNarrativeLockedChoice> Locked;\n    const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n    if (!Ink.IsValid() || bHasEnded || Choices.Num() == 0 || IsAtExit() || IsWaitingForContinue()) return Locked;\n    const FString Passage = GetCurrentPassage();\n    auto Offered = [&Choices](const TCHAR* Text) { return Choices.ContainsByPredicate([Text](const FNarrativeInkChoice& C) { return C.Text == Text; }); };\n    // While a forced choice is on offer, it's the only way on: nothing is shown as locked.\n    const FNarrativeStoryInfo& D = StoryInfo();\n    for (const FNarrativeStoryGatedChoice& G : D.GatedChoices)\n        if (G.bForced && Passage == G.Passage && Offered(*G.Text)) return Locked;\n    const FNarrativeReader Reader(Ink.Get());\n    for (const FNarrativeStoryGatedChoice& G : D.GatedChoices)\n    {\n        if (Passage != G.Passage || Offered(*G.Text)) continue;\n        TArray<FString> Missing;\n        for (const FNarrativeStoryRequirement& R : G.Requirements)\n            if (!R.Condition.Evaluate(Reader)) Missing.Add(UNarrativeLocalization::Translate(R.Words));\n        if (Missing.Num() == 0) continue;\n        FNarrativeLockedChoice L;\n        L.Text = UNarrativeLocalization::Translate(G.Text);\n        L.Needs = FString::Join(Missing, TEXT(\", \"));\n        Locked.Add(L);\n    }\n    return Locked;\n}\n\nconst TSet<FString>& UNarrativeBridgeComponent::Chosen() const\n{\n    if (!bChosenLoaded)\n    {\n        bChosenLoaded = true;\n        TArray<FString> Keys;\n        if (FFileHelper::LoadFileToStringArray(Keys, *ChosenFile(StoryInfo())))\n            for (const FString& K : Keys)\n                if (!K.IsEmpty()) ChosenBefore.Add(K);\n    }\n    return ChosenBefore;\n}\n\nbool UNarrativeBridgeComponent::WasChosen(int32 Index) const\n{\n    const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n    if (!Choices.IsValidIndex(Index) || IsWaitingForContinue() || IsAtExit()) return false;\n    return Chosen().Contains(ChosenKeyOf(Choices[Index]));\n}\n\nvoid UNarrativeBridgeComponent::ForgetChosen()\n{\n    Chosen();\n    ChosenBefore.Reset();\n    IFileManager::Get().Delete(*ChosenFile(StoryInfo()), false, false, true);\n}\n\nvoid UNarrativeBridgeComponent::Choose(int32 Index)\n{\n    const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n    if (!Choices.IsValidIndex(Index)) return;\n    const FString Text = Choices[Index].Text;\n    // A Continue break or an exit leaves no trace in the transcript: the page simply goes on.\n    if (!IsWaitingForContinue() && !IsAtExit())\n    {\n        const FString Key = ChosenKeyOf(Choices[Index]);\n        if (!Chosen().Contains(Key))\n        {\n            ChosenBefore.Add(Key);\n            FFileHelper::SaveStringArrayToFile(ChosenBefore.Array(), *ChosenFile(StoryInfo()));\n        }\n        FNarrativeLine Line;\n        Line.Text = Line.SourceText = Text;\n        Line.Tags.Add(TEXT(\"choice\"));\n        Line.bIsChoice = true;\n        Transcript.Add(Localize(Line));\n    }\n    ChoicePath.Add(Text);\n    Ink->Choose(Choices[Index].Index);\n    StopVoice();\n    Advance();\n}\n\nvoid UNarrativeBridgeComponent::Continue()\n{\n    if (IsWaitingForContinue()) Choose(0);\n}\n\nvoid UNarrativeBridgeComponent::Resume()\n{\n    if (!IsAtExit()) return;\n    OnResumed.Broadcast();\n    Choose(0);\n}\n\nvoid UNarrativeBridgeComponent::ResumeAt(const FString& Passage)\n{\n    if (!Ink.IsValid()) return;\n    if (!IsStartPoint(Passage)) { ReportError(FString::Printf(TEXT(\"There is no passage or line called %s.\"), *Passage)); return; }\n    const bool bExited = IsAtExit();\n    // Saves record the jump, so a save carries over to a revised story too.\n    ChoicePath.Add(JumpMark + Passage);\n    Ink->GoTo(InkPathOf(StoryInfo(), Passage));\n    LastPassage = PassageOfName(Passage);\n    bHasEnded = false;\n    StopVoice();\n    if (bExited) OnResumed.Broadcast();\n    Advance();\n}\n\nvoid UNarrativeBridgeComponent::Advance()\n{\n    if (!Ink.IsValid()) return;\n    SyncFromAuthority();\n    while (Ink->CanContinue())\n    {\n        NotePassage();\n        const FString Raw = Ink->Continue().TrimStartAndEnd();\n        const TArray<FString> Tags = Ink->CurrentTags();\n        if (!Raw.IsEmpty())\n        {\n            const FNarrativeLine Line = ParseLine(Raw, Tags);\n            Transcript.Add(Line);\n            QueueVoice(Line);\n            OnLineShown.Broadcast(Line);\n            OnLine.Broadcast(Line.Speaker, Line.Text, Line.Tags);\n        }\n        // A tag with no text after it (a cue at the end of a passage) still reaches the game.\n        RaiseTags(Tags);\n    }\n    AutosaveIfNewPassage();\n    Announce();\n}\n\nvoid UNarrativeBridgeComponent::Announce()\n{\n    if (IsAtExit()) OnExit.Broadcast(GetCurrentExit());\n    else if (IsWaitingForContinue()) OnContinue.Broadcast();\n    else if (InkChoices(Ink).Num() > 0) OnChoices.Broadcast(GetChoices());\n    else\n    {\n        bHasEnded = true;\n        OnEnded.Broadcast();\n    }\n}\n\nvoid UNarrativeBridgeComponent::RaiseTags(const TArray<FString>& Tags)\n{\n    for (const FString& Tag : Tags)\n    {\n        if (IsStoryTag(StoryInfo(), Tag)) continue;\n        FString Name, Value;\n        SplitTag(Tag, Name, Value);\n        if (Name.IsEmpty()) continue;\n        OnTag.Broadcast(Tag.TrimStartAndEnd());\n        OnCue.Broadcast(Name, Value);\n    }\n}\n\nvoid UNarrativeBridgeComponent::NotePassage()\n{\n    const FString Knot = KnotOf(StoryInfo(), Ink->CurrentPath());\n    if (!Knot.IsEmpty()) LastPassage = Knot;\n}\n\nFNarrativeLine UNarrativeBridgeComponent::ParseLine(const FString& Raw, const TArray<FString>& Tags) const\n{\n    FNarrativeLine Line;\n    Line.Tags = Tags;\n    for (const FString& Tag : Tags)\n    {\n        FString Name, Value;\n        SplitTag(Tag, Name, Value);\n        if (Name == TEXT(\"speaker\")) Line.Speaker = Line.SpeakerId = Value;\n        else if (Name == TEXT(\"scene\")) Line.Scene = Value;\n        else if (Name == TEXT(\"paren\")) Line.Paren = Value;\n        else if (Name == TEXT(\"image\")) Line.Image = Value;\n        else if (Name == TEXT(\"audio\")) Line.VoiceClip = Value;\n        else if (Name == TEXT(\"transition\")) Line.bIsTransition = true;\n        else if (Name == TEXT(\"cutscene\")) Line.bIsCutscene = true;\n    }\n    Line.Text = Raw;\n    if (!Line.Speaker.IsEmpty())\n    {\n        // Ink prints dialogue as \"NAME: text\"; the name shown is the one before the colon.\n        FString Name, Text;\n        if (Raw.Split(TEXT(\": \"), &Name, &Text, ESearchCase::CaseSensitive) && !Name.IsEmpty())\n        {\n            Line.Speaker = Name;\n            Line.Text = Text;\n        }\n    }\n    Line.SourceText = Line.Text;\n    Line.SourceSpeaker = Line.Speaker;\n    Line.SourceScene = Line.Scene;\n    Line.SourceParen = Line.Paren;\n    return Localize(Line);\n}\n\nFNarrativeLine UNarrativeBridgeComponent::Localize(FNarrativeLine Line)\n{\n    Line.Text = UNarrativeLocalization::Translate(Line.SourceText.IsEmpty() ? Line.Text : Line.SourceText);\n    if (!Line.SourceSpeaker.IsEmpty()) Line.Speaker = UNarrativeLocalization::Translate(Line.SourceSpeaker);\n    if (!Line.SourceScene.IsEmpty()) Line.Scene = UNarrativeLocalization::Translate(Line.SourceScene);\n    if (!Line.SourceParen.IsEmpty()) Line.Paren = UNarrativeLocalization::Translate(Line.SourceParen);\n    return Line;\n}\n\nvoid UNarrativeBridgeComponent::Relocalize()\n{\n    for (FNarrativeLine& Line : Transcript) Line = Localize(Line);\n}\n\nFString UNarrativeBridgeComponent::GetCurrentPicture() const\n{\n    for (int32 i = Transcript.Num() - 1; i >= 0; --i)\n        if (!Transcript[i].Image.IsEmpty()) return Transcript[i].Image;\n    return FString();\n}\n\nconst FNarrativeStoryInfo& UNarrativeBridgeComponent::StoryInfo() const\n{\n    return StoryData ? StoryData->Info() : UNarrativeStoryData::DefaultInfo();\n}\n\nTArray<FString> UNarrativeBridgeComponent::GetPassages() const\n{\n    TArray<FString> Out;\n    for (const FNarrativeStoryPassage& P : StoryInfo().Passages) Out.Add(P.Id);\n    return Out;\n}\n\nTArray<FString> UNarrativeBridgeComponent::GetLines() const\n{\n    TArray<FString> Out;\n    for (const FNarrativeStoryLine& L : StoryInfo().Lines) Out.Add(L.Path);\n    return Out;\n}\n\nTArray<FString> UNarrativeBridgeComponent::GetActs() const\n{\n    TArray<FString> Out;\n    for (const FNarrativeStoryAct& A : StoryInfo().Acts) Out.Add(A.Id);\n    return Out;\n}\n\nFString UNarrativeBridgeComponent::GetActOf(const FString& Passage) const\n{\n    for (const FNarrativeStoryPassage& P : StoryInfo().Passages)\n        if (P.Id == Passage) return P.Act;\n    return FString();\n}\n\nFString UNarrativeBridgeComponent::GetActTitle(const FString& Act) const\n{\n    for (const FNarrativeStoryAct& A : StoryInfo().Acts)\n        if (A.Id == Act) return A.Title;\n    return FString();\n}\n\nTArray<FString> UNarrativeBridgeComponent::GetExits() const { return StoryInfo().Exits; }\n\nFString UNarrativeBridgeComponent::GetStoryVersion() const\n{\n    return StoryInfo().StoryVersion;\n}\n\n// ---- Variables and inventory: the host game is the single source of truth -------------\n\nbool UNarrativeBridgeComponent::CanAccessVariable(const FString& Name, bool bWrite) const\n{\n    return IsStoryVariable(StoryInfo(), Name) || (!bWrite && IsItemVariable(StoryInfo(), Name));\n}\n\nFNarrativeValue UNarrativeBridgeComponent::GetStoryValue(const FString& Name, bool& bFound) const\n{\n    FNarrativeValue Value;\n    bFound = Ink.IsValid() && CanAccessVariable(Name, false) && Ink->Get(Name, Value);\n    return Value;\n}\n\nbool UNarrativeBridgeComponent::GetBool(const FString& Name) const\n{\n    bool bFound = false;\n    const FNarrativeValue V = GetStoryValue(Name, bFound);\n    return bFound && V.Type == ENarrativeValueType::Bool && V.bValue;\n}\n\nint32 UNarrativeBridgeComponent::GetInt(const FString& Name) const\n{\n    bool bFound = false;\n    const FNarrativeValue V = GetStoryValue(Name, bFound);\n    if (!bFound) return 0;\n    return V.Type == ENarrativeValueType::Int ? V.IntValue : V.Type == ENarrativeValueType::Float ? FMath::RoundToInt(V.FloatValue) : 0;\n}\n\nfloat UNarrativeBridgeComponent::GetFloat(const FString& Name) const\n{\n    bool bFound = false;\n    const FNarrativeValue V = GetStoryValue(Name, bFound);\n    if (!bFound) return 0.f;\n    return V.Type == ENarrativeValueType::Float ? V.FloatValue : V.Type == ENarrativeValueType::Int ? static_cast<float>(V.IntValue) : 0.f;\n}\n\nFString UNarrativeBridgeComponent::GetString(const FString& Name) const\n{\n    bool bFound = false;\n    const FNarrativeValue V = GetStoryValue(Name, bFound);\n    return bFound && V.Type == ENarrativeValueType::String ? V.StringValue : FString();\n}\n\nFString UNarrativeBridgeComponent::GetVariableAsString(const FString& Name) const\n{\n    bool bFound = false;\n    const FNarrativeValue Value = GetStoryValue(Name, bFound);\n    return bFound ? Value.ToString() : FString();\n}\n\nbool UNarrativeBridgeComponent::SetStoryValue(const FString& Name, const FNarrativeValue& Value)\n{\n    return Ink.IsValid() && CanAccessVariable(Name, true) && Ink->Set(Name, Value);\n}\n\nvoid UNarrativeBridgeComponent::SetItemOwned(const FString& ItemId, bool bOwned)\n{\n    if (Ink.IsValid()) Ink->Set(FString(TEXT(\"has_\")) + ItemId, FNarrativeValue::FromBool(bOwned));\n}\n\nvoid UNarrativeBridgeComponent::HandleVariableChange(const FString& Variable, const FNarrativeValue& NewValue)\n{\n    if (IsItemVariable(StoryInfo(), Variable) && !bSyncing)\n    {\n        if (UObject* Inventory = Authority())\n        {\n            const FString ItemId = Variable.Mid(4);\n            if (NewValue.Type == ENarrativeValueType::Bool)\n            {\n                if (NewValue.bValue) INarrativeInventoryAuthority::Execute_GiveItem(Inventory, ItemId);\n                else INarrativeInventoryAuthority::Execute_TakeItem(Inventory, ItemId);\n            }\n        }\n    }\n    if (!bSilent) OnVariableChanged.Broadcast(Variable, NewValue.ToString());\n}\n\nvoid UNarrativeBridgeComponent::RaiseAllVariables()\n{\n    for (const FString& Name : StoryInfo().ItemVariables) OnVariableChanged.Broadcast(Name, GetVariableAsString(Name));\n    for (const FString& Name : StoryInfo().Variables) OnVariableChanged.Broadcast(Name, GetVariableAsString(Name));\n}\n\nUObject* UNarrativeBridgeComponent::Authority() const\n{\n    if (InventoryAuthority && InventoryAuthority->Implements<UNarrativeInventoryAuthority>()) return InventoryAuthority;\n    if (AActor* Owner = GetOwner())\n    {\n        if (Owner->Implements<UNarrativeInventoryAuthority>()) return Owner;\n        for (UActorComponent* C : Owner->GetComponents())\n            if (C && C->Implements<UNarrativeInventoryAuthority>()) return C;\n    }\n    return nullptr;\n}\n\nvoid UNarrativeBridgeComponent::SyncFromAuthority()\n{\n    UObject* Inventory = Authority();\n    if (!Inventory || !Ink.IsValid()) return;\n    bSyncing = true;\n    for (const FString& Var : StoryInfo().ItemVariables)\n    {\n        Ink->Set(Var, FNarrativeValue::FromBool(INarrativeInventoryAuthority::Execute_HasItem(Inventory, Var.Mid(4))));\n    }\n    bSyncing = false;\n}\n\n// ---- Saves, with story-version checks ----------------------------------------------------\n\nFString UNarrativeBridgeComponent::Excerpt() const\n{\n    for (int32 i = Transcript.Num() - 1; i >= 0; --i)\n    {\n        const FNarrativeLine& L = Transcript[i];\n        if (L.bIsChoice || L.Text.IsEmpty()) continue;\n        const FString T = PlainText((L.Speaker.IsEmpty() ? FString() : L.Speaker + TEXT(\": \")) + L.Text);\n        return T.Len() > 90 ? T.Left(87) + TEXT(\"...\") : T;\n    }\n    return FString();\n}\n\nFString UNarrativeBridgeComponent::SaveState() const\n{\n    if (!Ink.IsValid()) return FString();\n    TSharedRef<FJsonObject> Data = MakeShared<FJsonObject>();\n    Data->SetStringField(TEXT(\"storyVersion\"), StoryInfo().StoryVersion);\n    Data->SetStringField(TEXT(\"inkState\"), Ink->ToJson());\n    TArray<TSharedPtr<FJsonValue>> Path;\n    for (const FString& C : ChoicePath) Path.Add(MakeShared<FJsonValueString>(C));\n    Data->SetArrayField(TEXT(\"choicePath\"), Path);\n    Data->SetStringField(TEXT(\"startPassage\"), StartPassage);\n    Data->SetStringField(TEXT(\"savedAt\"), FDateTime::UtcNow().ToIso8601());\n    Data->SetStringField(TEXT(\"passage\"), GetCurrentPassage());\n    Data->SetStringField(TEXT(\"excerpt\"), Excerpt());\n    FString Out;\n    const TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&Out);\n    FJsonSerializer::Serialize(Data, Writer);\n    return Out;\n}\n\nbool UNarrativeBridgeComponent::TryLoadState(const FString& Save, FString& Error)\n{\n    Error.Reset();\n    LoadNote.Reset();\n    TSharedPtr<FJsonObject> Data;\n    if (!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Save), Data) || !Data.IsValid()) { Error = TEXT(\"Save data is corrupt.\"); return false; }\n    FString InkState;\n    if (!Data->TryGetStringField(TEXT(\"inkState\"), InkState) || InkState.IsEmpty()) { Error = TEXT(\"Save data is empty.\"); return false; }\n    if (!Ink.IsValid()) StartStory();\n    if (!Ink.IsValid()) { Error = TEXT(\"The story could not start.\"); return false; }\n    FString Version;\n    Data->TryGetStringField(TEXT(\"storyVersion\"), Version);\n    Data->TryGetStringField(TEXT(\"startPassage\"), StartPassage);\n    TArray<FString> Path;\n    const TArray<TSharedPtr<FJsonValue>>* Saved = nullptr;\n    const bool bHasPath = Data->TryGetArrayField(TEXT(\"choicePath\"), Saved);\n    if (bHasPath)\n        for (const TSharedPtr<FJsonValue>& V : *Saved) Path.Add(V->AsString());\n    if (Version != StoryInfo().StoryVersion)\n    {\n        // Saves from before choices were recorded can't be carried over.\n        if (!bHasPath)\n        {\n            Error = FString::Printf(TEXT(\"This save was made with story version %s but the game now has %s. Restart the narrative.\"), *Version, *StoryInfo().StoryVersion);\n            return false;\n        }\n        ReplayChoices(Path, Version);\n        return true;\n    }\n    Ink->LoadJson(InkState);\n    ChoicePath = Path;\n    Transcript.Reset();\n    bHasEnded = false;\n    Data->TryGetStringField(TEXT(\"passage\"), LastPassage);\n    StopVoice();\n    OnRestarted.Broadcast();\n    RaiseAllVariables();\n    if (Ink->CanContinue()) Advance();\n    else Announce();\n    return true;\n}\n\n// A save from another version of the story: play the new version from the start (or the passage it was started at),\n// silently, making the same choices (matched by their text), so its text and variables apply. Stops at the first choice\n// the new version no longer offers.\nvoid UNarrativeBridgeComponent::ReplayChoices(const TArray<FString>& Path, const FString& SavedVersion)\n{\n    Ink->Reset();\n    if (IsStartPoint(StartPassage)) Ink->GoTo(InkPathOf(StoryInfo(), StartPassage));\n    ChoicePath.Reset();\n    Transcript.Reset();\n    bHasEnded = false;\n    LastPassage = PassageOfName(StartPassage);\n    StopVoice();\n    int32 Followed = 0;\n    // The host's inventory is already where the save left it.\n    bSyncing = true;\n    bSilent = true;\n    for (int32 i = 0, Steps = 0; i < Path.Num() && Steps < 10000; ++Steps)\n    {\n        const FString Before = Ink->ToJson();\n        while (Ink->CanContinue())\n        {\n            NotePassage();\n            Ink->Continue();\n        }\n        if (Path[i].StartsWith(JumpMark, ESearchCase::CaseSensitive))\n        {\n            // A jump the game made with ResumeAt.\n            const FString Target = Path[i].Mid(JumpMark.Len());\n            if (!IsStartPoint(Target)) break;\n            Ink->GoTo(InkPathOf(StoryInfo(), Target));\n            LastPassage = PassageOfName(Target);\n            ChoicePath.Add(Path[i]);\n            ++Followed;\n            ++i;\n            continue;\n        }\n        const TArray<FNarrativeInkChoice> Choices = InkChoices(Ink);\n        const FString& Wanted = Path[i];\n        const FNarrativeInkChoice* Match = Choices.FindByPredicate([&Wanted](const FNarrativeInkChoice& C) { return C.Text == Wanted; });\n        if (Match)\n        {\n            Ink->Choose(Match->Index);\n            ChoicePath.Add(Wanted);\n            ++Followed;\n            ++i;\n        }\n        else if (IsWaitingForContinue())\n        {\n            // A Continue break added since the save: take it.\n            Ink->Choose(0);\n            ChoicePath.Add(NarrativeBridge::ContinueText);\n        }\n        else if (Wanted == NarrativeBridge::ContinueText)\n        {\n            // A Continue break removed since the save: skip it.\n            ++Followed;\n            ++i;\n        }\n        else\n        {\n            Ink->LoadJson(Before);\n            break;\n        }\n    }\n    bSyncing = false;\n    bSilent = false;\n    OnRestarted.Broadcast();\n    RaiseAllVariables();\n    LoadNote = Followed == Path.Num()\n        ? FString::Printf(TEXT(\"Carried this save over from story version %s: all %d choices replayed.\"), *SavedVersion, Path.Num())\n        : FString::Printf(TEXT(\"Carried this save over from story version %s: %d of %d choices still exist, so it resumes after the last one that does.\"), *SavedVersion, Followed, Path.Num());\n    Advance();\n}\n\nbool UNarrativeBridgeComponent::ReadSlot(int32 Slot, FString& Data) const\n{\n    Data.Reset();\n    if (SaveStorage && SaveStorage->Implements<UNarrativeSaveStorage>()) return INarrativeSaveStorage::Execute_ReadSave(SaveStorage, SlotKey(Slot), Data) && !Data.IsEmpty();\n    return FFileHelper::LoadFileToString(Data, *SaveFile(StoryInfo(), SlotKey(Slot)), FFileHelper::EHashOptions::None, FILEREAD_Silent) && !Data.IsEmpty();\n}\n\nvoid UNarrativeBridgeComponent::WriteSlot(int32 Slot, const FString& Data)\n{\n    if (SaveStorage && SaveStorage->Implements<UNarrativeSaveStorage>()) { INarrativeSaveStorage::Execute_WriteSave(SaveStorage, SlotKey(Slot), Data); return; }\n    // Write a new file and swap it in, so a crash mid-save never leaves half a save.\n    const FString File = SaveFile(StoryInfo(), SlotKey(Slot));\n    const FString Temp = File + TEXT(\".tmp\");\n    if (!FFileHelper::SaveStringToFile(Data, *Temp, FFileHelper::EEncodingOptions::ForceUTF8WithoutBOM) || !IFileManager::Get().Move(*File, *Temp, true))\n        ReportError(FString::Printf(TEXT(\"Could not save to %s.\"), *File));\n}\n\nvoid UNarrativeBridgeComponent::SaveToSlot(int32 Slot)\n{\n    if (!Ink.IsValid()) return;\n    WriteSlot(Slot, SaveState());\n    if (Slot != AutosaveSlot) SetStatus(FString::Printf(TEXT(\"Saved to slot %d.\"), Slot));\n    OnSaved.Broadcast(Slot);\n}\n\nbool UNarrativeBridgeComponent::LoadFromSlot(int32 Slot)\n{\n    FString Data;\n    if (!ReadSlot(Slot, Data)) { SetStatus(TEXT(\"That slot is empty.\")); return false; }\n    FString Error;\n    const bool bOk = TryLoadState(Data, Error);\n    SetStatus(bOk ? (LoadNote.IsEmpty() ? (Slot == AutosaveSlot ? FString(TEXT(\"Loaded the autosave.\")) : FString::Printf(TEXT(\"Loaded slot %d.\"), Slot)) : LoadNote) : Error);\n    AutosavedPassage = GetCurrentPassage();\n    return bOk;\n}\n\nvoid UNarrativeBridgeComponent::DeleteSlot(int32 Slot)\n{\n    if (SaveStorage && SaveStorage->Implements<UNarrativeSaveStorage>()) INarrativeSaveStorage::Execute_DeleteSave(SaveStorage, SlotKey(Slot));\n    else IFileManager::Get().Delete(*SaveFile(StoryInfo(), SlotKey(Slot)), false, false, true);\n}\n\nFNarrativeSlotInfo UNarrativeBridgeComponent::GetSlot(int32 Slot) const\n{\n    FNarrativeSlotInfo Info;\n    Info.Slot = Slot;\n    FString Raw;\n    if (!ReadSlot(Slot, Raw)) return Info;\n    TSharedPtr<FJsonObject> Data;\n    FString InkState;\n    if (!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Raw), Data) || !Data.IsValid() || !Data->TryGetStringField(TEXT(\"inkState\"), InkState) || InkState.IsEmpty()) return Info;\n    Info.bExists = true;\n    FString SavedAt, Version;\n    Data->TryGetStringField(TEXT(\"savedAt\"), SavedAt);\n    FDateTime::ParseIso8601(*SavedAt, Info.SavedAt);\n    Data->TryGetStringField(TEXT(\"passage\"), Info.Passage);\n    Info.PassageTitle = Info.Passage;\n    for (const FNarrativeStoryPassage& P : StoryInfo().Passages)\n        if (Info.Passage == P.Id) Info.PassageTitle = UNarrativeLocalization::Translate(P.Title);\n    Data->TryGetStringField(TEXT(\"excerpt\"), Info.Excerpt);\n    Data->TryGetStringField(TEXT(\"storyVersion\"), Version);\n    Info.bOtherVersion = Version != StoryInfo().StoryVersion;\n    return Info;\n}\n\nTArray<FNarrativeSlotInfo> UNarrativeBridgeComponent::GetSlots() const\n{\n    TArray<FNarrativeSlotInfo> Slots;\n    for (int32 i = 0; i <= SaveSlots; ++i) Slots.Add(GetSlot(i));\n    return Slots;\n}\n\nvoid UNarrativeBridgeComponent::QuickSave()\n{\n    if (!Ink.IsValid()) return;\n    WriteSlot(-1, SaveState());\n    SetStatus(TEXT(\"Saved.\"));\n}\n\nbool UNarrativeBridgeComponent::QuickLoad()\n{\n    FString Data, Error;\n    if (!ReadSlot(-1, Data)) { SetStatus(TEXT(\"There is no save yet.\")); return false; }\n    const bool bOk = TryLoadState(Data, Error);\n    SetStatus(bOk ? (LoadNote.IsEmpty() ? FString(TEXT(\"Loaded.\")) : LoadNote) : Error);\n    return bOk;\n}\n\nvoid UNarrativeBridgeComponent::AutosaveIfNewPassage()\n{\n    // Only while the game plays (not in the editor's automation tests).\n    const UWorld* World = GetWorld();\n    if (!bAutosave || bSilent || !Ink.IsValid() || !World || !World->IsGameWorld()) return;\n    const FString Passage = GetCurrentPassage();\n    if (Passage.IsEmpty() || Passage == AutosavedPassage) return;\n    AutosavedPassage = Passage;\n    SaveToSlot(AutosaveSlot);\n}\n\nvoid UNarrativeBridgeComponent::ReportError(const FString& Message)\n{\n    UE_LOG(LogTemp, Error, TEXT(\"[NarrativeBridge] %s\"), *Message);\n    SetStatus(Message);\n    OnRuntimeError.Broadcast(Message);\n}\n\nvoid UNarrativeBridgeComponent::SetStatus(const FString& Message)\n{\n    Status = Message;\n    OnStatusChanged.Broadcast(Status);\n}\n\n// ---- Text helpers ------------------------------------------------------------------------\n\nFString UNarrativeBridgeComponent::PlainText(const FString& Text)\n{\n    static const TCHAR* EmphasisTags[] = { TEXT(\"<i>\"), TEXT(\"</i>\"), TEXT(\"<b>\"), TEXT(\"</b>\"), TEXT(\"<u>\"), TEXT(\"</u>\") };\n    FString Out = Text;\n    for (const TCHAR* Tag : EmphasisTags) Out.ReplaceInline(Tag, TEXT(\"\"), ESearchCase::CaseSensitive);\n    return Out;\n}\n\nFString UNarrativeBridgeComponent::RichText(const FString& Text)\n{\n    static const TCHAR* Closing[] = { TEXT(\"</i>\"), TEXT(\"</b>\"), TEXT(\"</u>\") };\n    FString Out = Text;\n    for (const TCHAR* Tag : Closing) Out.ReplaceInline(Tag, TEXT(\"</>\"), ESearchCase::CaseSensitive);\n    return Out;\n}\n\n// ---- Pictures and sound ------------------------------------------------------------------\n\nUTexture2D* UNarrativeBridgeComponent::LoadPicture(const FString& File)\n{\n    if (File.IsEmpty()) return nullptr;\n    if (const TStrongObjectPtr<UTexture2D>* Cached = Pictures().Find(File)) return Cached->Get();\n    TArray<uint8> Bytes;\n    if (!FFileHelper::LoadFileToArray(Bytes, *(FPaths::ProjectContentDir() / NarrativeBridge::ImageFolder / File), FILEREAD_Silent)) return nullptr;\n    UTexture2D* Texture = FImageUtils::ImportBufferAsTexture2D(Bytes);\n    if (!Texture) return nullptr;\n    Pictures().Add(File, TStrongObjectPtr<UTexture2D>(Texture));\n    return Texture;\n}\n\nFString UNarrativeBridgeComponent::PortraitFile(const FString& SpeakerId)\n{\n    for (const FNarrativeStoryPortrait& P : UNarrativeStoryData::DefaultInfo().Portraits)\n        if (SpeakerId == P.Speaker) return P.File;\n    return FString();\n}\n\nUTexture2D* UNarrativeBridgeComponent::LoadPortrait(const FString& SpeakerId)\n{\n    return LoadPicture(PortraitFile(SpeakerId));\n}\n\nFString UNarrativeBridgeComponent::ClipAssetName(const FString& File)\n{\n    FString Name = FPaths::GetBaseFilename(File);\n    for (TCHAR& Ch : Name)\n        if (!FChar::IsAlnum(Ch) && Ch != TEXT('_')) Ch = TEXT('_');\n    return Name;\n}\n\nUSoundBase* UNarrativeBridgeComponent::LoadVoiceClip(const FString& File)\n{\n    if (File.IsEmpty()) return nullptr;\n    const FString Name = ClipAssetName(File);\n    const FString Path = FString(NarrativeBridge::AudioPackagePath) + Name + TEXT(\".\") + Name;\n    return LoadObject<USoundBase>(nullptr, *Path, nullptr, LOAD_NoWarn | LOAD_Quiet);\n}\n\nvoid UNarrativeBridgeComponent::ReleaseLoadedMedia()\n{\n    Pictures().Reset();\n}\n\nvoid UNarrativeBridgeComponent::QueueVoice(const FNarrativeLine& Line)\n{\n    if (!bPlayVoiceClips || Line.VoiceClip.IsEmpty() || !GetWorld()) return;\n    if (USoundBase* Clip = LoadVoiceClip(Line.VoiceClip)) VoiceQueue.Add(Clip);\n    else UE_LOG(LogTemp, Warning, TEXT(\"[NarrativeBridge] No voice clip %s in %s (import StorySource/VoiceClips).\"), *Line.VoiceClip, NarrativeBridge::AudioPackagePath);\n}\n\nvoid UNarrativeBridgeComponent::StopVoice()\n{\n    VoiceQueue.Reset();\n    if (VoicePlaying) VoicePlaying->Stop();\n    VoicePlaying = nullptr;\n}\n\nvoid UNarrativeBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)\n{\n    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);\n    // Voice clips play in order: the next when the last has finished.\n    if (VoiceQueue.Num() == 0 || (VoicePlaying && VoicePlaying->IsPlaying())) return;\n    USoundBase* Next = VoiceQueue[0];\n    VoiceQueue.RemoveAt(0);\n    VoicePlaying = Next ? UGameplayStatics::SpawnSound2D(this, Next, VoiceVolume * UNarrativeSettings::GetVoiceVolume()) : nullptr;\n}\n";

/** templates/unreal/Component.h */
export const COMPONENT_H = "// Generated by Narrative Bridge. The story, as a Blueprint-friendly component on any actor.\n// Reaches the Ink runtime only through FNarrativeInk (NarrativeBridgeInk.h); npm run test:unreal:build builds it with Unreal Engine.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"NarrativeBridgeInk.h\"\n#include \"NarrativeBridgeInkCompat.h\"\n#include \"NarrativeBridgeStoryData.h\"\n#include \"NarrativeBridgeTypes.h\"\n#include \"NarrativeBridgeComponent.generated.h\"\n\nclass UAudioComponent;\nclass USoundBase;\nclass UTexture2D;\n\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_ThreeParams(FNarrativeLineSpoken, const FString&, Speaker, const FString&, Text, const TArray<FString>&, Tags);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FNarrativeLineShown, const FNarrativeLine&, Line);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FNarrativeChoices, const TArray<FString>&, Choices);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE(FNarrativeMoment);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FNarrativeCue, const FString&, Name, const FString&, Value);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FNarrativeWords, const FString&, Text);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FNarrativeVariable, const FString&, Name, const FString&, Value);\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FNarrativeSaved, int32, Slot);\n\n/**\n * Runs the story: advances text, presents choices and Continue breaks, hands over to the game at exits,\n * exposes the story's variables, keeps your game's inventory in step, translates, plays voice clips, and saves (with save\n * slots, an autosave and story-version carry-over). The Narrative Story Widget draws it as a themed story panel; your own\n * UI and game systems can use the events below instead.\n */\nUCLASS(ClassGroup = (NarrativeBridge), meta = (BlueprintSpawnableComponent, DisplayName = \"Narrative Bridge\"))\nclass __API__ UNarrativeBridgeComponent : public UActorComponent\n{\n    GENERATED_BODY()\n\npublic:\n    UNarrativeBridgeComponent();\n\n    /** The story asset (an Inkpot story asset). Empty: the one imported from StorySource/MainStory.ink (Content/NarrativeBridge/MainStory). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\", meta = (AllowedClasses = \"/Script/Inkpot.InkpotStoryAsset\"))\n    TObjectPtr<UObject> StoryAsset;\n\n    /** The story's data (passages, lines, items, locked choices). Empty: the one imported from StorySource/StoryInfo.json (Content/NarrativeBridge/StoryData). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TObjectPtr<UNarrativeStoryData> StoryData;\n\n    /** Start when play begins. Turn off to start it yourself with StartStory or StartAt. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bStartOnBeginPlay = true;\n\n    /** Optional: an object implementing Narrative Inventory Authority, so your game owns the items. Empty: the owner, or one of its components, if it implements it. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TObjectPtr<UObject> InventoryAuthority;\n\n    /** Play the recorded dialogue clips (#audio tags) that come with the story. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Voice\")\n    bool bPlayVoiceClips = true;\n\n    /** Volume of the voice clips (the story panel sets it from its theme; the player's Settings scale it). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Voice\", meta = (ClampMin = \"0\", ClampMax = \"1\"))\n    float VoiceVolume = 1.f;\n\n    /** Save slots the story panel's Save and Load offer. 0 keeps the single quick save (QuickSave / QuickLoad). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Saves\", meta = (ClampMin = \"0\", ClampMax = \"9\"))\n    int32 SaveSlots = 3;\n\n    /** Keep an autosave (slot 0) each time the reader reaches a new passage. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Saves\")\n    bool bAutosave = true;\n\n    /** Optional: an object implementing Narrative Save Storage, for your game's own saves. Empty: JSON files in Saved/SaveGames/NarrativeBridge. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Saves\")\n    TObjectPtr<UObject> SaveStorage;\n\n    /** A line of the story: the speaker (empty for narration), the text and its tags. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeLineSpoken OnLine;\n\n    /** A line of the story with everything about it: scene, stage direction, picture, voice clip… */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeLineShown OnLineShown;\n\n    /** Choices are waiting (their text, in the current language): call Choose. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeChoices OnChoices;\n\n    /** A Continue break is waiting: call Continue. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeMoment OnContinue;\n\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeMoment OnEnded;\n\n    /** The transcript was cleared (start, restart or load): redraw from scratch. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeMoment OnRestarted;\n\n    /** A cue the writer added (#music:calm gives \"music\", \"calm\"): play music or a sound, shake the camera… The Narrative Cue Player does it without code. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeCue OnCue;\n\n    /** A tag the story uses that Narrative Bridge doesn't, as written (e.g. \"music:calm\"). */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeWords OnTag;\n\n    /** A story variable or item changed: its name and new value. Raised for every one after a load. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeVariable OnVariableChanged;\n\n    /** The dialogue reached an exit to the game (its name, one of GetExits): play your gameplay, then call Resume or ResumeAt. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeWords OnExit;\n\n    /** The game resumed the dialogue after an exit. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeMoment OnResumed;\n\n    /** A message for the player (Saved., Loaded slot 2., an error…). */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeWords OnStatusChanged;\n\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeWords OnRuntimeError;\n\n    /** A slot was saved (its number; 0 for the autosave). */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge|Saves\")\n    FNarrativeSaved OnSaved;\n\n    /** The autosave's slot number; the player's slots are 1 to SaveSlots. */\n    static constexpr int32 AutosaveSlot = 0;\n\n    /** Starts (or restarts) the story from the beginning. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void StartStory();\n\n    /**\n     * Starts (or restarts) the story at a passage, e.g. when the player talks to someone (see GetPassages),\n     * or at a line of dialogue in one, \"passage.line_…\" (see GetLines), to pick a conversation up partway.\n     */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void StartAt(const FString& Passage);\n\n    /**\n     * Enters the dialogue at a passage or a line of dialogue (\"passage.line_…\"), e.g. when the player talks to someone again:\n     * the page starts afresh there, but the story keeps what it knows (its variables and items). The first time, it's StartAt.\n     */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void EnterAt(const FString& Name);\n\n    /** Whether the story can start at (or jump to) this name: one of GetPassages or GetLines. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool IsStartPoint(const FString& Name) const;\n\n    /** Whether the player has an item (an item id, without \"has_\"): your inventory's answer, or the story's. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool HasItem(const FString& ItemId) const;\n\n    /** Takes one of the choices (by its index in OnChoices). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Choose(int32 Index);\n\n    /** Goes on past a Continue break. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Continue();\n\n    /** Goes on after an exit to the game, from where the dialogue left off. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Resume();\n\n    /** Goes on at another passage or line (after a lost fight, say), keeping the story's variables and items. Works away from an exit too. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void ResumeAt(const FString& Passage);\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool IsStarted() const { return Ink.IsValid(); }\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool HasEnded() const { return bHasEnded; }\n\n    /** The story is at a Continue break: its only choice is Continue. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool IsWaitingForContinue() const;\n\n    /** The dialogue has handed over to the game and waits for Resume or ResumeAt. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool IsAtExit() const { return !GetCurrentExit().IsEmpty(); }\n\n    /** The exit to the game the dialogue is waiting at, or empty. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetCurrentExit() const;\n\n    /** The choices on offer, in the current language (empty at a Continue break, an exit or the ending). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    TArray<FString> GetChoices() const;\n\n    /** The choices on offer as the story has them (not translated), e.g. to match PlaythroughRoutes. */\n    TArray<FString> GetSourceChoices() const;\n\n    /** The current passage's choices that need an item or a value the reader doesn't have: show them greyed out if you like. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    TArray<FNarrativeLockedChoice> GetLockedChoices() const;\n\n    /** The passage (one of GetPassages) the reader is in, or empty before the story starts. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetCurrentPassage() const;\n\n    /**\n     * True if the player has taken choice Index (as in OnChoices) before, in this read or an earlier one: the story panel\n     * greys these out but keeps them clickable. Kept in Saved/SaveGames/NarrativeBridge through Restart; a choice is\n     * known by its passage and its text.\n     */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool WasChosen(int32 Index) const;\n\n    /** Forgets which choices were taken before, so every choice looks new again. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void ForgetChosen();\n\n    /** The passage or line the story was started at (StartAt), or empty when it started from the beginning. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetStartPassage() const { return StartPassage; }\n\n    /** Every line so far (and the choices made), in the current language. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    const TArray<FNarrativeLine>& GetTranscript() const { return Transcript; }\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetStatus() const { return Status; }\n\n    /** The picture of the scene the reader is in: the latest #image in the transcript, or empty. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetCurrentPicture() const;\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetStoryVersion() const;\n\n    /** The story's data: StoryData, or the default one imported from StorySource/. */\n    const FNarrativeStoryInfo& StoryInfo() const;\n\n    /** Every passage (Ink knot) the story can start at: StartAt, EnterAt and ResumeAt take these. Use it to fill a dropdown. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    TArray<FString> GetPassages() const;\n\n    /** Every line of dialogue the story can start at, \"passage.line_…\". */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    TArray<FString> GetLines() const;\n\n    /** The story's acts (groups of passages), in order. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    TArray<FString> GetActs() const;\n\n    /** The act a passage is in, or an empty string when it's in none. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetActOf(const FString& Passage) const;\n\n    /** An act's title (for chapter menus and save slots), or an empty string for an unknown act. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetActTitle(const FString& Act) const;\n\n    /** The story's exits to the game: OnExit gives their names. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    TArray<FString> GetExits() const;\n\n    /** The running story's runtime, for C++ that needs more than the functions here (null before the story starts). */\n    const FNarrativeInk* GetInk() const { return Ink.Get(); }\n\n    /** A story variable or item (one of the story's variables or items). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\")\n    FNarrativeValue GetStoryValue(const FString& Name, bool& bFound) const;\n\n    /** A true/false variable or item; false when it doesn't exist or isn't one. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\")\n    bool GetBool(const FString& Name) const;\n\n    /** A whole-number variable; 0 when it doesn't exist or isn't a number. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\")\n    int32 GetInt(const FString& Name) const;\n\n    /** A number variable; 0 when it doesn't exist or isn't a number. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\")\n    float GetFloat(const FString& Name) const;\n\n    /** A text variable; empty when it doesn't exist or isn't text. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\")\n    FString GetString(const FString& Name) const;\n\n    /** A story variable or item as text (\"true\", \"3\", \"calm\"), or empty. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\")\n    FString GetVariableAsString(const FString& Name) const;\n\n    /** Sets one of the story's own variables (the story's own variables). False when it isn't one. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\")\n    bool SetStoryValue(const FString& Name, const FNarrativeValue& Value);\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\")\n    bool SetBool(const FString& Name, bool bValue) { return SetStoryValue(Name, FNarrativeValue::FromBool(bValue)); }\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\")\n    bool SetInt(const FString& Name, int32 Value) { return SetStoryValue(Name, FNarrativeValue::FromInt(Value)); }\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\")\n    bool SetFloat(const FString& Name, float Value) { return SetStoryValue(Name, FNarrativeValue::FromFloat(Value)); }\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\")\n    bool SetString(const FString& Name, const FString& Value) { return SetStoryValue(Name, FNarrativeValue::FromString(Value)); }\n\n    /** Whether a name is one of the story's variables (or, for reading, its items). */\n    bool CanAccessVariable(const FString& Name, bool bWrite) const;\n\n    /** Deprecated: use GetStoryValue. Kept so Blueprints made before the Ink runtime moved behind FNarrativeInk still work. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Variables\", meta = (DeprecatedFunction, DeprecationMessage = \"Use Get Story Value, or Get Bool / Get Int / Get Float / Get String.\"))\n    FInkpotValue GetVariable(const FString& Name, bool& bFound) const;\n\n    /** Deprecated: use SetStoryValue. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\", meta = (DeprecatedFunction, DeprecationMessage = \"Use Set Story Value, or Set Bool / Set Int / Set Float / Set String.\"))\n    bool SetVariable(const FString& Name, const FInkpotValue& Value);\n\n    /** Deprecated: the runtime's own story object. Use GetInk() from C++. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\", meta = (DeprecatedFunction, DeprecationMessage = \"Use the story component's own functions.\"))\n    UInkpotStory* GetInkpotStory() const;\n\n    /** Host-authoritative inventory: push the game's item state into Ink before continuing. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Variables\")\n    void SetItemOwned(const FString& ItemId, bool bOwned);\n\n    // ---- Saves ----\n\n    /** The story's state as text, to keep in your own save system. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    FString SaveState() const;\n\n    /** Restores SaveState's text. A save from an earlier version of the story is carried over by replaying its choices (see GetLoadNote). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    bool TryLoadState(const FString& Save, FString& Error);\n\n    /** What happened when the last save was carried over from another story version; empty otherwise. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Saves\")\n    FString GetLoadNote() const { return LoadNote; }\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    void SaveToSlot(int32 Slot);\n\n    /** Loads a slot; false (with the reason in GetStatus) when it's empty or can't be loaded. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    bool LoadFromSlot(int32 Slot);\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    void DeleteSlot(int32 Slot);\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    FNarrativeSlotInfo GetSlot(int32 Slot) const;\n\n    /** The autosave and every player slot, in order (slot 0 is the autosave). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    TArray<FNarrativeSlotInfo> GetSlots() const;\n\n    /** The single quick save (what Save and Load use with Save Slots at 0). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    void QuickSave();\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Saves\")\n    bool QuickLoad();\n\n    // ---- Text, pictures and sound ----\n\n    /** A line without its emphasis tags (<i>, <b>, <u>), for a plain Text Block. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Text\")\n    static FString PlainText(const FString& Text);\n\n    /** A line for a Rich Text Block whose text style set has rows named i, b and u (closing tags become </>). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Text\")\n    static FString RichText(const FString& Text);\n\n    /** Puts the transcript into the current language again (done by itself when the language changes). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Text\")\n    void Relocalize();\n\n    /** The picture for an #image file name (decoded from Content/NarrativeBridge/Data/Images and kept), or null. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Media\")\n    static UTexture2D* LoadPicture(const FString& File);\n\n    /** A character's portrait file name, by speaker id (FNarrativeLine::SpeakerId), or empty. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Media\")\n    static FString PortraitFile(const FString& SpeakerId);\n\n    /** A character's portrait, by speaker id, or null if they have none. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Media\")\n    static UTexture2D* LoadPortrait(const FString& SpeakerId);\n\n    /** A voice clip or cue sound by its file name (imported into Content/NarrativeBridge/Audio), or null. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Media\")\n    static USoundBase* LoadVoiceClip(const FString& File);\n\n    /** The asset name a clip is imported as (its file name without the extension, made safe for Unreal). */\n    static FString ClipAssetName(const FString& File);\n\n    /** Lets go of every picture loaded so far (they load again when needed). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Media\")\n    static void ReleaseLoadedMedia();\n\n    virtual void TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction) override;\n\nprotected:\n    virtual void BeginPlay() override;\n    virtual void EndPlay(const EEndPlayReason::Type Reason) override;\n\nprivate:\n    void Begin(const FString& Passage);\n    void Advance();\n    void Announce();\n    void RaiseTags(const TArray<FString>& Tags);\n    void NotePassage();\n    void AutosaveIfNewPassage();\n    void ReplayChoices(const TArray<FString>& Path, const FString& SavedVersion);\n    void RaiseAllVariables();\n    void SyncFromAuthority();\n    void ReportError(const FString& Message);\n    void SetStatus(const FString& Message);\n    void QueueVoice(const FNarrativeLine& Line);\n    void StopVoice();\n    FString Excerpt() const;\n    UObject* Authority() const;\n    bool ReadSlot(int32 Slot, FString& Data) const;\n    void WriteSlot(int32 Slot, const FString& Data);\n    FNarrativeLine ParseLine(const FString& Raw, const TArray<FString>& Tags) const;\n    static FNarrativeLine Localize(FNarrativeLine Line);\n\n    void HandleVariableChange(const FString& Variable, const FNarrativeValue& NewValue);\n\n    TSharedPtr<FNarrativeInk> Ink;\n\n    UPROPERTY(Transient)\n    TObjectPtr<UAudioComponent> VoicePlaying;\n\n    UPROPERTY(Transient)\n    TArray<TObjectPtr<USoundBase>> VoiceQueue;\n\n    /** Choices taken before (\"passage|text\"), loaded from disk the first time they're needed. */\n    mutable TSet<FString> ChosenBefore;\n    mutable bool bChosenLoaded = false;\n    const TSet<FString>& Chosen() const;\n\n    TArray<FNarrativeLine> Transcript;\n    /** The text of every choice made since the start (and the jumps, as \"→passage\"), so a save carries over to a revised story. */\n    TArray<FString> ChoicePath;\n    FString StartPassage;\n    FString LastPassage;\n    FString AutosavedPassage;\n    FString Status;\n    FString LoadNote;\n    FDelegateHandle LanguageHandle;\n    bool bHasEnded = false;\n    bool bSyncing = false;\n    bool bSilent = false;\n};\n";

/** templates/unreal/Condition.h */
export const CONDITION_H = "// Generated by Narrative Bridge. The conditions of locked choices (has_item, not, and, or, compare) as a tree the story\n// data holds, and the evaluator that walks it. Plain C++: no Unreal types beyond FString and TArray, so\n// npm run test:unreal compiles it. It gives the same answers as the TypeScript evaluator (conditionHolds in gating.ts);\n// the NarrativeBridge.StoryData automation test checks that for every locked choice.\n#pragma once\n\n#include \"CoreMinimal.h\"\n\n/** Reads the story's variables for a locked choice's conditions (the story component gives one). */\nstruct FNarrativeVariableReader\n{\n    virtual ~FNarrativeVariableReader() = default;\n    /** Whether a variable is true (items are Ink Booleans named has_<item>). */\n    virtual bool Has(const TCHAR* Name) const = 0;\n    virtual bool CompareNumber(const TCHAR* Name, const TCHAR* Op, double Value) const = 0;\n    virtual bool CompareText(const TCHAR* Name, const TCHAR* Op, const TCHAR* Value) const = 0;\n    virtual bool CompareBool(const TCHAR* Name, const TCHAR* Op, bool Value) const = 0;\n};\n\n/** One node of a condition tree. */\nstruct FNarrativeCondition\n{\n    enum class EKind { HasItem, Not, And, Or, Compare };\n    enum class EOperand { Number, Text, Bool };\n\n    EKind Kind = EKind::And;\n    /** HasItem: the Ink variable (has_<item>). Compare: the variable compared. */\n    FString Variable;\n    /** Compare: ==, !=, <, <=, > or >=. */\n    FString Op;\n    EOperand Operand = EOperand::Number;\n    double Number = 0;\n    FString Text;\n    bool bBool = false;\n    /** Not: the one condition negated. And, Or: all of them. */\n    TArray<FNarrativeCondition> Children;\n\n    bool Evaluate(const FNarrativeVariableReader& V) const\n    {\n        switch (Kind)\n        {\n        case EKind::HasItem:\n            return V.Has(*Variable);\n        case EKind::Not:\n            return Children.Num() > 0 ? !Children[0].Evaluate(V) : true;\n        case EKind::And:\n            for (int32 i = 0; i < Children.Num(); ++i)\n                if (!Children[i].Evaluate(V)) return false;\n            return true;\n        case EKind::Or:\n            for (int32 i = 0; i < Children.Num(); ++i)\n                if (Children[i].Evaluate(V)) return true;\n            return false;\n        case EKind::Compare:\n            switch (Operand)\n            {\n            case EOperand::Text: return V.CompareText(*Variable, *Op, *Text);\n            case EOperand::Bool: return V.CompareBool(*Variable, *Op, bBool);\n            default: return V.CompareNumber(*Variable, *Op, Number);\n            }\n        }\n        return false;\n    }\n};\n";

/** templates/unreal/CuePlayer.cpp */
export const CUE_PLAYER_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeCuePlayer.h\"\n#include \"NarrativeBridgeStoryData.h\"\n#include \"Camera/CameraShakeBase.h\"\n#include \"Camera/PlayerCameraManager.h\"\n#include \"Components/AudioComponent.h\"\n#include \"Engine/World.h\"\n#include \"GameFramework/PlayerController.h\"\n#include \"Kismet/GameplayStatics.h\"\n#include \"Sound/SoundBase.h\"\n\nUNarrativeCuePlayerComponent::UNarrativeCuePlayerComponent()\n{\n    PrimaryComponentTick.bCanEverTick = false;\n}\n\nvoid UNarrativeCuePlayerComponent::OnRegister()\n{\n    Super::OnRegister();\n    // The first time, list every cue in the story with a likely action.\n    if (Cues.Num() == 0)\n        for (const FString& Name : UNarrativeStoryData::DefaultInfo().Cues)\n        {\n            FNarrativeCueSetup Cue;\n            Cue.Name = Name;\n            Cue.Action = Guess(Cue.Name);\n            Cues.Add(Cue);\n        }\n}\n\nvoid UNarrativeCuePlayerComponent::BeginPlay()\n{\n    Super::BeginPlay();\n    Story = GetOwner() ? GetOwner()->FindComponentByClass<UNarrativeBridgeComponent>() : nullptr;\n    if (Story) Story->OnCue.AddDynamic(this, &UNarrativeCuePlayerComponent::HandleCue);\n    else UE_LOG(LogTemp, Warning, TEXT(\"[NarrativeBridge] The Narrative Cue Player on %s has no Narrative Bridge component next to it.\"), *GetNameSafe(GetOwner()));\n}\n\nvoid UNarrativeCuePlayerComponent::EndPlay(const EEndPlayReason::Type Reason)\n{\n    if (Story) Story->OnCue.RemoveDynamic(this, &UNarrativeCuePlayerComponent::HandleCue);\n    Super::EndPlay(Reason);\n}\n\nvoid UNarrativeCuePlayerComponent::HandleCue(const FString& Name, const FString& Value)\n{\n    PlayCue(Name, Value);\n}\n\nvoid UNarrativeCuePlayerComponent::PlayCue(const FString& Name, const FString& Value)\n{\n    OnAnyCue.Broadcast(Name, Value);\n    const FString Tag = Value.IsEmpty() ? Name : Name + TEXT(\":\") + Value;\n    for (const FNarrativeCueSetup& Cue : Cues)\n        if (Cue.Name.Equals(Name, ESearchCase::IgnoreCase)) Run(Cue, Value, Tag);\n}\n\nFString UNarrativeCuePlayerComponent::StorySound(const FString& Tag)\n{\n    for (const FNarrativeStoryCueSound& Sound : UNarrativeStoryData::DefaultInfo().CueSounds)\n        if (Tag == Sound.Tag) return Sound.File;\n    return FString();\n}\n\nUSoundBase* UNarrativeCuePlayerComponent::PickSound(const FNarrativeCueSetup& Cue, const FString& Value, const FString& Tag) const\n{\n    // The cue's own sound named by the value; else the writer's sound for this cue; else the cue's first sound.\n    if (!Value.IsEmpty())\n        for (USoundBase* S : Cue.Sounds)\n            if (S && S->GetName().Equals(Value, ESearchCase::IgnoreCase)) return S;\n    if (bPlayStorySounds)\n        if (USoundBase* Writers = UNarrativeBridgeComponent::LoadVoiceClip(StorySound(Tag))) return Writers;\n    for (USoundBase* S : Cue.Sounds)\n        if (S) return S;\n    return nullptr;\n}\n\nvoid UNarrativeCuePlayerComponent::Run(const FNarrativeCueSetup& Cue, const FString& Value, const FString& Tag)\n{\n    switch (Cue.Action)\n    {\n    case ENarrativeCueAction::PlayMusic:\n        // A music cue with no value stops the music.\n        if (Value.IsEmpty()) StopMusic();\n        else PlayMusic(PickSound(Cue, Value, Tag), Cue.Volume);\n        break;\n    case ENarrativeCueAction::StopMusic:\n        StopMusic();\n        break;\n    case ENarrativeCueAction::PlaySound:\n        if (USoundBase* Sound = PickSound(Cue, Value, Tag)) UGameplayStatics::PlaySound2D(this, Sound, Cue.Volume);\n        break;\n    case ENarrativeCueAction::PlayAmbience:\n    {\n        // An ambience cue with no value stops the ambience.\n        if (Value.IsEmpty()) { if (Ambience) Ambience->Stop(); break; }\n        USoundBase* Loop = PickSound(Cue, Value, Tag);\n        if (!Loop || (Ambience && Ambience->Sound == Loop && Ambience->IsPlaying())) break;\n        if (Ambience) Ambience->Stop();\n        Ambience = UGameplayStatics::SpawnSound2D(this, Loop, Cue.Volume, 1.f, 0.f, nullptr, true, false);\n        if (Ambience) Ambience->OnAudioFinished.AddDynamic(this, &UNarrativeCuePlayerComponent::HandleAmbienceFinished);\n        break;\n    }\n    case ENarrativeCueAction::StopAmbience:\n        if (Ambience) Ambience->Stop();\n        Ambience = nullptr;\n        break;\n    case ENarrativeCueAction::ShakeCamera:\n        Shake(Value.IsEmpty() ? 0.5f : FMath::Clamp(FCString::Atof(*Value), 0.f, 1.f));\n        break;\n    default:\n        break;\n    }\n}\n\nvoid UNarrativeCuePlayerComponent::HandleAmbienceFinished()\n{\n    // Ambience loops until another cue stops it.\n    if (Ambience) Ambience->Play();\n}\n\nvoid UNarrativeCuePlayerComponent::PlayMusic(USoundBase* Sound, float Volume)\n{\n    if (!Sound || (Music && Music->Sound == Sound && Music->IsPlaying())) return;\n    const float Half = MusicFade * 0.5f;\n    if (Music) Music->FadeOut(Half, 0.f);\n    Music = UGameplayStatics::SpawnSound2D(this, Sound, Volume, 1.f, 0.f, nullptr, true, true);\n    if (Music && Half > 0.f)\n    {\n        Music->Stop();\n        Music->FadeIn(Half, Volume);\n    }\n}\n\nvoid UNarrativeCuePlayerComponent::StopMusic()\n{\n    if (Music) Music->FadeOut(MusicFade * 0.5f, 0.f);\n    Music = nullptr;\n}\n\nUSoundBase* UNarrativeCuePlayerComponent::GetCurrentMusic() const\n{\n    return Music && Music->IsPlaying() ? Music->Sound.Get() : nullptr;\n}\n\nvoid UNarrativeCuePlayerComponent::Shake(float Strength)\n{\n    if (!ShakeClass) return;\n    APlayerController* Player = GetWorld() ? GetWorld()->GetFirstPlayerController() : nullptr;\n    if (Player && Player->PlayerCameraManager) Player->PlayerCameraManager->StartCameraShake(ShakeClass, Strength);\n}\n\nENarrativeCueAction UNarrativeCuePlayerComponent::Guess(const FString& Name)\n{\n    const FString N = Name.ToLower();\n    if (N.Contains(TEXT(\"stop_music\")) || N == TEXT(\"silence\")) return ENarrativeCueAction::StopMusic;\n    if (N.Contains(TEXT(\"stop_ambience\"))) return ENarrativeCueAction::StopAmbience;\n    if (N.Contains(TEXT(\"music\")) || N == TEXT(\"song\") || N == TEXT(\"track\")) return ENarrativeCueAction::PlayMusic;\n    if (N.Contains(TEXT(\"ambien\")) || N == TEXT(\"weather\")) return ENarrativeCueAction::PlayAmbience;\n    if (N.Contains(TEXT(\"sound\")) || N == TEXT(\"sfx\")) return ENarrativeCueAction::PlaySound;\n    if (N.Contains(TEXT(\"shake\")) || N == TEXT(\"rumble\")) return ENarrativeCueAction::ShakeCamera;\n    return ENarrativeCueAction::EventOnly;\n}\n";

/** templates/unreal/CuePlayer.h */
export const CUE_PLAYER_H = "// Generated by Narrative Bridge.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeCuePlayer.generated.h\"\n\nclass UAudioComponent;\nclass UCameraShakeBase;\nclass USoundBase;\n\nUENUM(BlueprintType)\nenum class ENarrativeCueAction : uint8\n{\n    EventOnly,\n    PlayMusic,\n    StopMusic,\n    PlaySound,\n    PlayAmbience,\n    StopAmbience,\n    ShakeCamera\n};\n\n/** What one of the story's cues does. */\nUSTRUCT(BlueprintType)\nstruct FNarrativeCueSetup\n{\n    GENERATED_BODY()\n\n    /** The cue's name as the writer gave it (one of the story's cues), e.g. music, sound or shake. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    FString Name;\n\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    ENarrativeCueAction Action = ENarrativeCueAction::EventOnly;\n\n    /** Sounds to choose from: the cue's value picks the one with that name (#music:calm plays \"calm\"), else the writer's sound, else the first. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TArray<TObjectPtr<USoundBase>> Sounds;\n\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\", meta = (ClampMin = \"0\", ClampMax = \"1\"))\n    float Volume = 1.f;\n};\n\n/**\n * Plays the story's cues without code. A writer adds cues in Narrative Bridge (#music:calm, #sound:door_creak, #shake:0.5,\n * or any name of their own), and this does what each one is set to: play or stop music (fading between tracks), play a\n * sound, loop an ambience, shake the camera, or only raise OnAnyCue. Add it next to a Narrative Bridge component; it\n * lists every cue in the story with a likely action. Sounds the writer attached in Narrative Bridge play by themselves.\n */\nUCLASS(ClassGroup = (NarrativeBridge), meta = (BlueprintSpawnableComponent, DisplayName = \"Narrative Cue Player\"))\nclass __API__ UNarrativeCuePlayerComponent : public UActorComponent\n{\n    GENERATED_BODY()\n\npublic:\n    UNarrativeCuePlayerComponent();\n\n    /** Every cue in the story, with what it does. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TArray<FNarrativeCueSetup> Cues;\n\n    /** Play the sounds the writer attached to cues in Narrative Bridge (the story data's cue sounds) when a cue has no sound of its own named by its value. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bPlayStorySounds = true;\n\n    /** Seconds to fade out one music track and in the next. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Sound\", meta = (ClampMin = \"0\"))\n    float MusicFade = 1.f;\n\n    /** The camera shake a shake cue plays (scaled by its value, 0 to 1; 0.5 when it has none). Empty: shake cues only raise OnAnyCue. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge|Camera shake\")\n    TSubclassOf<UCameraShakeBase> ShakeClass;\n\n    /** Every cue the story reaches, listed or not: its name and value. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeCue OnAnyCue;\n\n    /** Plays a cue by name and value, as if the story had reached it. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void PlayCue(const FString& Name, const FString& Value);\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void PlayMusic(USoundBase* Sound, float Volume = 1.f);\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void StopMusic();\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Shake(float Strength);\n\n    /** The music track playing now, or null. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    USoundBase* GetCurrentMusic() const;\n\n    /** A sensible action for a cue's name (music, sound, ambience, shake…). */\n    static ENarrativeCueAction Guess(const FString& Name);\n\n    /** The file the writer attached to a cue tag (e.g. \"music:calm\"), or empty. */\n    static FString StorySound(const FString& Tag);\n\nprotected:\n    virtual void OnRegister() override;\n    virtual void BeginPlay() override;\n    virtual void EndPlay(const EEndPlayReason::Type Reason) override;\n\nprivate:\n    UFUNCTION()\n    void HandleCue(const FString& Name, const FString& Value);\n\n    UFUNCTION()\n    void HandleAmbienceFinished();\n\n    USoundBase* PickSound(const FNarrativeCueSetup& Cue, const FString& Value, const FString& Tag) const;\n    void Run(const FNarrativeCueSetup& Cue, const FString& Value, const FString& Tag);\n\n    UPROPERTY(Transient)\n    TObjectPtr<UAudioComponent> Music;\n\n    UPROPERTY(Transient)\n    TObjectPtr<UAudioComponent> Ambience;\n\n    UPROPERTY(Transient)\n    TObjectPtr<UNarrativeBridgeComponent> Story;\n};\n";

/** templates/unreal/Demo.cpp */
export const DEMO_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeDemoGameMode.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeCuePlayer.h\"\n#include \"NarrativeStoryPanel.h\"\n#include \"Engine/World.h\"\n#include \"EngineUtils.h\"\n\nvoid ANarrativeDemoGameMode::BeginPlay()\n{\n    Super::BeginPlay();\n    // A level that already has the story (Tools → Narrative Bridge → Add … to the Level) needs no other.\n    for (TActorIterator<AActor> It(GetWorld()); It; ++It)\n        if (It->FindComponentByClass<UNarrativeBridgeComponent>()) return;\n    AActor* Actor = GetWorld()->SpawnActor<AActor>();\n    if (!Actor) return;\n    auto Attach = [Actor](UActorComponent* C)\n    {\n        Actor->AddInstanceComponent(C);\n        C->RegisterComponent();\n    };\n    // The story first, so the panel finds it.\n    Attach(NewObject<UNarrativeBridgeComponent>(Actor, TEXT(\"Story\")));\n    Attach(NewObject<UNarrativeCuePlayerComponent>(Actor, TEXT(\"CuePlayer\")));\n    Attach(NewObject<UNarrativeStoryPanelComponent>(Actor, TEXT(\"StoryPanel\")));\n}\n";

