export const DEMO_H = "// Generated by Narrative Bridge. Plays the story on its own: the project's default game mode.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"GameFramework/GameModeBase.h\"\n#include \"NarrativeDemoGameMode.generated.h\"\n\n/** Puts an actor with the story, its story panel and its cue player in the level when play begins. Press Play in any level. */\nUCLASS()\nclass __API__ ANarrativeDemoGameMode : public AGameModeBase\n{\n    GENERATED_BODY()\n\nprotected:\n    virtual void BeginPlay() override;\n};\n";

/** templates/unreal/EditorInkImport.cpp */
export const EDITOR_INK_IMPORT_CPP = "// Generated by Narrative Bridge. See NarrativeBridgeInkImport.h.\n#include \"NarrativeBridgeInkImport.h\"\n#include \"Asset/InkpotStoryAsset.h\"\n#include \"FileHelpers.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/PackageName.h\"\n#include \"Misc/Paths.h\"\n#include \"UObject/Package.h\"\n#include \"NarrativeBridgeTypes.h\"\n\nnamespace NarrativeBridgeInkImport\n{\n    bool CreateStoryAssetFromCompiled(const FString& Source)\n    {\n        FString Json, Ink;\n        if (!FFileHelper::LoadFileToString(Json, *(Source / TEXT(\"MainStory.compiled.json\")))) return false;\n        FFileHelper::LoadFileToString(Ink, *(Source / TEXT(\"MainStory.ink\")));\n        const FString PackageName = FPackageName::ObjectPathToPackageName(FString(NarrativeBridge::StoryAssetPath));\n        UPackage* Package = CreatePackage(*PackageName);\n        UInkpotStoryAsset* Asset = NewObject<UInkpotStoryAsset>(Package, *FPackageName::GetShortName(PackageName), RF_Public | RF_Standalone);\n        Asset->SetSource(Ink);\n        Asset->SetCompiledJSON(Json);\n        Package->MarkPackageDirty();\n        return UEditorLoadingAndSavingUtils::SavePackages({ Package }, false);\n    }\n\n    UObject* MakeTransientStoryAsset(const FString& CompiledJson)\n    {\n        UInkpotStoryAsset* Asset = NewObject<UInkpotStoryAsset>(GetTransientPackage());\n        Asset->SetCompiledJSON(CompiledJson);\n        return Asset;\n    }\n}\n";

