export const EDITOR_INK_IMPORT_H = "// Generated by Narrative Bridge. Makes story assets from the compiled story. Part of the Ink runtime boundary\n// (see NarrativeBridgeInk.h): the only editor file that names the Ink runtime's asset class.\n#pragma once\n\n#include \"CoreMinimal.h\"\n\nnamespace NarrativeBridgeInkImport\n{\n    /** Makes and saves the story asset (NarrativeBridge::StoryAssetPath) from StorySource/MainStory.compiled.json, with no Ink compiler needed. */\n    bool CreateStoryAssetFromCompiled(const FString& SourceFolder);\n\n    /** A story asset made in memory from the compiled story's text, outside any package (for the automation tests). */\n    UObject* MakeTransientStoryAsset(const FString& CompiledJson);\n}\n";

/** templates/unreal/EditorModule.cpp */
export const EDITOR_MODULE_CPP = "// Generated by Narrative Bridge. Imports the story files into Content/NarrativeBridge and adds Tools → Narrative Bridge.\n#include \"Modules/ModuleManager.h\"\n#include \"AssetImportTask.h\"\n#include \"AssetToolsModule.h\"\n#include \"DesktopPlatformModule.h\"\n#include \"Dom/JsonObject.h\"\n#include \"Editor.h\"\n#include \"Engine/World.h\"\n#include \"FileHelpers.h\"\n#include \"Framework/Application/SlateApplication.h\"\n#include \"GameFramework/Actor.h\"\n#include \"HAL/FileManager.h\"\n#include \"HAL/IConsoleManager.h\"\n#include \"HAL/PlatformFileManager.h\"\n#include \"IAssetTools.h\"\n#include \"Misc/App.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/PackageName.h\"\n#include \"Misc/Paths.h\"\n#include \"Interfaces/IPluginManager.h\"\n#include \"Serialization/JsonReader.h\"\n#include \"Serialization/JsonSerializer.h\"\n#include \"ToolMenus.h\"\n#include \"UObject/Package.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeBridgeInkImport.h\"\n#include \"NarrativeBridgeStoryData.h\"\n#include \"NarrativeBridgeTypes.h\"\n#include \"NarrativeCuePlayer.h\"\n#include \"NarrativeStoryPanel.h\"\n\n#define LOCTEXT_NAMESPACE \"NarrativeBridgeEditor\"\n\nnamespace NarrativeBridgeEditor\n{\n    FString PackageOf(const TCHAR* ObjectPath)\n    {\n        return FPackageName::ObjectPathToPackageName(FString(ObjectPath));\n    }\n\n    /** Makes the story data asset (NarrativeBridge::StoryDataAssetPath) from StorySource/StoryInfo.json, or refreshes it. */\n    bool CreateStoryDataAsset(const FString& Source)\n    {\n        FString Json;\n        if (!FFileHelper::LoadFileToString(Json, *(Source / TEXT(\"StoryInfo.json\")))) return false;\n        const FString PackageName = PackageOf(NarrativeBridge::StoryDataAssetPath);\n        UPackage* Package = CreatePackage(*PackageName);\n        UNarrativeStoryData* Asset = FindObject<UNarrativeStoryData>(Package, *FPackageName::GetShortName(PackageName));\n        if (!Asset) Asset = NewObject<UNarrativeStoryData>(Package, *FPackageName::GetShortName(PackageName), RF_Public | RF_Standalone);\n        Asset->SetJson(Json);\n        Asset->MarkPackageDirty();\n        return UEditorLoadingAndSavingUtils::SavePackages({ Package }, false);\n    }\n\n    /** Imports StorySource/MainStory.ink and StorySource/VoiceClips/* into Content/NarrativeBridge (all of them, or only what's missing). */\n    void ImportStoryFiles(bool bAll)\n    {\n        const FString Source = FPaths::ProjectDir() / TEXT(\"StorySource\");\n        TArray<UAssetImportTask*> Tasks;\n        auto Add = [&Tasks](const FString& File, const FString& Destination, const FString& Name)\n        {\n            UAssetImportTask* Task = NewObject<UAssetImportTask>();\n            Task->Filename = File;\n            Task->DestinationPath = Destination;\n            Task->DestinationName = Name;\n            Task->bReplaceExisting = true;\n            Task->bAutomated = true;\n            Task->bSave = true;\n            Tasks.Add(Task);\n        };\n        const FString StoryPackage = PackageOf(NarrativeBridge::StoryAssetPath);\n        const bool bStoryMissing = !FPackageName::DoesPackageExist(StoryPackage);\n        if (bAll || bStoryMissing) Add(Source / TEXT(\"MainStory.ink\"), FPackageName::GetLongPackagePath(StoryPackage), FPackageName::GetShortName(StoryPackage));\n        TArray<FString> Clips;\n        IFileManager::Get().FindFiles(Clips, *(Source / TEXT(\"VoiceClips\")), nullptr);\n        FString AudioPath = NarrativeBridge::AudioPackagePath;\n        AudioPath.RemoveFromEnd(TEXT(\"/\"));\n        for (const FString& Clip : Clips)\n        {\n            const FString Name = UNarrativeBridgeComponent::ClipAssetName(Clip);\n            if (bAll || !FPackageName::DoesPackageExist(AudioPath / Name)) Add(Source / TEXT(\"VoiceClips\") / Clip, AudioPath, Name);\n        }\n        // The story data is small and always current: refresh it every time.\n        CreateStoryDataAsset(Source);\n        if (Tasks.Num() == 0) return;\n        FAssetToolsModule::GetModule().Get().ImportAssetTasks(Tasks);\n        if ((bAll || bStoryMissing) && !FPackageName::DoesPackageExist(StoryPackage))\n        {\n            UE_LOG(LogTemp, Warning, TEXT(\"[NarrativeBridge] Inkpot couldn't import MainStory.ink (its compiler needs .NET); made the story asset from MainStory.compiled.json instead.\"));\n            NarrativeBridgeInkImport::CreateStoryAssetFromCompiled(Source);\n        }\n        UE_LOG(LogTemp, Display, TEXT(\"[NarrativeBridge] Imported %d story file(s) into /Game/NarrativeBridge.\"), Tasks.Num());\n    }\n\n    /** The version of a NarrativeBridge.uplugin file, or empty. */\n    FString PluginVersionIn(const FString& File)\n    {\n        FString Text;\n        TSharedPtr<FJsonObject> Root;\n        FString Version;\n        if (FFileHelper::LoadFileToString(Text, *File) && FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root) && Root.IsValid()) Root->TryGetStringField(TEXT(\"VersionName\"), Version);\n        return Version;\n    }\n\n    /**\n     * Brings a story exported by Pen to Ink into this project: copies the exported folder's StorySource/ and\n     * Content/NarrativeBridge/Data/ (the story's own files; never the plugin, Config/ or the project file) and imports them again.\n     * Assets are replaced in place, so Blueprints that refer to them keep working.\n     */\n    bool ImportStoryFolder(const FString& From)\n    {\n        IPlatformFile& Files = FPlatformFileManager::Get().GetPlatformFile();\n        if (!Files.DirectoryExists(*(From / TEXT(\"StorySource\"))))\n        {\n            UE_LOG(LogTemp, Error, TEXT(\"[NarrativeBridge] %s has no StorySource/ folder: choose the folder a story was exported to.\"), *From);\n            return false;\n        }\n        // An export made with another version of the plugin than this project has may carry data the plugin can't read.\n        const FString Exported = PluginVersionIn(From / TEXT(\"Plugins/NarrativeBridge/NarrativeBridge.uplugin\"));\n        const TSharedPtr<IPlugin> Installed = IPluginManager::Get().FindPlugin(TEXT(\"NarrativeBridge\"));\n        if (!Exported.IsEmpty() && Installed.IsValid() && Installed->GetDescriptor().VersionName != Exported)\n            UE_LOG(LogTemp, Warning, TEXT(\"[NarrativeBridge] That story was exported with Narrative Bridge %s, but this project has plugin version %s. Update the plugin if the story doesn't play.\"), *Exported, *Installed->GetDescriptor().VersionName);\n        const TCHAR* Folders[] = { TEXT(\"StorySource\"), TEXT(\"Content/NarrativeBridge/Data\") };\n        for (const TCHAR* Folder : Folders)\n        {\n            const FString Source = From / Folder;\n            if (!Files.DirectoryExists(*Source)) continue;\n            const FString Destination = FPaths::ProjectDir() / Folder;\n            Files.CreateDirectoryTree(*Destination);\n            if (!Files.CopyDirectoryTree(*Destination, *Source, true))\n            {\n                UE_LOG(LogTemp, Error, TEXT(\"[NarrativeBridge] Couldn't copy %s into the project.\"), *Source);\n                return false;\n            }\n        }\n        ImportStoryFiles(true);\n        return true;\n    }\n\n    /** Asks for the exported folder, then imports it. */\n    void ChooseAndImportStoryFolder()\n    {\n        IDesktopPlatform* Desktop = FDesktopPlatformModule::Get();\n        if (!Desktop) return;\n        FString Folder;\n        const void* Parent = FSlateApplication::IsInitialized() ? FSlateApplication::Get().FindBestParentWindowHandleForDialogs(nullptr) : nullptr;\n        if (Desktop->OpenDirectoryDialog(Parent, TEXT(\"Choose the folder a story was exported to (the one that has StorySource in it)\"), FPaths::ProjectDir(), Folder))\n            ImportStoryFolder(Folder);\n    }\n\n    /** Puts an actor with the story, its panel and its cue player in the level being edited. */\n    void AddStoryToLevel()\n    {\n        UWorld* World = GEditor ? GEditor->GetEditorWorldContext().World() : nullptr;\n        if (!World) return;\n        ImportStoryFiles(false);\n        FActorSpawnParameters Params;\n        Params.Name = MakeUniqueObjectName(World->GetCurrentLevel(), AActor::StaticClass(), TEXT(\"NarrativeStory\"));\n        AActor* Actor = World->SpawnActor<AActor>(AActor::StaticClass(), FTransform::Identity, Params);\n        if (!Actor) return;\n        Actor->SetActorLabel(FString::Printf(TEXT(\"%s (Narrative Bridge)\"), *UNarrativeStoryData::DefaultInfo().Title));\n        auto Attach = [Actor](UActorComponent* C)\n        {\n            Actor->AddInstanceComponent(C);\n            C->RegisterComponent();\n        };\n        Attach(NewObject<UNarrativeBridgeComponent>(Actor, TEXT(\"Story\"), RF_Transactional));\n        Attach(NewObject<UNarrativeStoryPanelComponent>(Actor, TEXT(\"StoryPanel\"), RF_Transactional));\n        Attach(NewObject<UNarrativeCuePlayerComponent>(Actor, TEXT(\"CuePlayer\"), RF_Transactional));\n        Actor->MarkPackageDirty();\n        GEditor->SelectNone(false, true);\n        GEditor->SelectActor(Actor, true, true);\n    }\n}\n\nclass F__MODULE__EditorModule : public IModuleInterface\n{\npublic:\n    virtual void StartupModule() override\n    {\n        // The first time the project opens in the editor (not in a headless run), bring the story files in.\n        if (!FApp::IsUnattended() && !IsRunningCommandlet())\n            FEditorDelegates::OnEditorInitialized.AddLambda([](double) { NarrativeBridgeEditor::ImportStoryFiles(false); });\n        UToolMenus::RegisterStartupCallback(FSimpleMulticastDelegate::FDelegate::CreateRaw(this, &F__MODULE__EditorModule::RegisterMenus));\n    }\n\n    virtual void ShutdownModule() override\n    {\n        UToolMenus::UnRegisterStartupCallback(this);\n        UToolMenus::UnregisterOwner(this);\n    }\n\nprivate:\n    void RegisterMenus()\n    {\n        FToolMenuOwnerScoped Owner(this);\n        UToolMenu* Menu = UToolMenus::Get()->ExtendMenu(\"LevelEditor.MainMenu.Tools\");\n        FToolMenuSection& Section = Menu->FindOrAddSection(\"NarrativeBridge\", LOCTEXT(\"Section\", \"Narrative Bridge\"));\n        Section.AddMenuEntry(\"NarrativeBridgeAddStory\",\n            FText::Format(LOCTEXT(\"AddStory\", \"Add {0} to the Level\"), FText::FromString(UNarrativeStoryData::DefaultInfo().Title)),\n            LOCTEXT(\"AddStoryTip\", \"Adds an actor with the story, its story panel and its cue player.\"),\n            FSlateIcon(), FUIAction(FExecuteAction::CreateStatic(&NarrativeBridgeEditor::AddStoryToLevel)));\n        Section.AddMenuEntry(\"NarrativeBridgeImportStory\",\n            LOCTEXT(\"ImportStory\", \"Import Pen to Ink Story…\"),\n            LOCTEXT(\"ImportStoryTip\", \"Brings a story exported by Pen to Ink into this project: choose the exported folder. Assets are replaced in place, so Blueprints that use them keep working.\"),\n            FSlateIcon(), FUIAction(FExecuteAction::CreateStatic(&NarrativeBridgeEditor::ChooseAndImportStoryFolder)));\n        Section.AddMenuEntry(\"NarrativeBridgeImport\",\n            LOCTEXT(\"Import\", \"Re-import Story Files\"),\n            LOCTEXT(\"ImportTip\", \"Imports StorySource/MainStory.ink and the voice clips into Content/NarrativeBridge again, e.g. after exporting a new version.\"),\n            FSlateIcon(), FUIAction(FExecuteAction::CreateLambda([] { NarrativeBridgeEditor::ImportStoryFiles(true); })));\n    }\n};\n\nstatic FAutoConsoleCommand ImportFolderCommand(\n    TEXT(\"NarrativeBridge.ImportFolder\"),\n    TEXT(\"NarrativeBridge.ImportFolder <folder>: imports the story in a folder exported by Pen to Ink (the one with StorySource/ in it).\"),\n    FConsoleCommandWithArgsDelegate::CreateLambda([](const TArray<FString>& Args) { if (Args.Num() > 0) NarrativeBridgeEditor::ImportStoryFolder(Args[0]); }));\n\nstatic FAutoConsoleCommand ImportCommand(\n    TEXT(\"NarrativeBridge.Import\"),\n    TEXT(\"Imports StorySource/MainStory.ink and the voice clips into Content/NarrativeBridge.\"),\n    FConsoleCommandDelegate::CreateLambda([] { NarrativeBridgeEditor::ImportStoryFiles(true); }));\n\nIMPLEMENT_MODULE(F__MODULE__EditorModule, __MODULE__Editor);\n\n#undef LOCTEXT_NAMESPACE\n";

/** templates/unreal/EditorStoryDataTests.cpp */
export const EDITOR_STORY_DATA_TESTS_CPP = "// Generated by Narrative Bridge. Automation tests of the story data (StorySource/StoryInfo.json): it parses, it is consistent, a newer version is refused, and the C++ condition evaluator gives the answers Narrative Bridge\n// worked out for every locked choice (StorySource/ConditionChecks.json). Same for every story.\n#include \"CoreMinimal.h\"\n#include \"Misc/AutomationTest.h\"\n\n#if WITH_DEV_AUTOMATION_TESTS\n\n#include \"Dom/JsonObject.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/Paths.h\"\n#include \"Serialization/JsonReader.h\"\n#include \"Serialization/JsonSerializer.h\"\n#include \"NarrativeBridgeStoryData.h\"\n\nnamespace NarrativeBridgeStoryDataTests\n{\n    constexpr EAutomationTestFlags Flags = EAutomationTestFlags::EditorContext | EAutomationTestFlags::ProductFilter;\n\n    bool ReadSource(const TCHAR* File, FString& Out) { return FFileHelper::LoadFileToString(Out, *(FPaths::ProjectDir() / TEXT(\"StorySource\") / File)); }\n\n    /** Story variables from the checks' JSON, compared the way ink compares them. */\n    class FMapReader final : public FNarrativeVariableReader\n    {\n    public:\n        explicit FMapReader(const TSharedPtr<FJsonObject>& InVars) : Vars(InVars) {}\n\n        virtual bool Has(const TCHAR* Name) const override\n        {\n            const TSharedPtr<FJsonValue> V = Vars->TryGetField(Name);\n            if (!V.IsValid()) return false;\n            if (V->Type == EJson::Boolean) return V->AsBool();\n            if (V->Type == EJson::Number) return V->AsNumber() != 0;\n            return false;\n        }\n\n        virtual bool CompareNumber(const TCHAR* Name, const TCHAR* Op, double Value) const override\n        {\n            const TSharedPtr<FJsonValue> V = Vars->TryGetField(Name);\n            const FString O = Op;\n            if (!V.IsValid()) return O == TEXT(\"!=\");\n            if (V->Type == EJson::Boolean) return O == TEXT(\"==\") ? V->AsBool() == (Value != 0) : O == TEXT(\"!=\") ? V->AsBool() != (Value != 0) : false;\n            if (V->Type != EJson::Number) return O == TEXT(\"!=\");\n            const double X = V->AsNumber();\n            return Ordered(O, X < Value ? -1 : X > Value ? 1 : 0);\n        }\n\n        virtual bool CompareText(const TCHAR* Name, const TCHAR* Op, const TCHAR* Value) const override\n        {\n            const TSharedPtr<FJsonValue> V = Vars->TryGetField(Name);\n            const FString O = Op;\n            if (!V.IsValid() || V->Type != EJson::String) return O == TEXT(\"!=\");\n            return Ordered(O, V->AsString().Compare(Value, ESearchCase::CaseSensitive));\n        }\n\n        virtual bool CompareBool(const TCHAR* Name, const TCHAR* Op, bool Value) const override\n        {\n            const bool B = Has(Name);\n            const FString O = Op;\n            return O == TEXT(\"==\") ? B == Value : O == TEXT(\"!=\") ? B != Value : false;\n        }\n\n    private:\n        static bool Ordered(const FString& Op, int32 C)\n        {\n            if (Op == TEXT(\"==\")) return C == 0;\n            if (Op == TEXT(\"!=\")) return C != 0;\n            if (Op == TEXT(\"<\")) return C < 0;\n            if (Op == TEXT(\"<=\")) return C <= 0;\n            if (Op == TEXT(\">\")) return C > 0;\n            if (Op == TEXT(\">=\")) return C >= 0;\n            return false;\n        }\n\n        TSharedPtr<FJsonObject> Vars;\n    };\n}\n\nusing namespace NarrativeBridgeStoryDataTests;\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeStoryDataTest, \"NarrativeBridge.StoryData.Parses\", Flags)\n\nbool FNarrativeBridgeStoryDataTest::RunTest(const FString& Parameters)\n{\n    FString Text, Error;\n    if (!TestTrue(TEXT(\"StoryInfo.json reads\"), ReadSource(TEXT(\"StoryInfo.json\"), Text))) return false;\n    FNarrativeStoryInfo Info;\n    if (!TestTrue(FString::Printf(TEXT(\"StoryInfo.json parses (%s)\"), *Error), FNarrativeStoryInfo::Parse(Text, Info, Error))) return false;\n    // What the checks file refers to is in the data, and the data is consistent with itself.\n    TestTrue(TEXT(\"It has a story version\"), !Info.StoryVersion.IsEmpty());\n    TestTrue(TEXT(\"It has a save folder\"), !Info.SaveFolder.IsEmpty());\n    for (const FNarrativeStoryPassage& P : Info.Passages) TestTrue(FString::Printf(TEXT(\"%s has a title\"), *P.Id), !P.Title.IsEmpty());\n    for (const FNarrativeStoryLine& L : Info.Lines)\n    {\n        int32 Dot = INDEX_NONE;\n        const bool bHasDot = L.Path.FindChar(TEXT('.'), Dot);\n        TestTrue(FString::Printf(TEXT(\"%s is in a passage\"), *L.Path), bHasDot && Info.Passages.ContainsByPredicate([&](const FNarrativeStoryPassage& P) { return P.Id == L.Path.Left(Dot); }));\n    }\n    for (const FNarrativeStoryGatedChoice& G : Info.GatedChoices)\n    {\n        TestTrue(FString::Printf(TEXT(\"%s is in a passage\"), *G.Text), Info.Passages.ContainsByPredicate([&](const FNarrativeStoryPassage& P) { return P.Id == G.Passage; }));\n        TestTrue(FString::Printf(TEXT(\"%s has requirements\"), *G.Text), G.Requirements.Num() > 0);\n    }\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeStoryDataVersionTest, \"NarrativeBridge.StoryData.Versions\", Flags)\n\nbool FNarrativeBridgeStoryDataVersionTest::RunTest(const FString& Parameters)\n{\n    FNarrativeStoryInfo Info;\n    FString Error;\n    // A story newer than the plugin is refused with a message; unknown fields in a version it does read are ignored.\n    TestFalse(TEXT(\"A newer version is refused\"), FNarrativeStoryInfo::Parse(TEXT(\"{\\\"schemaVersion\\\":999}\"), Info, Error));\n    TestTrue(TEXT(\"It says to update\"), Error.Contains(TEXT(\"Update the plugin\")));\n    TestTrue(TEXT(\"Unknown fields are ignored\"), FNarrativeStoryInfo::Parse(TEXT(\"{\\\"schemaVersion\\\":1,\\\"title\\\":\\\"T\\\",\\\"somethingNew\\\":[1,2,3]}\"), Info, Error));\n    TestEqual(TEXT(\"Its title\"), Info.Title, FString(TEXT(\"T\")));\n    TestFalse(TEXT(\"Nonsense is refused\"), FNarrativeStoryInfo::Parse(TEXT(\"not json\"), Info, Error));\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeConditionParityTest, \"NarrativeBridge.StoryData.Conditions\", Flags)\n\nbool FNarrativeBridgeConditionParityTest::RunTest(const FString& Parameters)\n{\n    FString InfoText, ChecksText, Error;\n    if (!TestTrue(TEXT(\"StoryInfo.json reads\"), ReadSource(TEXT(\"StoryInfo.json\"), InfoText))) return false;\n    if (!TestTrue(TEXT(\"ConditionChecks.json reads\"), ReadSource(TEXT(\"ConditionChecks.json\"), ChecksText))) return false;\n    FNarrativeStoryInfo Info;\n    if (!TestTrue(TEXT(\"StoryInfo.json parses\"), FNarrativeStoryInfo::Parse(InfoText, Info, Error))) return false;\n    TSharedPtr<FJsonObject> Checks;\n    if (!TestTrue(TEXT(\"ConditionChecks.json parses\"), FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(ChecksText), Checks) && Checks.IsValid())) return false;\n    int32 Evaluated = 0;\n    const TArray<TSharedPtr<FJsonValue>>* List = nullptr;\n    Checks->TryGetArrayField(TEXT(\"checks\"), List);\n    if (!List) return true;\n    for (const TSharedPtr<FJsonValue>& Item : *List)\n    {\n        const TSharedPtr<FJsonObject> Check = Item->AsObject();\n        const FString Passage = Check->GetStringField(TEXT(\"passage\"));\n        const FString Choice = Check->GetStringField(TEXT(\"choice\"));\n        const int32 Requirement = static_cast<int32>(Check->GetNumberField(TEXT(\"requirement\")));\n        const FNarrativeStoryGatedChoice* Gated = Info.GatedChoices.FindByPredicate([&](const FNarrativeStoryGatedChoice& G) { return G.Passage == Passage && G.Text == Choice; });\n        if (!Gated || !Gated->Requirements.IsValidIndex(Requirement)) { AddError(FString::Printf(TEXT(\"No locked choice \\\"%s\\\" in %s.\"), *Choice, *Passage)); continue; }\n        for (const TSharedPtr<FJsonValue>& CaseValue : Check->GetArrayField(TEXT(\"cases\")))\n        {\n            const TSharedPtr<FJsonObject> Case = CaseValue->AsObject();\n            const FMapReader Reader(Case->GetObjectField(TEXT(\"vars\")));\n            const bool bWanted = Case->GetBoolField(TEXT(\"holds\"));\n            TestEqual(FString::Printf(TEXT(\"\\\"%s\\\" in %s, requirement %d\"), *Choice, *Passage, Requirement), Gated->Requirements[Requirement].Condition.Evaluate(Reader), bWanted);\n            ++Evaluated;\n        }\n    }\n    AddInfo(FString::Printf(TEXT(\"%d condition cases agree with Narrative Bridge.\"), Evaluated));\n    return true;\n}\n\n#endif\n";

/** templates/unreal/EditorTests.cpp */
export const EDITOR_TESTS_CPP = "// Generated by Narrative Bridge. Same for every story: it reads StorySource/*.json. Automation tests of the story, run in the editor:\n// Tools → Session Frontend → Automation (filter \"NarrativeBridge\"), or headless:\n//   UnrealEditor-Cmd <project>.uproject -ExecCmds=\"Automation RunTests NarrativeBridge; Quit\" -unattended -nullrhi\n// They play the compiled story (StorySource/MainStory.compiled.json) through the story component, so nothing has to be\n// imported first.\n#include \"CoreMinimal.h\"\n#include \"Misc/AutomationTest.h\"\n\n#if WITH_DEV_AUTOMATION_TESTS\n\n#include \"Dom/JsonObject.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/Paths.h\"\n#include \"Serialization/JsonReader.h\"\n#include \"Serialization/JsonSerializer.h\"\n#include \"Serialization/JsonWriter.h\"\n#include \"UObject/StrongObjectPtr.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeBridgeInk.h\"\n#include \"NarrativeBridgeInkImport.h\"\n#include \"NarrativeBridgeStoryData.h\"\n#include \"NarrativeLocalization.h\"\n#include \"NarrativeTheme.h\"\n\nnamespace NarrativeBridgeTests\n{\n    constexpr EAutomationTestFlags Flags = EAutomationTestFlags::EditorContext | EAutomationTestFlags::ProductFilter;\n\n    /** A story component playing the compiled story, outside any level. */\n    struct FPlay\n    {\n        TStrongObjectPtr<UObject> Asset;\n        TStrongObjectPtr<UNarrativeStoryData> Data;\n        TStrongObjectPtr<UNarrativeBridgeComponent> Story;\n\n        explicit FPlay(FAutomationTestBase& Test)\n        {\n            FString Json;\n            if (!FFileHelper::LoadFileToString(Json, *(FPaths::ProjectDir() / TEXT(\"StorySource/MainStory.compiled.json\"))))\n            {\n                Test.AddError(TEXT(\"Couldn't read StorySource/MainStory.compiled.json.\"));\n                return;\n            }\n            FString InfoJson;\n            if (!FFileHelper::LoadFileToString(InfoJson, *(FPaths::ProjectDir() / TEXT(\"StorySource/StoryInfo.json\"))))\n            {\n                Test.AddError(TEXT(\"Couldn't read StorySource/StoryInfo.json.\"));\n                return;\n            }\n            Asset.Reset(NarrativeBridgeInkImport::MakeTransientStoryAsset(Json));\n            Data.Reset(NewObject<UNarrativeStoryData>(GetTransientPackage()));\n            Data->SetJson(InfoJson);\n            Story.Reset(NewObject<UNarrativeBridgeComponent>(GetTransientPackage()));\n            Story->StoryAsset = Asset.Get();\n            Story->StoryData = Data.Get();\n            Story->bAutosave = false;\n            Story->bPlayVoiceClips = false;\n        }\n\n        /** The choices ink offers (Continue breaks and exits included). */\n        TArray<FString> Offered() const\n        {\n            TArray<FString> Out;\n            if (const FNarrativeInk* Ink = Story->GetInk())\n                for (const FNarrativeInkChoice& C : Ink->CurrentChoices()) Out.Add(C.Text);\n            return Out;\n        }\n\n        FString LastLine() const\n        {\n            const TArray<FNarrativeLine>& T = Story->GetTranscript();\n            for (int32 i = T.Num() - 1; i >= 0; --i)\n                if (!T[i].bIsChoice) return (T[i].SourceSpeaker.IsEmpty() ? FString() : T[i].SourceSpeaker + TEXT(\": \")) + T[i].SourceText;\n            return FString();\n        }\n\n        /** Takes the first choice on offer, Steps times (or until the story ends). */\n        void Walk(int32 Steps)\n        {\n            for (int32 i = 0; i < Steps && !Story->HasEnded() && Offered().Num() > 0; ++i) Story->Choose(0);\n        }\n    };\n}\n\n/** The playthrough routes (StorySource/PlaythroughRoutes.json), none when the story has randomness. */\nstatic TArray<TSharedPtr<FJsonObject>> LoadRoutes()\n{\n    TArray<TSharedPtr<FJsonObject>> Routes;\n    FString Text;\n    TSharedPtr<FJsonObject> Root;\n    if (!FFileHelper::LoadFileToString(Text, *(FPaths::ProjectDir() / TEXT(\"StorySource/PlaythroughRoutes.json\")))) return Routes;\n    if (!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root) || !Root.IsValid()) return Routes;\n    const TArray<TSharedPtr<FJsonValue>>* List = nullptr;\n    if (Root->TryGetArrayField(TEXT(\"routes\"), List))\n        for (const TSharedPtr<FJsonValue>& V : *List) Routes.Add(V->AsObject());\n    return Routes;\n}\n\nusing namespace NarrativeBridgeTests;\n\nIMPLEMENT_COMPLEX_AUTOMATION_TEST(FNarrativeBridgePlaythroughTest, \"NarrativeBridge.Playthrough\", Flags)\n\nvoid FNarrativeBridgePlaythroughTest::GetTests(TArray<FString>& OutBeautifiedNames, TArray<FString>& OutTestCommands) const\n{\n    const TArray<TSharedPtr<FJsonObject>> Routes = LoadRoutes();\n    for (int32 i = 0; i < Routes.Num(); ++i)\n    {\n        OutBeautifiedNames.Add(Routes[i]->GetStringField(TEXT(\"name\")).Replace(TEXT(\".\"), TEXT(\" \")));\n        OutTestCommands.Add(FString::FromInt(i));\n    }\n}\n\nbool FNarrativeBridgePlaythroughTest::RunTest(const FString& Parameters)\n{\n    const TArray<TSharedPtr<FJsonObject>> Routes = LoadRoutes();\n    if (!Routes.IsValidIndex(FCString::Atoi(*Parameters))) return false;\n    const TSharedPtr<FJsonObject>& Route = Routes[FCString::Atoi(*Parameters)];\n    TArray<FString> Choices;\n    for (const TSharedPtr<FJsonValue>& C : Route->GetArrayField(TEXT(\"choices\"))) Choices.Add(C->AsString());\n    FString Ending;\n    Route->TryGetStringField(TEXT(\"ending\"), Ending);\n    FPlay Play(*this);\n    if (!Play.Story) return false;\n    Play.Story->StartStory();\n    if (!TestTrue(TEXT(\"The story starts\"), Play.Story->IsStarted())) return false;\n    for (int32 i = 0; i < Choices.Num(); ++i)\n    {\n        const TArray<FString> Offered = Play.Offered();\n        const int32 Index = Offered.IndexOfByKey(Choices[i]);\n        if (Index == INDEX_NONE)\n        {\n            AddError(FString::Printf(TEXT(\"Step %d (in %s): expected the choice \\\"%s\\\" but the story offers [%s].\"), i + 1, *Play.Story->GetCurrentPassage(), *Choices[i], *FString::Join(Offered, TEXT(\" | \"))));\n            return false;\n        }\n        Play.Story->Choose(Index);\n    }\n    TestTrue(TEXT(\"The story ends\"), Play.Story->HasEnded());\n    if (!Ending.IsEmpty()) TestTrue(FString::Printf(TEXT(\"It reaches %s\"), *Ending), Play.Story->GetInk()->VisitCount(Ending) > 0);\n    TestEqual(TEXT(\"The last line\"), Play.LastLine(), Route->GetStringField(TEXT(\"lastLine\")));\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgePassagesTest, \"NarrativeBridge.StartAtEveryPassage\", Flags)\n\nbool FNarrativeBridgePassagesTest::RunTest(const FString& Parameters)\n{\n    FPlay Play(*this);\n    if (!Play.Story) return false;\n    for (const FNarrativeStoryPassage& P : Play.Story->StoryInfo().Passages)\n    {\n        const FString Passage = P.Id;\n        Play.Story->StartAt(Passage);\n        TestTrue(FString::Printf(TEXT(\"%s starts\"), *Passage), Play.Story->IsStarted() && Play.Story->GetStatus().IsEmpty());\n        TestTrue(FString::Printf(TEXT(\"%s shows something\"), *Passage), Play.Story->GetTranscript().Num() > 0 || Play.Offered().Num() > 0 || Play.Story->HasEnded());\n        TestEqual(FString::Printf(TEXT(\"%s is where it started\"), *Passage), Play.Story->GetStartPassage(), Passage);\n        // Locked choices are worked out from the story's variables without trouble.\n        for (const FNarrativeLockedChoice& L : Play.Story->GetLockedChoices()) TestFalse(TEXT(\"A locked choice says what it needs\"), L.Needs.IsEmpty());\n    }\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeLinesTest, \"NarrativeBridge.StartAtEveryLine\", Flags)\n\n// Just the letters and digits of a line, lower case, without rich text tags (to compare lines however they're styled).\nstatic FString LettersOf(const FString& In)\n{\n    FString Out;\n    bool bInTag = false;\n    for (const TCHAR Ch : In)\n    {\n        if (Ch == TEXT('<')) bInTag = true;\n        else if (Ch == TEXT('>')) bInTag = false;\n        else if (!bInTag && FChar::IsAlnum(Ch)) Out.AppendChar(FChar::ToLower(Ch));\n    }\n    return Out;\n}\n\nbool FNarrativeBridgeLinesTest::RunTest(const FString& Parameters)\n{\n    FPlay Play(*this);\n    if (!Play.Story) return false;\n    for (const FNarrativeStoryLine& Entry : Play.Story->StoryInfo().Lines)\n    {\n        const FString Line = Entry.Path;\n        // The first thing shown is that line (by its first words), in its passage, whether started or entered later.\n        const FString Said = Entry.Text;\n        int32 Colon = INDEX_NONE;\n        const FString Words = LettersOf(Said.FindChar(TEXT(':'), Colon) ? Said.Mid(Colon + 1) : Said).Left(12);\n        for (int32 Pass = 0; Pass < 2; ++Pass)\n        {\n            if (Pass == 0) Play.Story->StartAt(Line);\n            else Play.Story->EnterAt(Line);\n            TestTrue(FString::Printf(TEXT(\"%s starts\"), *Line), Play.Story->IsStarted() && Play.Story->GetStatus().IsEmpty());\n            const TArray<FNarrativeLine>& Shown = Play.Story->GetTranscript();\n            TestTrue(FString::Printf(TEXT(\"%s shows that line first\"), *Line), Shown.Num() > 0 && LettersOf(Shown[0].Text).Contains(Words));\n        }\n        TestEqual(FString::Printf(TEXT(\"%s is where it started\"), *Line), Play.Story->GetStartPassage(), Line);\n    }\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeSavesTest, \"NarrativeBridge.Saves\", Flags)\n\nbool FNarrativeBridgeSavesTest::RunTest(const FString& Parameters)\n{\n    FPlay Play(*this);\n    if (!Play.Story) return false;\n    Play.Story->StartStory();\n    Play.Walk(3);\n    const FString Save = Play.Story->SaveState();\n    const FString Passage = Play.Story->GetCurrentPassage();\n    const TArray<FString> Choices = Play.Offered();\n\n    // The same version loads as it was.\n    FPlay Again(*this);\n    FString Error;\n    TestTrue(TEXT(\"The save loads\"), Again.Story->TryLoadState(Save, Error));\n    TestEqual(TEXT(\"It's in the same passage\"), Again.Story->GetCurrentPassage(), Passage);\n    TestEqual(TEXT(\"It offers the same choices\"), Again.Offered(), Choices);\n\n    // A save from another version of the story is carried over by replaying its choices.\n    TSharedPtr<FJsonObject> Data;\n    FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Save), Data);\n    Data->SetStringField(TEXT(\"storyVersion\"), TEXT(\"an-earlier-version\"));\n    FString Older;\n    FJsonSerializer::Serialize(Data.ToSharedRef(), TJsonWriterFactory<>::Create(&Older));\n    FPlay Carried(*this);\n    TestTrue(TEXT(\"An earlier version's save loads\"), Carried.Story->TryLoadState(Older, Error));\n    TestTrue(TEXT(\"It says it was carried over\"), Carried.Story->GetLoadNote().StartsWith(TEXT(\"Carried this save over\")));\n    TestEqual(TEXT(\"It's in the same passage\"), Carried.Story->GetCurrentPassage(), Passage);\n    TestEqual(TEXT(\"It offers the same choices\"), Carried.Offered(), Choices);\n\n    TestFalse(TEXT(\"Nonsense doesn't load\"), Carried.Story->TryLoadState(TEXT(\"not a save\"), Error));\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeTranslationKeysTest, \"NarrativeBridge.TranslationKeys\", Flags)\n\nbool FNarrativeBridgeTranslationKeysTest::RunTest(const FString& Parameters)\n{\n    // Worked out by Narrative Bridge when it exported the story (StorySource/TestData.json): the keys in Translations.csv.\n    FString Text;\n    TSharedPtr<FJsonObject> Root;\n    if (TestTrue(TEXT(\"TestData.json reads\"), FFileHelper::LoadFileToString(Text, *(FPaths::ProjectDir() / TEXT(\"StorySource/TestData.json\")))) && TestTrue(TEXT(\"TestData.json parses\"), FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root) && Root.IsValid()))\n    {\n        for (const TSharedPtr<FJsonValue>& V : Root->GetArrayField(TEXT(\"translationKeys\")))\n        {\n            const TSharedPtr<FJsonObject> Sample = V->AsObject();\n            const FString Source = Sample->GetStringField(TEXT(\"text\"));\n            TestEqual(FString::Printf(TEXT(\"Key of %s\"), *Source), UNarrativeLocalization::Key(Source), Sample->GetStringField(TEXT(\"key\")));\n        }\n    }\n    TestTrue(TEXT(\"The translation sheet reads\"), UNarrativeLocalization::ParseCsv(TEXT(\"key,kind,passage,source,fr\\r\\nnb_1,line,a,\\\"Hello, \\\"\\\"you\\\"\\\"\\\",Bonjour\\r\\n\")).Num() == 2);\n    return true;\n}\n\nIMPLEMENT_SIMPLE_AUTOMATION_TEST(FNarrativeBridgeThemeTest, \"NarrativeBridge.Theme\", Flags)\n\nbool FNarrativeBridgeThemeTest::RunTest(const FString& Parameters)\n{\n    FNarrativeTheme Theme;\n    TestTrue(TEXT(\"Theme.json loads\"), UNarrativeThemeLibrary::LoadStoryTheme(Theme));\n    TestTrue(TEXT(\"Its text is bigger than nothing\"), Theme.FontSize > 0);\n    return true;\n}\n\n#endif\n";

/** templates/unreal/EnterDialogueTrigger.cpp */
export const ENTER_DIALOGUE_TRIGGER_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeEnterDialogueTrigger.h\"\n#include \"NarrativeBridgeStoryData.h\"\n#include \"GameFramework/Pawn.h\"\n#include \"Kismet/GameplayStatics.h\"\n\nvoid UNarrativeEnterDialogueTriggerComponent::BeginPlay()\n{\n    Super::BeginPlay();\n    Story = FindStory();\n    if (AActor* Owner = GetOwner()) Owner->OnActorBeginOverlap.AddDynamic(this, &UNarrativeEnterDialogueTriggerComponent::HandleOverlap);\n    if (Story)\n    {\n        Story->OnEnded.AddDynamic(this, &UNarrativeEnterDialogueTriggerComponent::HandleStop);\n        Story->OnExit.AddDynamic(this, &UNarrativeEnterDialogueTriggerComponent::HandleExit);\n    }\n    else UE_LOG(LogTemp, Warning, TEXT(\"[NarrativeBridge] Enter Dialogue Trigger on %s: no Narrative Bridge component on its Story Actor or its own actor.\"), *GetNameSafe(GetOwner()));\n}\n\nUNarrativeBridgeComponent* UNarrativeEnterDialogueTriggerComponent::FindStory() const\n{\n    const AActor* From = StoryActor ? StoryActor.Get() : GetOwner();\n    return From ? From->FindComponentByClass<UNarrativeBridgeComponent>() : nullptr;\n}\n\nFString UNarrativeEnterDialogueTriggerComponent::GetTarget() const\n{\n    return Passage.IsEmpty() || Line.IsEmpty() ? Passage : Passage + TEXT(\".\") + Line;\n}\n\nbool UNarrativeEnterDialogueTriggerComponent::CanEnter() const\n{\n    if (!Story || (bOnce && bDone)) return false;\n    return RequiredItem.IsEmpty() || Story->HasItem(RequiredItem);\n}\n\nvoid UNarrativeEnterDialogueTriggerComponent::HandleOverlap(AActor* OverlappedActor, AActor* OtherActor)\n{\n    const APawn* Pawn = Cast<APawn>(OtherActor);\n    if (bEnterOnOverlap && Pawn && Pawn->IsPlayerControlled()) Enter();\n}\n\nvoid UNarrativeEnterDialogueTriggerComponent::Enter()\n{\n    if (!CanEnter()) return;\n    const FString Target = GetTarget();\n    if (!Target.IsEmpty() && !Story->IsStartPoint(Target))\n    {\n        UE_LOG(LogTemp, Error, TEXT(\"[NarrativeBridge] Enter Dialogue Trigger on %s: the story has no passage or line called %s (was it changed in the script?).\"), *GetNameSafe(GetOwner()), *Target);\n        return;\n    }\n    bDone = true;\n    bActive = true;\n    if (bPauseGame) UGameplayStatics::SetGamePaused(this, true);\n    if (Target.IsEmpty()) Story->StartStory();\n    else if (bFreshStart) Story->StartAt(Target);\n    else Story->EnterAt(Target);\n    OnEntered.Broadcast();\n}\n\nvoid UNarrativeEnterDialogueTriggerComponent::HandleStop()\n{\n    if (!bActive) return;\n    bActive = false;\n    if (bPauseGame) UGameplayStatics::SetGamePaused(this, false);\n    OnFinished.Broadcast();\n}\n\nvoid UNarrativeEnterDialogueTriggerComponent::HandleExit(const FString& ExitName)\n{\n    // The game plays at an exit, until it calls Resume.\n    HandleStop();\n}\n\nTArray<FString> UNarrativeEnterDialogueTriggerComponent::GetPassageOptions() const\n{\n    TArray<FString> Options;\n    Options.Add(FString());\n    for (const FNarrativeStoryPassage& P : UNarrativeStoryData::DefaultInfo().Passages) Options.Add(P.Id);\n    return Options;\n}\n\nTArray<FString> UNarrativeEnterDialogueTriggerComponent::GetLineOptions() const\n{\n    TArray<FString> Options;\n    Options.Add(FString());\n    const FString Prefix = Passage + TEXT(\".\");\n    for (const FNarrativeStoryLine& StoryLine : UNarrativeStoryData::DefaultInfo().Lines)\n    {\n        const FString& Name = StoryLine.Path;\n        if (!Passage.IsEmpty() && Name.StartsWith(Prefix, ESearchCase::CaseSensitive)) Options.Add(Name.Mid(Prefix.Len()));\n    }\n    return Options;\n}\n";

/** templates/unreal/EnterDialogueTrigger.h */
export const ENTER_DIALOGUE_TRIGGER_H = "// Generated by Narrative Bridge. Enters the dialogue at a passage, or at a line of dialogue in it.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeEnterDialogueTrigger.generated.h\"\n\n/**\n * Enters the story at a passage, or at a line of dialogue in it, when the player's pawn overlaps this actor (or when you\n * call Enter). Pick the Line to pick a conversation up partway: the player went off to fetch the flowers, comes back, and\n * the talk goes on at \"You found them!\" instead of from the top. When the story has already run, it keeps what it knows\n * (its variables and items); Fresh Start starts over. Turn off Start On Begin Play on the Narrative Bridge component.\n */\nUCLASS(ClassGroup = (NarrativeBridge), meta = (BlueprintSpawnableComponent, DisplayName = \"Narrative Enter Dialogue Trigger\"))\nclass __API__ UNarrativeEnterDialogueTriggerComponent : public UActorComponent\n{\n    GENERATED_BODY()\n\npublic:\n    /** The actor with the Narrative Bridge component. Empty: this actor. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TObjectPtr<AActor> StoryActor;\n\n    /** The passage to enter (one of the story's passages). Empty: the beginning of the story. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\", meta = (GetOptions = \"GetPassageOptions\"))\n    FString Passage;\n\n    /** The line of dialogue in that passage the player picks up on (see the story's lines). Empty: the top of the passage. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\", meta = (GetOptions = \"GetLineOptions\"))\n    FString Line;\n\n    /** Enter only when the player has this item (an item id, without \"has_\"), e.g. the flowers. Empty: always. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    FString RequiredItem;\n\n    /** Enter when the player's pawn walks in. Off: only when you call Enter (from your own \"talk\" button, say). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bEnterOnOverlap = true;\n\n    /** Only the first time. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bOnce = true;\n\n    /** Start the story over there (forgetting its variables and items) instead of keeping what it knows. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bFreshStart = false;\n\n    /** Pause the game while the dialogue runs. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bPauseGame = false;\n\n    /** The dialogue was entered. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeMoment OnEntered;\n\n    /** The dialogue ended, or handed over to the game at an exit. */\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeMoment OnFinished;\n\n    /** Enters the dialogue now, as walking in does. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Enter();\n\n    /** Whether Enter would enter the dialogue now. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool CanEnter() const;\n\n    /** Where it enters: the passage, or \"passage.line_…\" for a line (empty for the beginning). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetTarget() const;\n\n    /** The passages, for the Passage list in the Details panel. */\n    UFUNCTION()\n    TArray<FString> GetPassageOptions() const;\n\n    /** The chosen passage's lines of dialogue, for the Line list in the Details panel. */\n    UFUNCTION()\n    TArray<FString> GetLineOptions() const;\n\nprotected:\n    virtual void BeginPlay() override;\n\nprivate:\n    UFUNCTION()\n    void HandleOverlap(AActor* OverlappedActor, AActor* OtherActor);\n\n    UFUNCTION()\n    void HandleStop();\n\n    UFUNCTION()\n    void HandleExit(const FString& ExitName);\n\n    UNarrativeBridgeComponent* FindStory() const;\n\n    UPROPERTY(Transient)\n    TObjectPtr<UNarrativeBridgeComponent> Story;\n\n    bool bDone = false;\n    bool bActive = false;\n};\n";

/** templates/unreal/Ink.cpp */
export const INK_CPP = "// Generated by Narrative Bridge. The only file that calls the Ink runtime (Inkpot, and InkPlusPlus's Ink::FStory under it).\n// If the runtime changes, or a new engine needs a patch, this is the file to change. See NarrativeBridgeInk.h for what it offers.\n#include \"NarrativeBridgeInk.h\"\n#include \"NarrativeBridgeInkCompat.h\"\n#include \"NarrativeBridgeInkObserver.h\"\n#include \"Asset/InkpotStoryAsset.h\"\n#include \"Engine/Engine.h\"\n#include \"Ink/Choice.h\"\n#include \"Ink/StoryState.h\"\n#include \"Inkpot/Inkpot.h\"\n#include \"Inkpot/InkpotStory.h\"\n#include \"Inkpot/InkpotValueLibrary.h\"\n#include \"UObject/StrongObjectPtr.h\"\n\nstruct FNarrativeInk::FImpl\n{\n    TStrongObjectPtr<UInkpotStory> Story;\n    TStrongObjectPtr<UNarrativeInkObserver> Observer;\n};\n\nFNarrativeValue NarrativeValueFromInkpot(const FInkpotValue& V)\n{\n    if (UInkpotValueLibrary::IsInkpotValueBool(V)) return FNarrativeValue::FromBool(UInkpotValueLibrary::InkpotValueAsBool(V));\n    if (UInkpotValueLibrary::IsInkpotValueInt(V)) return FNarrativeValue::FromInt(UInkpotValueLibrary::InkpotValueAsInt(V));\n    if (UInkpotValueLibrary::IsInkpotValueFloat(V)) return FNarrativeValue::FromFloat(UInkpotValueLibrary::InkpotValueAsFloat(V));\n    if (UInkpotValueLibrary::IsInkpotValueString(V)) return FNarrativeValue::FromString(UInkpotValueLibrary::InkpotValueAsString(V));\n    return FNarrativeValue();\n}\n\nvoid UNarrativeInkObserver::HandleChange(UInkpotStory* Story, const FString& Variable, const FInkpotValue& NewValue)\n{\n    const FNarrativeValue Value = NarrativeValueFromInkpot(NewValue);\n    for (const FNarrativeInk::FObserver& Callback : Callbacks) Callback(Variable, Value);\n}\n\nFNarrativeInk::FNarrativeInk() : Impl(MakeUnique<FImpl>()) {}\n\nFNarrativeInk::~FNarrativeInk() { End(); }\n\nUObject* FNarrativeInk::LoadStoryAsset(const TCHAR* ObjectPath)\n{\n    return LoadObject<UInkpotStoryAsset>(nullptr, ObjectPath, nullptr, LOAD_NoWarn | LOAD_Quiet);\n}\n\nTSharedPtr<FNarrativeInk> FNarrativeInk::Begin(UObject* StoryAsset, FString& Error)\n{\n    Error.Reset();\n    UInkpotStoryAsset* Asset = Cast<UInkpotStoryAsset>(StoryAsset);\n    if (!Asset) { Error = TEXT(\"No story asset. Open the project in the editor to import StorySource/MainStory.ink, or set Story Asset.\"); return nullptr; }\n    UInkpot* Pot = GEngine ? GEngine->GetEngineSubsystem<UInkpot>() : nullptr;\n    if (!Pot) { Error = TEXT(\"The Inkpot plugin isn't running.\"); return nullptr; }\n    UInkpotStory* Story = Pot->BeginStory(Asset);\n    if (!Story || !Story->IsValid()) { Error = TEXT(\"Inkpot couldn't start the story.\"); return nullptr; }\n    TSharedPtr<FNarrativeInk> Ink = MakeShareable(new FNarrativeInk());\n    Ink->Impl->Story.Reset(Story);\n    return Ink;\n}\n\nvoid FNarrativeInk::End()\n{\n    UInkpotStory* Story = Impl->Story.Get();\n    if (Story && GEngine)\n        if (UInkpot* Pot = GEngine->GetEngineSubsystem<UInkpot>()) Pot->EndStory(Story);\n    Impl->Story.Reset();\n    Impl->Observer.Reset();\n}\n\nbool FNarrativeInk::CanContinue() const { return Impl->Story && Impl->Story->CanContinue(); }\n\nFString FNarrativeInk::Continue() { return Impl->Story ? Impl->Story->Continue() : FString(); }\n\nTArray<FString> FNarrativeInk::CurrentTags() const { return Impl->Story ? Impl->Story->GetCurrentTags() : TArray<FString>(); }\n\nTArray<FNarrativeInkChoice> FNarrativeInk::CurrentChoices() const\n{\n    TArray<FNarrativeInkChoice> Out;\n    // From ink's state itself: Inkpot's own list only updates as the story continues.\n    if (!Impl->Story || !Impl->Story->GetStoryInternal().IsValid()) return Out;\n    for (const TSharedPtr<Ink::FChoice>& C : Impl->Story->GetStoryInternal()->GetCurrentChoices())\n    {\n        FNarrativeInkChoice Choice;\n        Choice.Text = C->GetText();\n        Choice.Index = C->GetIndex();\n        Choice.SourcePath = C->GetSourcePath();\n        Out.Add(Choice);\n    }\n    return Out;\n}\n\nvoid FNarrativeInk::Choose(int32 ChoiceIndex) { if (Impl->Story) Impl->Story->ChooseChoiceIndex(ChoiceIndex); }\n\nvoid FNarrativeInk::GoTo(const FString& Path) { if (Impl->Story) Impl->Story->ChoosePath(Path); }\n\nFString FNarrativeInk::CurrentPath() const\n{\n    if (!Impl->Story || !Impl->Story->GetStoryInternal().IsValid()) return FString();\n    return Impl->Story->GetStoryInternal()->GetStoryState()->getCurrentPathString();\n}\n\nint32 FNarrativeInk::VisitCount(const FString& Path) const { return Impl->Story ? Impl->Story->VisitCountAtPathString(Path) : 0; }\n\nbool FNarrativeInk::IsDefined(const FString& Name) const { return Impl->Story && Impl->Story->IsVariableDefined(Name); }\n\nbool FNarrativeInk::Get(const FString& Name, FNarrativeValue& Out) const\n{\n    Out = FNarrativeValue();\n    if (!IsDefined(Name)) return false;\n    FInkpotValue V;\n    bool bOk = false;\n    Impl->Story->GetValue(Name, V, bOk);\n    if (bOk) Out = NarrativeValueFromInkpot(V);\n    return bOk && Out.IsSet();\n}\n\nbool FNarrativeInk::Set(const FString& Name, const FNarrativeValue& Value)\n{\n    if (!Impl->Story) return false;\n    bool bOk = false;\n    switch (Value.Type)\n    {\n    case ENarrativeValueType::Bool: Impl->Story->SetBool(Name, Value.bValue, bOk); break;\n    case ENarrativeValueType::Int: Impl->Story->SetInt(Name, Value.IntValue, bOk); break;\n    case ENarrativeValueType::Float: Impl->Story->SetFloat(Name, Value.FloatValue, bOk); break;\n    case ENarrativeValueType::String: Impl->Story->SetString(Name, Value.StringValue, bOk); break;\n    default: break;\n    }\n    return bOk;\n}\n\nvoid FNarrativeInk::Observe(const TArray<FString>& Names, FObserver Callback)\n{\n    if (!Impl->Story) return;\n    if (!Impl->Observer) Impl->Observer.Reset(NewObject<UNarrativeInkObserver>(GetTransientPackage()));\n    Impl->Observer->Callbacks.Add(MoveTemp(Callback));\n    for (const FString& Name : Names)\n    {\n        FOnInkpotVariableChange Delegate;\n        Delegate.BindUFunction(Impl->Observer.Get(), GET_FUNCTION_NAME_CHECKED(UNarrativeInkObserver, HandleChange));\n        Impl->Story->SetOnVariableChange(Delegate, Name);\n    }\n}\n\nFString FNarrativeInk::ToJson() const { return Impl->Story ? Impl->Story->ToJSON() : FString(); }\n\nvoid FNarrativeInk::LoadJson(const FString& Json) { if (Impl->Story) Impl->Story->LoadJSON(Json); }\n\nvoid FNarrativeInk::Reset() { if (Impl->Story) Impl->Story->ResetState(); }\n\nUObject* FNarrativeInk::GetRuntimeStory() const { return Impl->Story.Get(); }\n";

/** templates/unreal/Ink.h */
export const INK_H = "// Generated by Narrative Bridge. The one place the story runtime is reached: every call into the Ink runtime (Inkpot and\n// InkPlusPlus) is made in NarrativeBridgeInk.cpp. Nothing else in the project includes the Ink runtime's headers, so\n// upgrading it, patching it for a new engine or swapping it is a change to that one file.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"NarrativeBridgeTypes.h\"\n\n/** A choice ink offers right now (Continue breaks and exits included). */\nstruct FNarrativeInkChoice\n{\n    /** The choice's text as written. */\n    FString Text;\n    /** Pass this to FNarrativeInk::Choose. */\n    int32 Index = 0;\n    /** Where the choice is written in the story (\"harbour.0.c-1\"); its first part is the passage. */\n    FString SourcePath;\n};\n\n/** One running story. Made with Begin; the story ends with it. */\nclass __API__ FNarrativeInk\n{\npublic:\n    /** Called when a watched variable changes. */\n    using FObserver = TFunction<void(const FString& Name, const FNarrativeValue& Value)>;\n\n    /** Starts a story from a story asset (the one the editor imports from StorySource/). Null, with Error filled, when it can't. */\n    static TSharedPtr<FNarrativeInk> Begin(UObject* StoryAsset, FString& Error);\n\n    /** Loads the story asset at an object path (e.g. \"/Game/NarrativeBridge/MainStory.MainStory\"), or null. */\n    static UObject* LoadStoryAsset(const TCHAR* ObjectPath);\n\n    ~FNarrativeInk();\n    FNarrativeInk(const FNarrativeInk&) = delete;\n    FNarrativeInk& operator=(const FNarrativeInk&) = delete;\n\n    /** Stops the story and lets the runtime forget it. Safe to call twice. */\n    void End();\n\n    bool CanContinue() const;\n    /** The next piece of text. */\n    FString Continue();\n    /** The tags on the text Continue just gave. */\n    TArray<FString> CurrentTags() const;\n    /** The choices on offer, always up to date (not only after the story has continued). */\n    TArray<FNarrativeInkChoice> CurrentChoices() const;\n    void Choose(int32 ChoiceIndex);\n    /** Jumps to a knot, or a stitch (\"garden\", \"garden.line_3\"). */\n    void GoTo(const FString& Path);\n    /** Where the story is, as \"knot.stitch…\", or empty. */\n    FString CurrentPath() const;\n    /** How many times the story has been at a path (the automation tests check endings with it). */\n    int32 VisitCount(const FString& Path) const;\n\n    bool IsDefined(const FString& Name) const;\n    /** Reads a variable. False when it doesn't exist. */\n    bool Get(const FString& Name, FNarrativeValue& Out) const;\n    /** Writes a variable. False when it doesn't exist or the value's type doesn't fit. */\n    bool Set(const FString& Name, const FNarrativeValue& Value);\n    /** Calls Callback whenever one of these variables changes. */\n    void Observe(const TArray<FString>& Names, FObserver Callback);\n\n    /** The whole state (variables, position, history) as text, and back. */\n    FString ToJson() const;\n    void LoadJson(const FString& Json);\n    /** Back to the start, with the variables at their first values. */\n    void Reset();\n\n    /** The runtime's own story object, for the deprecated Blueprint functions that expose it (see NarrativeBridgeInkCompat.h). */\n    UObject* GetRuntimeStory() const;\n\nprivate:\n    FNarrativeInk();\n\n    struct FImpl;\n    TUniquePtr<FImpl> Impl;\n};\n";

/** templates/unreal/InkCompat.cpp */
export const INK_COMPAT_CPP = "// Generated by Narrative Bridge. The deprecated Inkpot-typed Blueprint functions of UNarrativeBridgeComponent.\n// They live here so the component itself never names the Ink runtime (see NarrativeBridgeInk.h).\n#include \"NarrativeBridgeInkCompat.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeBridgeInk.h\"\n#include \"Inkpot/InkpotStory.h\"\n\nUInkpotStory* UNarrativeBridgeComponent::GetInkpotStory() const\n{\n    return Ink.IsValid() ? Cast<UInkpotStory>(Ink->GetRuntimeStory()) : nullptr;\n}\n\nFInkpotValue UNarrativeBridgeComponent::GetVariable(const FString& Name, bool& bFound) const\n{\n    FInkpotValue Value;\n    bFound = false;\n    UInkpotStory* Story = GetInkpotStory();\n    if (!Story || !CanAccessVariable(Name, false) || !Story->IsVariableDefined(Name)) return Value;\n    Story->GetValue(Name, Value, bFound);\n    return Value;\n}\n\nbool UNarrativeBridgeComponent::SetVariable(const FString& Name, const FInkpotValue& Value)\n{\n    return SetStoryValue(Name, NarrativeValueFromInkpot(Value));\n}\n";

/** templates/unreal/InkCompat.h */
export const INK_COMPAT_H = "// Generated by Narrative Bridge. The old Inkpot-typed Blueprint functions (GetVariable, SetVariable, GetInkpotStory),\n// kept as deprecated wrappers so existing Blueprints still work. New code uses GetStoryValue / SetStoryValue, the typed\n// getters (GetBool, GetInt, GetFloat, GetString) and FNarrativeInk. Part of the Ink runtime boundary: it's the only header\n// besides NarrativeBridgeInk* that names Inkpot.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Inkpot/InkpotValue.h\"\n#include \"NarrativeBridgeTypes.h\"\n\nclass UInkpotStory;\n\n/** An Inkpot value as ours. */\nFNarrativeValue NarrativeValueFromInkpot(const FInkpotValue& Value);\n";

/** templates/unreal/InkObserver.h */
export const INK_OBSERVER_H = "// Generated by Narrative Bridge. Ink reports a variable change to a UFUNCTION; this forwards it to a plain callback.\n// Part of the Ink runtime boundary (see NarrativeBridgeInk.h): only NarrativeBridgeInk* files include it.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Inkpot/InkpotValue.h\"\n#include \"NarrativeBridgeInk.h\"\n#include \"NarrativeBridgeInkObserver.generated.h\"\n\nclass UInkpotStory;\n\nUCLASS()\nclass __API__ UNarrativeInkObserver : public UObject\n{\n    GENERATED_BODY()\n\npublic:\n    TArray<FNarrativeInk::FObserver> Callbacks;\n\n    UFUNCTION()\n    void HandleChange(UInkpotStory* Story, const FString& Variable, const FInkpotValue& NewValue);\n};\n";

/** templates/unreal/Inventory.h */
export const INVENTORY_H = "// Generated by Narrative Bridge.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"UObject/Interface.h\"\n#include \"NarrativeInventoryAuthority.generated.h\"\n\nUINTERFACE(BlueprintType, meta = (DisplayName = \"Narrative Inventory Authority\"))\nclass __API__ UNarrativeInventoryAuthority : public UInterface\n{\n    GENERATED_BODY()\n};\n\n/**\n * Implement on an actor or component (in C++ or Blueprint) to make your game the authority for item possession, and set\n * it as the story component's Inventory Authority. The story asks it before every step and sends it the gains and losses\n * instead of keeping its own copy. Item ids are the story's item variables without the \"has_\" prefix.\n */\nclass __API__ INarrativeInventoryAuthority\n{\n    GENERATED_BODY()\n\npublic:\n    UFUNCTION(BlueprintNativeEvent, BlueprintCallable, Category = \"Narrative Bridge\")\n    bool HasItem(const FString& ItemId);\n\n    UFUNCTION(BlueprintNativeEvent, BlueprintCallable, Category = \"Narrative Bridge\")\n    void GiveItem(const FString& ItemId);\n\n    UFUNCTION(BlueprintNativeEvent, BlueprintCallable, Category = \"Narrative Bridge\")\n    void TakeItem(const FString& ItemId);\n};\n";

/** templates/unreal/InventoryComponent.h */
export const INVENTORY_COMPONENT_H = "// Generated by Narrative Bridge. A simple inventory the story can use, or a model for your own.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"NarrativeInventoryAuthority.h\"\n#include \"NarrativeSimpleInventory.generated.h\"\n\nDECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FNarrativeItemChanged, const FString&, ItemId, bool, bOwned);\n\n/**\n * A list of item ids that is the story's inventory (it implements Narrative Inventory Authority): put it on the same actor\n * as the Narrative Bridge component, or point the component's Inventory Authority at it. Items the story gives or takes\n * arrive here; give and take them from your game too. Item ids are the story's item variables without \"has_\".\n */\nUCLASS(ClassGroup = (NarrativeBridge), meta = (BlueprintSpawnableComponent, DisplayName = \"Narrative Simple Inventory\"))\nclass __API__ UNarrativeSimpleInventoryComponent : public UActorComponent, public INarrativeInventoryAuthority\n{\n    GENERATED_BODY()\n\npublic:\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TArray<FString> Items;\n\n    UPROPERTY(BlueprintAssignable, Category = \"Narrative Bridge\")\n    FNarrativeItemChanged OnItemChanged;\n\n    virtual bool HasItem_Implementation(const FString& ItemId) override { return Items.Contains(ItemId); }\n\n    virtual void GiveItem_Implementation(const FString& ItemId) override\n    {\n        if (Items.Contains(ItemId)) return;\n        Items.Add(ItemId);\n        OnItemChanged.Broadcast(ItemId, true);\n    }\n\n    virtual void TakeItem_Implementation(const FString& ItemId) override\n    {\n        if (Items.Remove(ItemId) > 0) OnItemChanged.Broadcast(ItemId, false);\n    }\n};\n";

/** templates/unreal/Localization.cpp */
export const LOCALIZATION_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeLocalization.h\"\n#include \"NarrativeBridgeStoryData.h\"\n#include \"NarrativeBridgeTypes.h\"\n#include \"Internationalization/Culture.h\"\n#include \"Internationalization/Internationalization.h\"\n#include \"Misc/ConfigCacheIni.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/Paths.h\"\n\nnamespace\n{\n    const TCHAR* ConfigSection = TEXT(\"NarrativeBridge\");\n    TMap<FString, TArray<FString>> Table;\n    TArray<FString> SheetLanguages;\n    FString SheetFile;\n    FString Current;\n    bool bLoaded = false;\n    bool bLanguageLoaded = false;\n\n    FString Normalise(const FString& Text)\n    {\n        FString Out;\n        Out.Reserve(Text.Len());\n        bool bSpace = false;\n        for (const TCHAR Ch : Text)\n        {\n            if (FChar::IsWhitespace(Ch)) { bSpace = Out.Len() > 0; continue; }\n            if (bSpace) Out.AppendChar(TEXT(' '));\n            bSpace = false;\n            Out.AppendChar(Ch);\n        }\n        return Out;\n    }\n}\n\nFSimpleMulticastDelegate& UNarrativeLocalization::OnChanged()\n{\n    static FSimpleMulticastDelegate Changed;\n    return Changed;\n}\n\nFString UNarrativeLocalization::Key(const FString& Text)\n{\n    const FString T = Normalise(Text);\n    uint32 H = 0x811c9dc5u;\n    for (const TCHAR Ch : T)\n    {\n        H ^= static_cast<uint32>(static_cast<uint16>(Ch));\n        H *= 0x01000193u;\n    }\n    return FString::Printf(TEXT(\"nb_%08x\"), H);\n}\n\nTArray<TArray<FString>> UNarrativeLocalization::ParseCsv(const FString& Text)\n{\n    TArray<TArray<FString>> Rows;\n    TArray<FString> Row;\n    FString Field;\n    bool bQuoted = false;\n    const int32 Len = Text.Len();\n    for (int32 i = 0; i < Len; ++i)\n    {\n        const TCHAR C = Text[i];\n        if (bQuoted)\n        {\n            if (C == TEXT('\"') && i + 1 < Len && Text[i + 1] == TEXT('\"')) { Field.AppendChar(TEXT('\"')); ++i; }\n            else if (C == TEXT('\"')) bQuoted = false;\n            else Field.AppendChar(C);\n            continue;\n        }\n        if (C == TEXT('\"') && Field.IsEmpty()) bQuoted = true;\n        else if (C == TEXT(',')) { Row.Add(Field); Field.Reset(); }\n        else if (C == TEXT('\\n') || C == TEXT('\\r'))\n        {\n            if (C == TEXT('\\r') && i + 1 < Len && Text[i + 1] == TEXT('\\n')) ++i;\n            Row.Add(Field);\n            Field.Reset();\n            if (Row.Num() > 1 || !Row[0].IsEmpty()) Rows.Add(Row);\n            Row.Reset();\n        }\n        else if (C != 0xFEFF) Field.AppendChar(C);\n    }\n    if (!Field.IsEmpty() || Row.Num() > 0)\n    {\n        Row.Add(Field);\n        Rows.Add(Row);\n    }\n    return Rows;\n}\n\nvoid UNarrativeLocalization::EnsureLoaded()\n{\n    if (bLoaded) return;\n    bLoaded = true;\n    Table.Reset();\n    SheetLanguages.Reset();\n    const FString File = SheetFile.IsEmpty() ? FPaths::ProjectContentDir() / NarrativeBridge::TranslationsFile : SheetFile;\n    FString Csv;\n    if (!FFileHelper::LoadFileToString(Csv, *File)) return;\n    const TArray<TArray<FString>> Rows = ParseCsv(Csv);\n    if (Rows.Num() == 0) return;\n    const int32 First = Rows[0].IndexOfByKey(TEXT(\"source\")) + 1;\n    if (First <= 0) return;\n    for (int32 i = First; i < Rows[0].Num(); ++i) SheetLanguages.Add(Rows[0][i].TrimStartAndEnd());\n    for (int32 r = 1; r < Rows.Num(); ++r)\n    {\n        const TArray<FString>& Row = Rows[r];\n        if (Row.Num() == 0 || Row[0].IsEmpty()) continue;\n        TArray<FString> Values;\n        for (int32 i = 0; i < SheetLanguages.Num(); ++i) Values.Add(First + i < Row.Num() ? Row[First + i] : FString());\n        Table.Add(Row[0], MoveTemp(Values));\n    }\n}\n\nvoid UNarrativeLocalization::LoadLanguage()\n{\n    if (bLanguageLoaded) return;\n    bLanguageLoaded = true;\n    if (GConfig && GConfig->GetString(ConfigSection, TEXT(\"Language\"), Current, GGameUserSettingsIni)) return;\n    // Nobody has chosen yet: the player's system language, if there's a translation into it.\n    EnsureLoaded();\n    const FString System = FInternationalization::Get().GetCurrentLanguage()->GetTwoLetterISOLanguageName();\n    Current = System != UNarrativeStoryData::DefaultInfo().SourceLanguage && SheetLanguages.Contains(System) ? System : FString();\n}\n\nFString UNarrativeLocalization::Translate(const FString& Text)\n{\n    if (Text.IsEmpty()) return Text;\n    LoadLanguage();\n    if (Current.IsEmpty()) return Text;\n    EnsureLoaded();\n    const int32 Column = SheetLanguages.IndexOfByKey(Current);\n    if (Column == INDEX_NONE) return Text;\n    const TArray<FString>* Row = Table.Find(Key(Text));\n    return Row && Row->IsValidIndex(Column) && !(*Row)[Column].IsEmpty() ? (*Row)[Column] : Text;\n}\n\nFString UNarrativeLocalization::GetLanguage()\n{\n    LoadLanguage();\n    return Current;\n}\n\nvoid UNarrativeLocalization::SetLanguage(const FString& Language)\n{\n    LoadLanguage();\n    if (Language == Current) return;\n    Current = Language;\n    if (GConfig)\n    {\n        GConfig->SetString(ConfigSection, TEXT(\"Language\"), *Current, GGameUserSettingsIni);\n        GConfig->Flush(false, GGameUserSettingsIni);\n    }\n    OnChanged().Broadcast();\n}\n\nTArray<FString> UNarrativeLocalization::GetLanguages()\n{\n    EnsureLoaded();\n    return SheetLanguages;\n}\n\nFString UNarrativeLocalization::DisplayName(const FString& Language)\n{\n    const FString Code = Language.IsEmpty() ? UNarrativeStoryData::DefaultInfo().SourceLanguage : Language;\n    const FCulturePtr Culture = FInternationalization::Get().GetCulture(Code);\n    if (!Culture.IsValid()) return Code;\n    FString Name = Culture->GetNativeName();\n    if (Name.IsEmpty()) return Code;\n    Name[0] = FChar::ToUpper(Name[0]);\n    return Name;\n}\n\nvoid UNarrativeLocalization::UseSheet(const FString& CsvFile)\n{\n    SheetFile = CsvFile;\n    bLoaded = false;\n    OnChanged().Broadcast();\n}\n";

/** templates/unreal/Localization.h */
export const LOCALIZATION_H = "// Generated by Narrative Bridge.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Kismet/BlueprintFunctionLibrary.h\"\n#include \"NarrativeLocalization.generated.h\"\n\n/**\n * Shows the story in another language. The translation sheet (Content/NarrativeBridge/Data/Translations.csv) lists every\n * piece of text the player can see with a key made from its text; translators add a column per language (\"fr\", \"de\"…).\n * SetLanguage picks one (\"\" for the story as written); the story panel's Settings menu has it too. Lines are found by their\n * text, so revising the story keeps every translation whose line didn't change.\n */\nUCLASS()\nclass __API__ UNarrativeLocalization : public UBlueprintFunctionLibrary\n{\n    GENERATED_BODY()\n\npublic:\n    /** The text in the current language, or as written when there's no translation for it. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Translations\")\n    static FString Translate(const FString& Text);\n\n    /** The language shown: one of GetLanguages, or \"\" for the story as written. The first time, the player's system language if the sheet has it. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Translations\")\n    static FString GetLanguage();\n\n    /** Shows the story in a language (one of GetLanguages, or \"\" for the story as written). Kept in GameUserSettings. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Translations\")\n    static void SetLanguage(const FString& Language);\n\n    /** The languages the sheet has (its column names after \"source\"), not counting the story's own. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Translations\")\n    static TArray<FString> GetLanguages();\n\n    /** A language's own name for itself (fr → Français), or the code; \"\" is the story's own language. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Translations\")\n    static FString DisplayName(const FString& Language);\n\n    /** Uses another sheet (a CSV file like Translations.csv, e.g. your translators' newest); \"\" goes back to the story's. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Translations\")\n    static void UseSheet(const FString& CsvFile);\n\n    /** The sheet's key for a text: its words with spaces tidied, hashed (FNV-1a), e.g. \"nb_1c3f9a2e\". The same as Narrative Bridge's. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Translations\")\n    static FString Key(const FString& Text);\n\n    /** Reads CSV: commas between fields, \"quoted\" fields may hold commas, quotes (\"\") and line breaks. */\n    static TArray<TArray<FString>> ParseCsv(const FString& Text);\n\n    /** Raised when the language (or the sheet) changes: the story and its panel show the new words. */\n    static FSimpleMulticastDelegate& OnChanged();\n\nprivate:\n    static void EnsureLoaded();\n    static void LoadLanguage();\n};\n";

/** templates/unreal/Panel.cpp */
export const PANEL_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeStoryPanel.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeStoryWidget.h\"\n#include \"Blueprint/UserWidget.h\"\n#include \"Engine/World.h\"\n#include \"GameFramework/PlayerController.h\"\n\nvoid UNarrativeStoryPanelComponent::BeginPlay()\n{\n    Super::BeginPlay();\n    APlayerController* Player = GetWorld() ? GetWorld()->GetFirstPlayerController() : nullptr;\n    if (!Player) return;\n    UClass* Class = WidgetClass ? WidgetClass.Get() : UNarrativeStoryWidget::StaticClass();\n    Widget = CreateWidget<UNarrativeStoryWidget>(Player, Class);\n    if (!Widget) return;\n    if (ThemeAsset) Widget->ThemeAsset = ThemeAsset;\n    Widget->AddToViewport(ZOrder);\n    Widget->SetStory(GetOwner() ? GetOwner()->FindComponentByClass<UNarrativeBridgeComponent>() : nullptr);\n    if (bShowMouseCursor)\n    {\n        Player->SetShowMouseCursor(true);\n        FInputModeGameAndUI Mode;\n        Mode.SetWidgetToFocus(Widget->TakeWidget());\n        Mode.SetHideCursorDuringCapture(false);\n        Player->SetInputMode(Mode);\n    }\n}\n\nvoid UNarrativeStoryPanelComponent::EndPlay(const EEndPlayReason::Type Reason)\n{\n    if (Widget) Widget->RemoveFromParent();\n    Widget = nullptr;\n    Super::EndPlay(Reason);\n}\n";

/** templates/unreal/Panel.h */
export const PANEL_H = "// Generated by Narrative Bridge. Puts the story panel on screen for the story next to it.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"NarrativeStoryPanel.generated.h\"\n\nclass UNarrativeStoryWidget;\nclass UNarrativeThemeAsset;\n\n/**\n * Shows the story of the Narrative Bridge component on the same actor in a Narrative Story Widget: the themed story panel.\n * It puts the widget on the first player's screen when play begins and lets the mouse reach it.\n */\nUCLASS(ClassGroup = (NarrativeBridge), meta = (BlueprintSpawnableComponent, DisplayName = \"Narrative Story Panel\"))\nclass __API__ UNarrativeStoryPanelComponent : public UActorComponent\n{\n    GENERATED_BODY()\n\npublic:\n    /** The widget class: Narrative Story Widget, or a Blueprint made from it. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TSubclassOf<UNarrativeStoryWidget> WidgetClass;\n\n    /** Optional: a Narrative Theme asset. Empty: the look chosen in Narrative Bridge. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TObjectPtr<UNarrativeThemeAsset> ThemeAsset;\n\n    /** Where the panel draws among your other widgets (higher is in front). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    int32 ZOrder = 10;\n\n    /** Show the mouse cursor and let it click the panel (Game and UI input). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bShowMouseCursor = true;\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    UNarrativeStoryWidget* GetWidget() const { return Widget; }\n\nprotected:\n    virtual void BeginPlay() override;\n    virtual void EndPlay(const EEndPlayReason::Type Reason) override;\n\nprivate:\n    UPROPERTY(Transient)\n    TObjectPtr<UNarrativeStoryWidget> Widget;\n};\n";

