export const SAVE_STORAGE_H = "// Generated by Narrative Bridge.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"UObject/Interface.h\"\n#include \"NarrativeSaveStorage.generated.h\"\n\nUINTERFACE(BlueprintType, meta = (DisplayName = \"Narrative Save Storage\"))\nclass __API__ UNarrativeSaveStorage : public UInterface\n{\n    GENERATED_BODY()\n};\n\n/**\n * Where save slots are kept. Implement it (in C++ or Blueprint) and set the story component's Save Storage to keep them\n * in your game's own saves (a USaveGame, Steam Cloud, a console's save data). Keys are short names like \"slot-1\". Without\n * one, each slot is a small JSON file in Saved/SaveGames/NarrativeBridge/<story>/.\n */\nclass __API__ INarrativeSaveStorage\n{\n    GENERATED_BODY()\n\npublic:\n    UFUNCTION(BlueprintNativeEvent, BlueprintCallable, Category = \"Narrative Bridge\")\n    void WriteSave(const FString& Key, const FString& Data);\n\n    /** The data saved under Key; false when there is none. */\n    UFUNCTION(BlueprintNativeEvent, BlueprintCallable, Category = \"Narrative Bridge\")\n    bool ReadSave(const FString& Key, FString& Data);\n\n    UFUNCTION(BlueprintNativeEvent, BlueprintCallable, Category = \"Narrative Bridge\")\n    void DeleteSave(const FString& Key);\n};\n";

/** templates/unreal/Settings.cpp */
export const SETTINGS_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeSettings.h\"\n#include \"Misc/ConfigCacheIni.h\"\n\nnamespace\n{\n    const TCHAR* Section = TEXT(\"NarrativeBridge.Settings\");\n    bool bSettingsLoaded = false;\n    float TextScale = 1.f;\n    float VoiceVolume = 1.f;\n    ENarrativeTypingSpeed TypingSpeed = ENarrativeTypingSpeed::Normal;\n    ENarrativeAutoAdvance AutoAdvance = ENarrativeAutoAdvance::AsDesigned;\n    bool bHighContrast = false;\n}\n\nFSimpleMulticastDelegate& UNarrativeSettings::OnChanged()\n{\n    static FSimpleMulticastDelegate Changed;\n    return Changed;\n}\n\nconst TArray<float>& UNarrativeSettings::TextScales()\n{\n    static const TArray<float> Values = { 0.85f, 1.f, 1.15f, 1.3f, 1.5f };\n    return Values;\n}\n\nconst TArray<float>& UNarrativeSettings::VoiceVolumes()\n{\n    static const TArray<float> Values = { 1.f, 0.75f, 0.5f, 0.25f, 0.f };\n    return Values;\n}\n\nfloat UNarrativeSettings::Next(const TArray<float>& Values, float Current)\n{\n    for (int32 i = 0; i < Values.Num(); ++i)\n        if (FMath::Abs(Values[i] - Current) < 0.01f) return Values[(i + 1) % Values.Num()];\n    return Values.Num() ? Values[0] : Current;\n}\n\nvoid UNarrativeSettings::Load()\n{\n    if (bSettingsLoaded || !GConfig) return;\n    bSettingsLoaded = true;\n    GConfig->GetFloat(Section, TEXT(\"TextScale\"), TextScale, GGameUserSettingsIni);\n    GConfig->GetFloat(Section, TEXT(\"VoiceVolume\"), VoiceVolume, GGameUserSettingsIni);\n    int32 Speed = static_cast<int32>(TypingSpeed);\n    GConfig->GetInt(Section, TEXT(\"TypingSpeed\"), Speed, GGameUserSettingsIni);\n    int32 Auto = static_cast<int32>(AutoAdvance);\n    GConfig->GetInt(Section, TEXT(\"AutoAdvance\"), Auto, GGameUserSettingsIni);\n    GConfig->GetBool(Section, TEXT(\"HighContrast\"), bHighContrast, GGameUserSettingsIni);\n    TextScale = FMath::Clamp(TextScale, 0.5f, 2.f);\n    VoiceVolume = FMath::Clamp(VoiceVolume, 0.f, 1.f);\n    TypingSpeed = static_cast<ENarrativeTypingSpeed>(FMath::Clamp(Speed, 0, 3));\n    AutoAdvance = static_cast<ENarrativeAutoAdvance>(FMath::Clamp(Auto, 0, 2));\n}\n\nvoid UNarrativeSettings::Save()\n{\n    if (GConfig)\n    {\n        GConfig->SetFloat(Section, TEXT(\"TextScale\"), TextScale, GGameUserSettingsIni);\n        GConfig->SetFloat(Section, TEXT(\"VoiceVolume\"), VoiceVolume, GGameUserSettingsIni);\n        GConfig->SetInt(Section, TEXT(\"TypingSpeed\"), static_cast<int32>(TypingSpeed), GGameUserSettingsIni);\n        GConfig->SetInt(Section, TEXT(\"AutoAdvance\"), static_cast<int32>(AutoAdvance), GGameUserSettingsIni);\n        GConfig->SetBool(Section, TEXT(\"HighContrast\"), bHighContrast, GGameUserSettingsIni);\n        GConfig->Flush(false, GGameUserSettingsIni);\n    }\n    OnChanged().Broadcast();\n}\n\nfloat UNarrativeSettings::GetTextScale() { Load(); return TextScale; }\nvoid UNarrativeSettings::SetTextScale(float Scale) { Load(); TextScale = FMath::Clamp(Scale, 0.5f, 2.f); Save(); }\nENarrativeTypingSpeed UNarrativeSettings::GetTypingSpeed() { Load(); return TypingSpeed; }\nvoid UNarrativeSettings::SetTypingSpeed(ENarrativeTypingSpeed Speed) { Load(); TypingSpeed = Speed; Save(); }\nENarrativeAutoAdvance UNarrativeSettings::GetAutoAdvance() { Load(); return AutoAdvance; }\nvoid UNarrativeSettings::SetAutoAdvance(ENarrativeAutoAdvance Mode) { Load(); AutoAdvance = Mode; Save(); }\nbool UNarrativeSettings::GetHighContrast() { Load(); return bHighContrast; }\nvoid UNarrativeSettings::SetHighContrast(bool bOn) { Load(); bHighContrast = bOn; Save(); }\nfloat UNarrativeSettings::GetVoiceVolume() { Load(); return VoiceVolume; }\nvoid UNarrativeSettings::SetVoiceVolume(float Volume) { Load(); VoiceVolume = FMath::Clamp(Volume, 0.f, 1.f); Save(); }\n\nfloat UNarrativeSettings::SpeedMultiplier()\n{\n    switch (GetTypingSpeed())\n    {\n    case ENarrativeTypingSpeed::Slow: return 0.5f;\n    case ENarrativeTypingSpeed::Fast: return 2.f;\n    case ENarrativeTypingSpeed::Instant: return 0.f;\n    default: return 1.f;\n    }\n}\n\nvoid UNarrativeSettings::ResetSettings()\n{\n    Load();\n    TextScale = 1.f;\n    VoiceVolume = 1.f;\n    TypingSpeed = ENarrativeTypingSpeed::Normal;\n    AutoAdvance = ENarrativeAutoAdvance::AsDesigned;\n    bHighContrast = false;\n    Save();\n}\n";

/** templates/unreal/Settings.h */
export const SETTINGS_H = "// Generated by Narrative Bridge.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Kismet/BlueprintFunctionLibrary.h\"\n#include \"NarrativeSettings.generated.h\"\n\nUENUM(BlueprintType)\nenum class ENarrativeTypingSpeed : uint8\n{\n    Slow,\n    Normal,\n    Fast,\n    Instant\n};\n\nUENUM(BlueprintType)\nenum class ENarrativeAutoAdvance : uint8\n{\n    /** Follow the theme's Auto Advance. */\n    AsDesigned,\n    Off,\n    On\n};\n\n/**\n * The player's own reading settings: text size, typing speed, going on by itself, high contrast and voice volume. The story\n * panel's Settings button changes them; your game's own options menu can too. They're kept in GameUserSettings and shared\n * by every Narrative Bridge story in the game. OnChanged is raised after each change.\n */\nUCLASS()\nclass __API__ UNarrativeSettings : public UBlueprintFunctionLibrary\n{\n    GENERATED_BODY()\n\npublic:\n    /** Text size, as a multiple of the theme's (0.5 to 2). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Settings\")\n    static float GetTextScale();\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Settings\")\n    static void SetTextScale(float Scale);\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Settings\")\n    static ENarrativeTypingSpeed GetTypingSpeed();\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Settings\")\n    static void SetTypingSpeed(ENarrativeTypingSpeed Speed);\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Settings\")\n    static ENarrativeAutoAdvance GetAutoAdvance();\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Settings\")\n    static void SetAutoAdvance(ENarrativeAutoAdvance Mode);\n\n    /** Light text on a solid dark panel, whatever the theme's colours. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Settings\")\n    static bool GetHighContrast();\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Settings\")\n    static void SetHighContrast(bool bOn);\n\n    /** Voice clip volume, as a multiple of the theme's (0 to 1). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Settings\")\n    static float GetVoiceVolume();\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Settings\")\n    static void SetVoiceVolume(float Volume);\n\n    /** How fast text types, as a multiple of the theme's speed; 0 shows each line at once. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge|Settings\")\n    static float SpeedMultiplier();\n\n    /** Back to the theme's own look and pacing. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge|Settings\")\n    static void ResetSettings();\n\n    /** The text sizes and voice volumes the Settings menu steps through. */\n    static const TArray<float>& TextScales();\n    static const TArray<float>& VoiceVolumes();\n\n    /** The value after Current in Values (for menus that step through choices). */\n    static float Next(const TArray<float>& Values, float Current);\n\n    /** Raised after any setting changes, so story panels redraw. */\n    static FSimpleMulticastDelegate& OnChanged();\n\nprivate:\n    static void Load();\n    static void Save();\n};\n";

