export const STORY_DATA_CPP = "// Generated by Narrative Bridge. See NarrativeBridgeStoryData.h.\n#include \"NarrativeBridgeStoryData.h\"\n#include \"Dom/JsonObject.h\"\n#include \"Serialization/JsonReader.h\"\n#include \"NarrativeBridgeTypes.h\"\n#include \"Serialization/JsonSerializer.h\"\n#include \"UObject/StrongObjectPtr.h\"\n\nnamespace\n{\n    FString Str(const TSharedPtr<FJsonObject>& O, const TCHAR* Field)\n    {\n        FString Out;\n        O->TryGetStringField(Field, Out);\n        return Out;\n    }\n\n    TArray<FString> Strings(const TSharedPtr<FJsonObject>& O, const TCHAR* Field)\n    {\n        TArray<FString> Out;\n        const TArray<TSharedPtr<FJsonValue>>* Values = nullptr;\n        if (O->TryGetArrayField(Field, Values))\n            for (const TSharedPtr<FJsonValue>& V : *Values) Out.Add(V->AsString());\n        return Out;\n    }\n\n    /** The objects of an array field (none when it's missing), skipping anything that isn't an object. */\n    TArray<TSharedPtr<FJsonObject>> Objects(const TSharedPtr<FJsonObject>& O, const TCHAR* Field)\n    {\n        TArray<TSharedPtr<FJsonObject>> Out;\n        const TArray<TSharedPtr<FJsonValue>>* Values = nullptr;\n        if (O->TryGetArrayField(Field, Values))\n            for (const TSharedPtr<FJsonValue>& V : *Values)\n                if (V.IsValid() && V->Type == EJson::Object) Out.Add(V->AsObject());\n        return Out;\n    }\n}\n\nbool FNarrativeStoryInfo::ParseCondition(const TSharedPtr<FJsonObject>& Json, FNarrativeCondition& Out, FString& Error)\n{\n    if (!Json.IsValid()) { Error = TEXT(\"A condition is missing.\"); return false; }\n    const FString Type = Str(Json, TEXT(\"type\"));\n    if (Type == TEXT(\"has_item\"))\n    {\n        Out.Kind = FNarrativeCondition::EKind::HasItem;\n        Out.Variable = TEXT(\"has_\") + Str(Json, TEXT(\"itemId\"));\n        return true;\n    }\n    if (Type == TEXT(\"not\"))\n    {\n        Out.Kind = FNarrativeCondition::EKind::Not;\n        const TSharedPtr<FJsonObject>* Inner = nullptr;\n        if (!Json->TryGetObjectField(TEXT(\"condition\"), Inner)) { Error = TEXT(\"A \\\"not\\\" condition has nothing inside it.\"); return false; }\n        FNarrativeCondition Child;\n        if (!ParseCondition(*Inner, Child, Error)) return false;\n        Out.Children.Add(Child);\n        return true;\n    }\n    if (Type == TEXT(\"and\") || Type == TEXT(\"or\"))\n    {\n        Out.Kind = Type == TEXT(\"and\") ? FNarrativeCondition::EKind::And : FNarrativeCondition::EKind::Or;\n        for (const TSharedPtr<FJsonObject>& Item : Objects(Json, TEXT(\"conditions\")))\n        {\n            FNarrativeCondition Child;\n            if (!ParseCondition(Item, Child, Error)) return false;\n            Out.Children.Add(Child);\n        }\n        return true;\n    }\n    if (Type == TEXT(\"compare\"))\n    {\n        Out.Kind = FNarrativeCondition::EKind::Compare;\n        Out.Variable = Str(Json, TEXT(\"variableId\"));\n        Out.Op = Str(Json, TEXT(\"op\"));\n        const TSharedPtr<FJsonValue> Value = Json->TryGetField(TEXT(\"value\"));\n        if (!Value.IsValid()) { Error = TEXT(\"A comparison has no value.\"); return false; }\n        switch (Value->Type)\n        {\n        case EJson::Boolean: Out.Operand = FNarrativeCondition::EOperand::Bool; Out.bBool = Value->AsBool(); break;\n        case EJson::String: Out.Operand = FNarrativeCondition::EOperand::Text; Out.Text = Value->AsString(); break;\n        case EJson::Number: Out.Operand = FNarrativeCondition::EOperand::Number; Out.Number = Value->AsNumber(); break;\n        default: Error = TEXT(\"A comparison's value isn't a number, text or true/false.\"); return false;\n        }\n        return true;\n    }\n    Error = FString::Printf(TEXT(\"Unknown condition type \\\"%s\\\".\"), *Type);\n    return false;\n}\n\nbool FNarrativeStoryInfo::Parse(const FString& Text, FNarrativeStoryInfo& Out, FString& Error)\n{\n    Error.Reset();\n    Out = FNarrativeStoryInfo();\n    TSharedPtr<FJsonObject> Root;\n    if (!FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(Text), Root) || !Root.IsValid()) { Error = TEXT(\"StoryInfo.json isn't valid JSON.\"); return false; }\n    double Version = 0;\n    Root->TryGetNumberField(TEXT(\"schemaVersion\"), Version);\n    Out.SchemaVersion = static_cast<int32>(Version);\n    if (Out.SchemaVersion > NarrativeStoryInfoSchemaVersion)\n    {\n        Error = FString::Printf(TEXT(\"This story's data is version %d, but this Narrative Bridge plugin reads up to version %d. Update the plugin.\"), Out.SchemaVersion, NarrativeStoryInfoSchemaVersion);\n        return false;\n    }\n    if (Out.SchemaVersion < 1) { Error = TEXT(\"StoryInfo.json has no schemaVersion.\"); return false; }\n    Out.Title = Str(Root, TEXT(\"title\"));\n    Out.ProjectId = Str(Root, TEXT(\"projectId\"));\n    Out.StoryVersion = Str(Root, TEXT(\"storyVersion\"));\n    const FString Language = Str(Root, TEXT(\"sourceLanguage\"));\n    if (!Language.IsEmpty()) Out.SourceLanguage = Language;\n    Out.SaveFolder = Str(Root, TEXT(\"saveFolder\"));\n    for (const TSharedPtr<FJsonObject>& O : Objects(Root, TEXT(\"passages\"))) Out.Passages.Add({ Str(O, TEXT(\"id\")), Str(O, TEXT(\"title\")), Str(O, TEXT(\"act\")) });\n    for (const TSharedPtr<FJsonObject>& O : Objects(Root, TEXT(\"acts\"))) Out.Acts.Add({ Str(O, TEXT(\"id\")), Str(O, TEXT(\"title\")) });\n    for (const TSharedPtr<FJsonObject>& O : Objects(Root, TEXT(\"lines\"))) Out.Lines.Add({ Str(O, TEXT(\"path\")), Str(O, TEXT(\"text\")) });\n    Out.ItemVariables = Strings(Root, TEXT(\"itemVariables\"));\n    Out.Variables = Strings(Root, TEXT(\"variables\"));\n    Out.Exits = Strings(Root, TEXT(\"exits\"));\n    Out.Cues = Strings(Root, TEXT(\"cues\"));\n    Out.CueTags = Strings(Root, TEXT(\"cueTags\"));\n    for (const TSharedPtr<FJsonObject>& O : Objects(Root, TEXT(\"cueSounds\"))) Out.CueSounds.Add({ Str(O, TEXT(\"tag\")), Str(O, TEXT(\"file\")) });\n    for (const TSharedPtr<FJsonObject>& O : Objects(Root, TEXT(\"portraits\"))) Out.Portraits.Add({ Str(O, TEXT(\"speaker\")), Str(O, TEXT(\"file\")) });\n    Out.ReservedTags = Strings(Root, TEXT(\"reservedTags\"));\n    for (const TSharedPtr<FJsonObject>& O : Objects(Root, TEXT(\"gatedChoices\")))\n    {\n        FNarrativeStoryGatedChoice G;\n        G.Passage = Str(O, TEXT(\"passage\"));\n        G.Text = Str(O, TEXT(\"text\"));\n        G.Needs = Str(O, TEXT(\"needs\"));\n        O->TryGetBoolField(TEXT(\"forced\"), G.bForced);\n        for (const TSharedPtr<FJsonObject>& R : Objects(O, TEXT(\"requirements\")))\n        {\n            FNarrativeStoryRequirement Req;\n            Req.Words = Str(R, TEXT(\"words\"));\n            const TSharedPtr<FJsonObject>* Condition = nullptr;\n            if (!R->TryGetObjectField(TEXT(\"condition\"), Condition) || !ParseCondition(*Condition, Req.Condition, Error))\n            {\n                if (Error.IsEmpty()) Error = TEXT(\"A locked choice's requirement has no condition.\");\n                Out = FNarrativeStoryInfo();\n                return false;\n            }\n            G.Requirements.Add(Req);\n        }\n        Out.GatedChoices.Add(G);\n    }\n    return true;\n}\n\nconst FNarrativeStoryInfo& UNarrativeStoryData::Info() const\n{\n    if (!bParsed) Parse();\n    return Parsed;\n}\n\nFString UNarrativeStoryData::GetError() const\n{\n    if (!bParsed) Parse();\n    return Error;\n}\n\nvoid UNarrativeStoryData::Parse() const\n{\n    bParsed = true;\n    FNarrativeStoryInfo::Parse(Json, Parsed, Error);\n}\n\nUNarrativeStoryData* UNarrativeStoryData::GetDefault()\n{\n    static TStrongObjectPtr<UNarrativeStoryData> Loaded;\n    if (!Loaded.IsValid()) Loaded.Reset(LoadObject<UNarrativeStoryData>(nullptr, NarrativeBridge::StoryDataAssetPath, nullptr, LOAD_NoWarn | LOAD_Quiet));\n    return Loaded.Get();\n}\n\nconst FNarrativeStoryInfo& UNarrativeStoryData::DefaultInfo()\n{\n    static const FNarrativeStoryInfo Empty;\n    const UNarrativeStoryData* Data = GetDefault();\n    return Data ? Data->Info() : Empty;\n}\n";

/** templates/unreal/StoryData.h */
export const STORY_DATA_H = "// Generated by Narrative Bridge. The story's passages, lines, acts, items, cues and the conditions of its locked choices,\n// read from StorySource/StoryInfo.json (schemas/unreal-story-info.schema.json). The data asset holds the JSON text, so it\n// cooks with the game and needs no staging; the runtime parses it once into the plain structs below.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Engine/DataAsset.h\"\n#include \"NarrativeBridgeCondition.h\"\n#include \"NarrativeBridgeStoryData.generated.h\"\n\n/** The newest StoryInfo.json this plugin reads. A newer one is refused with a clear message; older ones and unknown fields are fine. */\nconstexpr int32 NarrativeStoryInfoSchemaVersion = 1;\n\nstruct FNarrativeStoryPassage { FString Id; FString Title; FString Act; };\nstruct FNarrativeStoryAct { FString Id; FString Title; };\nstruct FNarrativeStoryLine { FString Path; FString Text; };\nstruct FNarrativeStoryCueSound { FString Tag; FString File; };\nstruct FNarrativeStoryPortrait { FString Speaker; FString File; };\nstruct FNarrativeStoryRequirement { FString Words; FNarrativeCondition Condition; };\n\n/** A choice that needs an item or a value: Ink leaves it out while it's locked. */\nstruct FNarrativeStoryGatedChoice\n{\n    FString Passage;\n    FString Text;\n    /** What it needs, in words (e.g. \"Archive Key\"). */\n    FString Needs;\n    /** While it's on offer it's the only choice in its passage, so nothing else is shown as locked. */\n    bool bForced = false;\n    TArray<FNarrativeStoryRequirement> Requirements;\n};\n\n/** Everything StoryInfo.json says, as plain structs. */\nstruct __API__ FNarrativeStoryInfo\n{\n    int32 SchemaVersion = 0;\n    FString Title;\n    FString ProjectId;\n    /** Changes whenever the generated Ink changes. Saves from another version are carried over by replaying their choices. */\n    FString StoryVersion;\n    /** The language the story is written in (the translation sheet's \"source\" column). */\n    FString SourceLanguage = TEXT(\"en\");\n    /** Save slots go in Saved/SaveGames/NarrativeBridge/<this>/. */\n    FString SaveFolder;\n    TArray<FNarrativeStoryPassage> Passages;\n    TArray<FNarrativeStoryAct> Acts;\n    TArray<FNarrativeStoryLine> Lines;\n    TArray<FString> ItemVariables;\n    TArray<FString> Variables;\n    TArray<FString> Exits;\n    TArray<FString> Cues;\n    TArray<FString> CueTags;\n    TArray<FNarrativeStoryCueSound> CueSounds;\n    TArray<FNarrativeStoryPortrait> Portraits;\n    TArray<FString> ReservedTags;\n    TArray<FNarrativeStoryGatedChoice> GatedChoices;\n\n    /** Reads StoryInfo.json's text. False, with Error filled, when it isn't valid or is from a newer Narrative Bridge. */\n    static bool Parse(const FString& Json, FNarrativeStoryInfo& Out, FString& Error);\n\n    /** Reads a condition tree (an ISR condition as JSON). */\n    static bool ParseCondition(const TSharedPtr<FJsonObject>& Json, FNarrativeCondition& Out, FString& Error);\n};\n\n/** The story's data as an asset (Content/NarrativeBridge/StoryData), made from StorySource/StoryInfo.json by the editor module. */\nUCLASS(BlueprintType)\nclass __API__ UNarrativeStoryData : public UDataAsset\n{\n    GENERATED_BODY()\n\npublic:\n    /** StoryInfo.json, as text. */\n    UPROPERTY(EditAnywhere, Category = \"Narrative Bridge\", meta = (MultiLine = \"true\"))\n    FString Json;\n\n    /** Replaces the JSON (the editor does this when the story is imported again). */\n    void SetJson(const FString& NewJson) { Json = NewJson; bParsed = false; }\n\n    /** The story data at NarrativeBridge::StoryDataAssetPath (the one imported from StorySource/), or null. */\n    static UNarrativeStoryData* GetDefault();\n\n    /** The default story data's info, or an empty one when there is none (the project hasn't imported its story yet). */\n    static const FNarrativeStoryInfo& DefaultInfo();\n\n    /** The parsed data (parsed the first time it's asked for). Empty when the JSON can't be read: see GetError. */\n    const FNarrativeStoryInfo& Info() const;\n\n    /** Why the JSON couldn't be read, or empty. */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FString GetError() const;\n\nprivate:\n    void Parse() const;\n\n    mutable FNarrativeStoryInfo Parsed;\n    mutable FString Error;\n    mutable bool bParsed = false;\n};\n";

/** templates/unreal/Theme.cpp */
export const THEME_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeTheme.h\"\n#include \"NarrativeBridgeTypes.h\"\n#include \"JsonObjectConverter.h\"\n#include \"Misc/FileHelper.h\"\n#include \"Misc/Paths.h\"\n\nbool UNarrativeThemeLibrary::LoadStoryTheme(FNarrativeTheme& Theme)\n{\n    Theme = FNarrativeTheme();\n    FString Json;\n    if (!FFileHelper::LoadFileToString(Json, *(FPaths::ProjectContentDir() / NarrativeBridge::ThemeFile))) return false;\n    return FJsonObjectConverter::JsonObjectStringToUStruct(Json, &Theme, 0, 0);\n}\n\nFVector4 UNarrativeThemeLibrary::PanelRect(const FNarrativeTheme& Theme)\n{\n    // The theme keeps the corners from the bottom left (as Narrative Bridge shows them); UMG counts from the top.\n    return FVector4(Theme.PanelXMin, 1.f - Theme.PanelYMax, Theme.PanelXMax, 1.f - Theme.PanelYMin);\n}\n";

/** templates/unreal/Trigger.cpp */
export const TRIGGER_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeStoryTrigger.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"GameFramework/Pawn.h\"\n#include \"Kismet/GameplayStatics.h\"\n\nvoid UNarrativeStoryTriggerComponent::BeginPlay()\n{\n    Super::BeginPlay();\n    AActor* Owner = GetOwner();\n    if (!Owner) return;\n    Story = Owner->FindComponentByClass<UNarrativeBridgeComponent>();\n    Owner->OnActorBeginOverlap.AddDynamic(this, &UNarrativeStoryTriggerComponent::HandleOverlap);\n    if (Story)\n    {\n        Story->OnEnded.AddDynamic(this, &UNarrativeStoryTriggerComponent::HandleStop);\n        Story->OnExit.AddDynamic(this, &UNarrativeStoryTriggerComponent::HandleExit);\n    }\n}\n\nvoid UNarrativeStoryTriggerComponent::HandleOverlap(AActor* OverlappedActor, AActor* OtherActor)\n{\n    const APawn* Pawn = Cast<APawn>(OtherActor);\n    if (Pawn && Pawn->IsPlayerControlled()) Trigger();\n}\n\nvoid UNarrativeStoryTriggerComponent::Trigger()\n{\n    if (!Story || (bOnce && bDone)) return;\n    bDone = true;\n    if (bPauseGame) UGameplayStatics::SetGamePaused(this, true);\n    if (Passage.IsEmpty()) Story->StartStory();\n    else Story->StartAt(Passage);\n}\n\nvoid UNarrativeStoryTriggerComponent::HandleStop()\n{\n    if (bPauseGame) UGameplayStatics::SetGamePaused(this, false);\n}\n\nvoid UNarrativeStoryTriggerComponent::HandleExit(const FString& ExitName)\n{\n    // The game plays at an exit, until it calls Resume.\n    HandleStop();\n}\n";

/** templates/unreal/Trigger.h */
export const TRIGGER_H = "// Generated by Narrative Bridge. Starts the story when the player walks into the actor.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Components/ActorComponent.h\"\n#include \"NarrativeStoryTrigger.generated.h\"\n\nclass UNarrativeBridgeComponent;\n\n/**\n * Starts the story (or a passage of it) when the player's pawn overlaps this actor, e.g. a Trigger Box or a character to\n * talk to: turn off Start On Begin Play on the actor's Narrative Bridge component. Optionally pauses the game while the\n * dialogue runs, and lets it go on at an exit to the game and at the ending.\n */\nUCLASS(ClassGroup = (NarrativeBridge), meta = (BlueprintSpawnableComponent, DisplayName = \"Narrative Story Trigger\"))\nclass __API__ UNarrativeStoryTriggerComponent : public UActorComponent\n{\n    GENERATED_BODY()\n\npublic:\n    /** The passage to start at (one of the story's passages), or empty for the beginning. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    FString Passage;\n\n    /** Only the first time the player walks in. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bOnce = true;\n\n    /** Pause the game while the dialogue runs. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bPauseGame = false;\n\n    /** Starts the story now, as walking in does. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Trigger();\n\nprotected:\n    virtual void BeginPlay() override;\n\nprivate:\n    UFUNCTION()\n    void HandleOverlap(AActor* OverlappedActor, AActor* OtherActor);\n\n    UFUNCTION()\n    void HandleStop();\n\n    UFUNCTION()\n    void HandleExit(const FString& ExitName);\n\n    UPROPERTY(Transient)\n    TObjectPtr<UNarrativeBridgeComponent> Story;\n\n    bool bDone = false;\n};\n";

/** templates/unreal/Types.h */
export const TYPES_H = "// Generated by Narrative Bridge. The values the story component hands to Blueprint and C++.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"NarrativeBridgeTypes.generated.h\"\n\n/** The same for every story: where the editor puts the story's assets, and the words Ink uses for Continue breaks and exits. */\nnamespace NarrativeBridge\n{\n    /** The Ink story asset the editor imports from StorySource/MainStory.ink. */\n    static const TCHAR* StoryAssetPath = TEXT(\"/Game/NarrativeBridge/MainStory.MainStory\");\n    /** The story data asset (UNarrativeStoryData) the editor makes from StorySource/StoryInfo.json. */\n    static const TCHAR* StoryDataAssetPath = TEXT(\"/Game/NarrativeBridge/StoryData.StoryData\");\n    /** Where the editor imports the voice clips and cue sounds (StorySource/VoiceClips). */\n    static const TCHAR* AudioPackagePath = TEXT(\"/Game/NarrativeBridge/Audio/\");\n    /** The story's files read while the game runs, under Content/ (staged with the game; see Config/DefaultGame.ini). */\n    static const TCHAR* ThemeFile = TEXT(\"NarrativeBridge/Data/Theme.json\");\n    static const TCHAR* TranslationsFile = TEXT(\"NarrativeBridge/Data/Translations.csv\");\n    static const TCHAR* ImageFolder = TEXT(\"NarrativeBridge/Data/Images/\");\n    /** The text of a Continue break's only choice, and the text before an exit's name (see the Ink conventions). */\n    static const TCHAR* ContinueText = TEXT(\"Continue\");\n    static const TCHAR* ExitPrefix = TEXT(\"Back to the game: \");\n}\n\n/** A line of the story, as the component shows it (OnLineShown) and keeps it (GetTranscript). */\nUSTRUCT(BlueprintType)\nstruct FNarrativeLine\n{\n    GENERATED_BODY()\n\n    /** The speaker's name as written in the story (in the current language), or empty for narration. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Speaker;\n\n    /** The speaker's character id (the #speaker tag), e.g. for LoadPortrait; empty for narration. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString SpeakerId;\n\n    /** The line's text, with the script's emphasis as <i>, <b> and <u> (see PlainText and RichText). */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Text;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    TArray<FString> Tags;\n\n    /** The scene heading this line opens (from #scene), or empty. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Scene;\n\n    /** A stage direction for the speaker (from #paren), or empty. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Paren;\n\n    /** The scene picture this line opens (a file name from #image), or empty. See LoadPicture. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Image;\n\n    /** The recorded clip for this line (a file name from #audio), or empty. See LoadVoiceClip. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString VoiceClip;\n\n    /** A choice the player made (kept in the transcript), not story text. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    bool bIsChoice = false;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    bool bIsTransition = false;\n\n    /** A cutscene line (#cutscene): the story panel shows it alone, then goes on by itself. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    bool bIsCutscene = false;\n\n    /** The text, speaker, scene and stage direction as written (the others are in the current language). */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString SourceText;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString SourceSpeaker;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString SourceScene;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString SourceParen;\n};\n\n/** A choice the reader can't take yet: its text, and what it needs in plain words. */\nUSTRUCT(BlueprintType)\nstruct FNarrativeLockedChoice\n{\n    GENERATED_BODY()\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Text;\n\n    /** What it needs, e.g. \"Brass Key\" or \"trust at least 2\". */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Needs;\n};\n\n/** What a save slot holds: when it was saved, where, and the last line read. */\nUSTRUCT(BlueprintType)\nstruct FNarrativeSlotInfo\n{\n    GENERATED_BODY()\n\n    /** The slot's number: 0 is the autosave, 1 and up the player's. */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    int32 Slot = 0;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    bool bExists = false;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FDateTime SavedAt;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Passage;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString PassageTitle;\n\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    FString Excerpt;\n\n    /** The save is from an earlier version of the story (it loads by replaying its choices). */\n    UPROPERTY(BlueprintReadOnly, Category = \"Narrative Bridge\")\n    bool bOtherVersion = false;\n};\n\n/** What kind of value a story variable holds. */\nUENUM(BlueprintType)\nenum class ENarrativeValueType : uint8\n{\n    None,\n    Bool,\n    Int,\n    Float,\n    String,\n};\n\n/** A story variable's value: a bool, an int, a float or a string. Ours, so Blueprints don't depend on the Ink runtime. */\nUSTRUCT(BlueprintType)\nstruct FNarrativeValue\n{\n    GENERATED_BODY()\n\n    UPROPERTY(BlueprintReadWrite, Category = \"Narrative Bridge\")\n    ENarrativeValueType Type = ENarrativeValueType::None;\n\n    UPROPERTY(BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bValue = false;\n\n    UPROPERTY(BlueprintReadWrite, Category = \"Narrative Bridge\")\n    int32 IntValue = 0;\n\n    UPROPERTY(BlueprintReadWrite, Category = \"Narrative Bridge\")\n    float FloatValue = 0.f;\n\n    UPROPERTY(BlueprintReadWrite, Category = \"Narrative Bridge\")\n    FString StringValue;\n\n    static FNarrativeValue FromBool(bool V) { FNarrativeValue R; R.Type = ENarrativeValueType::Bool; R.bValue = V; return R; }\n    static FNarrativeValue FromInt(int32 V) { FNarrativeValue R; R.Type = ENarrativeValueType::Int; R.IntValue = V; return R; }\n    static FNarrativeValue FromFloat(float V) { FNarrativeValue R; R.Type = ENarrativeValueType::Float; R.FloatValue = V; return R; }\n    static FNarrativeValue FromString(const FString& V) { FNarrativeValue R; R.Type = ENarrativeValueType::String; R.StringValue = V; return R; }\n\n    bool IsSet() const { return Type != ENarrativeValueType::None; }\n\n    /** \"true\", \"3\", \"2.5\" or the text itself; empty when it holds nothing. */\n    FString ToString() const\n    {\n        switch (Type)\n        {\n        case ENarrativeValueType::Bool: return bValue ? TEXT(\"true\") : TEXT(\"false\");\n        case ENarrativeValueType::Int: return FString::FromInt(IntValue);\n        case ENarrativeValueType::Float: return FString::SanitizeFloat(FloatValue);\n        case ENarrativeValueType::String: return StringValue;\n        default: return FString();\n        }\n    }\n};\n";

