export const WIDGET_CPP = "// Generated by Narrative Bridge.\n#include \"NarrativeStoryWidget.h\"\n#include \"NarrativeBridgeComponent.h\"\n#include \"NarrativeLocalization.h\"\n#include \"NarrativeSettings.h\"\n#include \"Blueprint/WidgetTree.h\"\n#include \"Components/Border.h\"\n#include \"Components/BorderSlot.h\"\n#include \"Components/ButtonSlot.h\"\n#include \"Components/CanvasPanel.h\"\n#include \"Components/CanvasPanelSlot.h\"\n#include \"Components/HorizontalBox.h\"\n#include \"Components/HorizontalBoxSlot.h\"\n#include \"Components/Image.h\"\n#include \"Components/RichTextBlock.h\"\n#include \"Components/ScaleBox.h\"\n#include \"Components/ScrollBox.h\"\n#include \"Components/TextBlock.h\"\n#include \"Components/VerticalBox.h\"\n#include \"Components/VerticalBoxSlot.h\"\n#include \"Engine/DataTable.h\"\n#include \"Engine/Font.h\"\n#include \"Engine/Texture2D.h\"\n#include \"Framework/Application/SlateApplication.h\"\n#include \"Styling/CoreStyle.h\"\n\nnamespace\n{\n    /** The length of the emphasis tag (<i>, </b>, …) starting at i, or 0. */\n    int32 TagLength(const FString& S, int32 i)\n    {\n        if (S[i] != TEXT('<')) return 0;\n        const bool bClose = i + 1 < S.Len() && S[i + 1] == TEXT('/');\n        const int32 Letter = i + (bClose ? 2 : 1);\n        if (Letter + 1 >= S.Len() || S[Letter + 1] != TEXT('>')) return 0;\n        const TCHAR L = S[Letter];\n        return L == TEXT('i') || L == TEXT('b') || L == TEXT('u') ? (bClose ? 4 : 3) : 0;\n    }\n\n    bool EndsSentence(TCHAR C) { return C == TEXT('.') || C == TEXT('!') || C == TEXT('?'); }\n\n    FSlateBrush Rounded(const FLinearColor& Colour, float Radius = 6.f)\n    {\n        FSlateBrush B;\n        B.DrawAs = ESlateBrushDrawType::RoundedBox;\n        B.TintColor = FSlateColor(Colour);\n        B.OutlineSettings.RoundingType = ESlateBrushRoundingType::FixedRadius;\n        B.OutlineSettings.CornerRadii = FVector4(Radius, Radius, Radius, Radius);\n        return B;\n    }\n\n    ETextJustify::Type Justify(const FString& Align)\n    {\n        return Align == TEXT(\"center\") ? ETextJustify::Center : Align == TEXT(\"right\") ? ETextJustify::Right : ETextJustify::Left;\n    }\n}\n\n// ---- Emphasis -------------------------------------------------------------------------------\n\nint32 UNarrativeStoryWidget::VisibleLength(const FString& Text)\n{\n    int32 N = 0;\n    for (int32 i = 0; i < Text.Len();)\n    {\n        const int32 Tag = TagLength(Text, i);\n        if (Tag) { i += Tag; continue; }\n        ++N;\n        ++i;\n    }\n    return N;\n}\n\nFString UNarrativeStoryWidget::VisiblePrefix(const FString& Text, int32 Count)\n{\n    FString Out;\n    TArray<TCHAR> Open;\n    int32 Shown = 0;\n    for (int32 i = 0; i < Text.Len();)\n    {\n        const int32 Tag = TagLength(Text, i);\n        if (Tag)\n        {\n            const TCHAR L = Text[i + Tag - 2];\n            if (Tag == 3) Open.Add(L);\n            else if (Open.Num() && Open.Last() == L) Open.Pop();\n            Out += Text.Mid(i, Tag);\n            i += Tag;\n            continue;\n        }\n        if (Shown >= Count) break;\n        Out.AppendChar(Text[i]);\n        ++Shown;\n        ++i;\n    }\n    while (Open.Num()) Out += FString::Printf(TEXT(\"</%c>\"), Open.Pop());\n    return Out;\n}\n\nFString UNarrativeStoryWidget::ToRichMarkup(const FString& Text)\n{\n    // Rich Text Blocks don't nest styles: the innermost emphasis shows.\n    FString Out;\n    TArray<TCHAR> Open;\n    for (int32 i = 0; i < Text.Len();)\n    {\n        const int32 Tag = TagLength(Text, i);\n        if (Tag)\n        {\n            const TCHAR L = Text[i + Tag - 2];\n            if (Open.Num()) Out += TEXT(\"</>\");\n            if (Tag == 3) Open.Add(L);\n            else if (Open.Num() && Open.Last() == L) Open.Pop();\n            if (Open.Num()) Out += FString::Printf(TEXT(\"<%c>\"), Open.Last());\n            i += Tag;\n            continue;\n        }\n        const TCHAR C = Text[i++];\n        if (C == TEXT('<')) Out += TEXT(\"&lt;\");\n        else if (C == TEXT('>')) Out += TEXT(\"&gt;\");\n        else if (C == TEXT('&')) Out += TEXT(\"&amp;\");\n        else if (C == TEXT('\"')) Out += TEXT(\"&quot;\");\n        else Out.AppendChar(C);\n    }\n    if (Open.Num()) Out += TEXT(\"</>\");\n    return Out;\n}\n\n// ---- Setup ----------------------------------------------------------------------------------\n\nTSharedRef<SWidget> UNarrativeStoryWidget::RebuildWidget()\n{\n    if (WidgetTree && !WidgetTree->RootWidget)\n    {\n        Root = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT(\"Root\"));\n        WidgetTree->RootWidget = Root;\n        LoadTheme();\n        Layout();\n    }\n    return Super::RebuildWidget();\n}\n\nvoid UNarrativeStoryWidget::NativeConstruct()\n{\n    Super::NativeConstruct();\n    SetIsFocusable(true);\n    SettingsHandle = UNarrativeSettings::OnChanged().AddUObject(this, &UNarrativeStoryWidget::Rebuild);\n    LanguageHandle = UNarrativeLocalization::OnChanged().AddUObject(this, &UNarrativeStoryWidget::Rebuild);\n}\n\nvoid UNarrativeStoryWidget::NativeDestruct()\n{\n    UNarrativeSettings::OnChanged().Remove(SettingsHandle);\n    UNarrativeLocalization::OnChanged().Remove(LanguageHandle);\n    Bind(false);\n    Super::NativeDestruct();\n}\n\nvoid UNarrativeStoryWidget::SetStory(UNarrativeBridgeComponent* InStory)\n{\n    Bind(false);\n    Story = InStory;\n    Bind(true);\n    if (Story) Story->VoiceVolume = Theme.VoiceVolume;\n    Redraw();\n}\n\nvoid UNarrativeStoryWidget::Bind(bool bOn)\n{\n    if (!Story) return;\n    if (bOn)\n    {\n        Story->OnLineShown.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleLine);\n        Story->OnChoices.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleChoices);\n        Story->OnContinue.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleContinue);\n        Story->OnEnded.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleEnded);\n        Story->OnExit.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleExit);\n        Story->OnResumed.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleResumed);\n        Story->OnRestarted.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleRestarted);\n        Story->OnStatusChanged.AddUniqueDynamic(this, &UNarrativeStoryWidget::HandleStatus);\n    }\n    else\n    {\n        Story->OnLineShown.RemoveAll(this);\n        Story->OnChoices.RemoveAll(this);\n        Story->OnContinue.RemoveAll(this);\n        Story->OnEnded.RemoveAll(this);\n        Story->OnExit.RemoveAll(this);\n        Story->OnResumed.RemoveAll(this);\n        Story->OnRestarted.RemoveAll(this);\n        Story->OnStatusChanged.RemoveAll(this);\n    }\n}\n\nvoid UNarrativeStoryWidget::LoadTheme()\n{\n    if (ThemeAsset) Theme = ThemeAsset->Theme;\n    else UNarrativeThemeLibrary::LoadStoryTheme(Theme);\n    if (UNarrativeSettings::GetHighContrast())\n    {\n        // Light text on a solid dark panel, whatever the theme's colours.\n        Theme.Background = FLinearColor(0.f, 0.f, 0.f, 1.f);\n        Theme.PanelOpacity = 1.f;\n        Theme.Text = Theme.ChoiceTextColour = FLinearColor::White;\n        Theme.SpeakerColour = Theme.Accent = Theme.BorderColour = FLinearColor(1.f, 0.65f, 0.12f, 1.f);\n        Theme.SceneColour = Theme.Muted = FLinearColor(0.8f, 0.8f, 0.8f, 1.f);\n        Theme.ButtonColour = FLinearColor(1.f, 1.f, 1.f, 1.f);\n        Theme.ButtonOpacity = FMath::Max(Theme.ButtonOpacity, 0.25f);\n    }\n}\n\nvoid UNarrativeStoryWidget::Rebuild()\n{\n    if (!Root) return;\n    LoadTheme();\n    Layout();\n    Redraw();\n}\n\nFString UNarrativeStoryWidget::T(const FString& Source) const\n{\n    return UNarrativeLocalization::Translate(Source);\n}\n\nint32 UNarrativeStoryWidget::FontSize(float Scale) const\n{\n    // The theme's sizes are pixels at its reference resolution; Slate's are points (3/4 of a pixel).\n    return FMath::Max(6, FMath::RoundToInt(Theme.FontSize * Scale * UNarrativeSettings::GetTextScale() * 0.75f));\n}\n\nFSlateFontInfo UNarrativeStoryWidget::Font(int32 Size, const TCHAR* Typeface) const\n{\n    if (FontFamily) return FSlateFontInfo(FontFamily, Size, FName(Typeface));\n    return FCoreStyle::GetDefaultFontStyle(FName(Typeface), Size);\n}\n\nUDataTable* UNarrativeStoryWidget::Styles(int32 Size, const FLinearColor& Colour)\n{\n    const FString Key = FString::Printf(TEXT(\"%d %s\"), Size, *Colour.ToString());\n    if (TObjectPtr<UDataTable>* Found = StyleTables.Find(Key)) return *Found;\n    UDataTable* Table = NewObject<UDataTable>(this);\n    Table->RowStruct = FRichTextStyleRow::StaticStruct();\n    auto Add = [&](const TCHAR* Name, const TCHAR* Typeface, bool bUnderline)\n    {\n        FRichTextStyleRow Row;\n        Row.TextStyle.SetFont(Font(Size, Typeface));\n        Row.TextStyle.SetColorAndOpacity(FSlateColor(Colour));\n        if (bUnderline) Row.TextStyle.SetUnderlineBrush(FSlateColorBrush(Colour));\n        Table->AddRow(FName(Name), Row);\n    };\n    Add(TEXT(\"Default\"), TEXT(\"Regular\"), false);\n    Add(TEXT(\"i\"), TEXT(\"Italic\"), false);\n    Add(TEXT(\"b\"), TEXT(\"Bold\"), false);\n    Add(TEXT(\"u\"), TEXT(\"Regular\"), true);\n    StyleTables.Add(Key, Table);\n    return Table;\n}\n\nUTextBlock* UNarrativeStoryWidget::Text(const FString& Content, int32 Size, const FLinearColor& Colour, const TCHAR* Typeface)\n{\n    UTextBlock* Block = WidgetTree->ConstructWidget<UTextBlock>();\n    Block->SetText(FText::FromString(Content));\n    Block->SetFont(Font(Size, Typeface));\n    Block->SetColorAndOpacity(FSlateColor(Colour));\n    Block->SetAutoWrapText(true);\n    Block->SetLineHeightPercentage(Theme.LineSpacing);\n    return Block;\n}\n\nURichTextBlock* UNarrativeStoryWidget::Rich(const FString& Markup, int32 Size, const FLinearColor& Colour)\n{\n    URichTextBlock* Block = WidgetTree->ConstructWidget<URichTextBlock>();\n    Block->SetTextStyleSet(Styles(Size, Colour));\n    Block->SetAutoWrapText(true);\n    Block->SetLineHeightPercentage(Theme.LineSpacing);\n    Block->SetJustification(Justify(Theme.TextAlign));\n    Block->SetText(FText::FromString(Markup));\n    return Block;\n}\n\nUNarrativePanelButton* UNarrativeStoryWidget::Button(UVerticalBox* Into, const FString& Label, TFunction<void()> Action, bool bEnabled, float Scale, bool bChosen)\n{\n    UNarrativePanelButton* B = WidgetTree->ConstructWidget<UNarrativePanelButton>();\n    FButtonStyle Style;\n    Style.SetNormal(Rounded(Faded(Theme.ButtonColour, Theme.ButtonOpacity)));\n    Style.SetHovered(Rounded(Faded(Theme.ButtonColour, Theme.ButtonHoverOpacity)));\n    Style.SetPressed(Rounded(Faded(Theme.ButtonColour, FMath::Min(1.f, Theme.ButtonHoverOpacity + 0.15f))));\n    Style.SetDisabled(Rounded(Faded(Theme.ButtonColour, Theme.ButtonOpacity * 0.4f)));\n    Style.SetNormalPadding(FMargin(0));\n    Style.SetPressedPadding(FMargin(0));\n    B->SetStyle(Style);\n    const int32 Size = FontSize(Theme.ChoiceScale * Scale);\n    URichTextBlock* Caption = Rich(ToRichMarkup(Label), Size, !bEnabled ? Faded(Theme.Muted, 0.8f) : bChosen ? Theme.Muted : Theme.ChoiceTextColour);\n    Caption->SetJustification(Theme.ChoiceAlign == TEXT(\"center\") ? ETextJustify::Center : ETextJustify::Left);\n    UButtonSlot* Content = Cast<UButtonSlot>(B->AddChild(Caption));\n    const float Vertical = FMath::Max(2.f, (Theme.ChoiceHeight - 1.f) * Size * 0.6f);\n    Content->SetPadding(FMargin(Size * 0.8f, Vertical));\n    Content->SetHorizontalAlignment(HAlign_Fill);\n    B->SetIsEnabled(bEnabled);\n    B->Action = MoveTemp(Action);\n    B->Bind();\n    if (Into)\n    {\n        UVerticalBoxSlot* Row = Into->AddChildToVerticalBox(B);\n        Row->SetPadding(FMargin(0, 0, 0, Theme.ChoiceSpacing * Size));\n        Row->SetHorizontalAlignment(HAlign_Fill);\n    }\n    return B;\n}\n\nUNarrativePanelButton* UNarrativeStoryWidget::ToolButton(const FString& Label, TFunction<void()> Action)\n{\n    UNarrativePanelButton* B = Button(nullptr, Label, MoveTemp(Action), true, 0.75f);\n    UHorizontalBoxSlot* Place = Toolbar->AddChildToHorizontalBox(B);\n    Place->SetPadding(FMargin(0, 0, FontSize(0.4f), 0));\n    Place->SetVerticalAlignment(VAlign_Center);\n    return B;\n}\n\nvoid UNarrativeStoryWidget::Layout()\n{\n    Root->ClearChildren();\n    StyleTables.Reset();\n    ChoiceButtons.Reset();\n    ContinueButton = nullptr;\n    TypingBlock = nullptr;\n    Fading.Reset();\n    FadeSeconds.Reset();\n    bMenuOpen = false;\n\n    // The scene picture, full screen behind the panel, and a shade over it.\n    PictureBox = WidgetTree->ConstructWidget<UScaleBox>();\n    PictureBox->SetStretch(Theme.PictureFit == TEXT(\"contain\") ? EStretch::ScaleToFit : EStretch::ScaleToFill);\n    PictureBox->SetClipping(EWidgetClipping::ClipToBounds);\n    Picture = WidgetTree->ConstructWidget<UImage>();\n    PictureBox->AddChild(Picture);\n    UCanvasPanelSlot* PictureSlot = Root->AddChildToCanvas(PictureBox);\n    PictureSlot->SetAnchors(FAnchors(0, 0, 1, 1));\n    PictureSlot->SetOffsets(FMargin(0));\n    PictureBox->SetVisibility(ESlateVisibility::Collapsed);\n    Dim = WidgetTree->ConstructWidget<UImage>();\n    Dim->SetColorAndOpacity(FLinearColor(0, 0, 0, Theme.PictureDim));\n    UCanvasPanelSlot* DimSlot = Root->AddChildToCanvas(Dim);\n    DimSlot->SetAnchors(FAnchors(0, 0, 1, 1));\n    DimSlot->SetOffsets(FMargin(0));\n    Dim->SetVisibility(ESlateVisibility::Collapsed);\n\n    const FVector4 Rect = UNarrativeThemeLibrary::PanelRect(Theme);\n    const bool bInside = Theme.PortraitPlacement == TEXT(\"inside\");\n\n    // The portrait, standing on the panel (or inside it, beside the text).\n    Portrait = WidgetTree->ConstructWidget<UImage>();\n    Portrait->SetVisibility(ESlateVisibility::Collapsed);\n    if (!bInside)\n    {\n        UCanvasPanelSlot* PortraitSlot = Root->AddChildToCanvas(Portrait);\n        PortraitSlot->SetAnchors(FAnchors(Rect.X, Rect.Y, Rect.X, Rect.Y));\n        PortraitSlot->SetAlignment(FVector2D(0, 1));\n        PortraitSlot->SetAutoSize(true);\n    }\n\n    // The panel: a border (when it has one) round the background.\n    Panel = WidgetTree->ConstructWidget<UBorder>();\n    Panel->SetBrush(Rounded(Theme.BorderWidth > 0 ? Theme.BorderColour : FLinearColor::Transparent, 10.f));\n    Panel->SetPadding(FMargin(Theme.BorderWidth));\n    UCanvasPanelSlot* PanelSlot = Root->AddChildToCanvas(Panel);\n    PanelSlot->SetAnchors(FAnchors(Rect.X, Rect.Y, Rect.Z, Rect.W));\n    PanelSlot->SetOffsets(FMargin(0));\n    UBorder* Back = WidgetTree->ConstructWidget<UBorder>();\n    Back->SetBrush(Rounded(Faded(Theme.Background, Theme.PanelOpacity), 8.f));\n    Back->SetPadding(FMargin(Theme.Padding));\n    Panel->SetContent(Back);\n\n    UVerticalBox* Column = WidgetTree->ConstructWidget<UVerticalBox>();\n    if (bInside)\n    {\n        UHorizontalBox* Row = WidgetTree->ConstructWidget<UHorizontalBox>();\n        const bool bRight = Theme.PortraitSide == TEXT(\"right\");\n        if (!bRight) Row->AddChildToHorizontalBox(Portrait)->SetPadding(FMargin(0, 0, Theme.Padding, 0));\n        UHorizontalBoxSlot* ColumnSlot = Row->AddChildToHorizontalBox(Column);\n        ColumnSlot->SetSize(FSlateChildSize(ESlateSizeRule::Fill));\n        if (bRight) Row->AddChildToHorizontalBox(Portrait)->SetPadding(FMargin(Theme.Padding, 0, 0, 0));\n        Back->SetContent(Row);\n    }\n    else Back->SetContent(Column);\n\n    Scroll = WidgetTree->ConstructWidget<UScrollBox>();\n    Lines = WidgetTree->ConstructWidget<UVerticalBox>();\n    Scroll->AddChild(Lines);\n    UVerticalBoxSlot* ScrollSlot = Column->AddChildToVerticalBox(Scroll);\n    ScrollSlot->SetSize(FSlateChildSize(ESlateSizeRule::Fill));\n    Choices = WidgetTree->ConstructWidget<UVerticalBox>();\n    Column->AddChildToVerticalBox(Choices)->SetPadding(FMargin(0, FontSize(0.4f), 0, 0));\n\n    Toolbar = WidgetTree->ConstructWidget<UHorizontalBox>();\n    StatusText = nullptr;\n    if (Theme.bShowToolbar)\n    {\n        Column->AddChildToVerticalBox(Toolbar)->SetPadding(FMargin(0, FontSize(0.4f), 0, 0));\n        if (Theme.bShowRestart) ToolButton(T(Theme.RestartLabel), [this] { if (Story) Story->StartStory(); });\n        // With save slots, Save and Load open the slot menu; without, they use the one quick save.\n        if (Theme.bShowSave) ToolButton(T(Theme.SaveLabel), [this] { if (!Story) return; if (Story->SaveSlots > 0) OpenSaveSlots(true); else Story->QuickSave(); });\n        if (Theme.bShowLoad) ToolButton(T(Theme.LoadLabel), [this] { if (!Story) return; if (Story->SaveSlots > 0) OpenSaveSlots(false); else Story->QuickLoad(); });\n        if (Theme.bShowSettings) ToolButton(T(Theme.SettingsLabel), [this] { if (bMenuOpen) CloseMenu(); else OpenSettings(); });\n        if (Theme.bShowStatus)\n        {\n            StatusText = Text(Story ? Story->GetStatus() : FString(), FontSize(0.6f), Theme.Muted, TEXT(\"Italic\"));\n            UHorizontalBoxSlot* Place = Toolbar->AddChildToHorizontalBox(StatusText);\n            Place->SetSize(FSlateChildSize(ESlateSizeRule::Fill));\n            Place->SetVerticalAlignment(VAlign_Center);\n        }\n    }\n\n    // The Settings and save-slot menus, over everything.\n    MenuLayer = WidgetTree->ConstructWidget<UBorder>();\n    MenuLayer->SetBrushColor(FLinearColor(0, 0, 0, 0.55f));\n    UCanvasPanelSlot* MenuSlot = Root->AddChildToCanvas(MenuLayer);\n    MenuSlot->SetAnchors(FAnchors(0, 0, 1, 1));\n    MenuSlot->SetOffsets(FMargin(0));\n    MenuLayer->SetHorizontalAlignment(HAlign_Center);\n    MenuLayer->SetVerticalAlignment(VAlign_Center);\n    UBorder* MenuBox = WidgetTree->ConstructWidget<UBorder>();\n    MenuBox->SetBrush(Rounded(Faded(Theme.Background, 1.f), 10.f));\n    MenuBox->SetPadding(FMargin(Theme.Padding));\n    MenuLayer->SetContent(MenuBox);\n    UScrollBox* MenuScroll = WidgetTree->ConstructWidget<UScrollBox>();\n    MenuList = WidgetTree->ConstructWidget<UVerticalBox>();\n    MenuScroll->AddChild(MenuList);\n    MenuBox->SetContent(MenuScroll);\n    MenuLayer->SetVisibility(ESlateVisibility::Collapsed);\n}\n\n// ---- Drawing the story ------------------------------------------------------------------------\n\nvoid UNarrativeStoryWidget::Redraw()\n{\n    if (!Root) return;\n    ClearLines();\n    ClearPrompt();\n    Pending.Reset();\n    Prompt = EPrompt::None;\n    CutsceneLeft = -1.f;\n    SetVisibility(ESlateVisibility::SelfHitTestInvisible);\n    if (!Story) return;\n    if (StatusText) StatusText->SetText(FText::FromString(Story->GetStatus()));\n    const TArray<FNarrativeLine>& All = Story->GetTranscript();\n    // What stays on screen: everything, the current scene, or the latest line.\n    int32 First = 0;\n    for (int32 i = All.Num() - 1; i >= 0 && Theme.Transcript != TEXT(\"history\"); --i)\n        if ((Theme.Transcript == TEXT(\"line\") && !All[i].bIsChoice) || (Theme.Transcript == TEXT(\"scene\") && !All[i].Scene.IsEmpty())) { First = i; break; }\n    for (int32 i = First; i < All.Num(); ++i) ShowLine(All[i], false);\n    if (!Story->IsStarted()) return;\n    Prompt = Story->IsAtExit() ? EPrompt::Exit : Story->IsWaitingForContinue() ? EPrompt::Continue : Story->HasEnded() ? EPrompt::Ended : EPrompt::Choices;\n    ShowPrompt();\n}\n\nvoid UNarrativeStoryWidget::ClearLines()\n{\n    if (Lines) Lines->ClearChildren();\n    TypingBlock = nullptr;\n}\n\nvoid UNarrativeStoryWidget::ShowLine(const FNarrativeLine& Line, bool bType)\n{\n    if (Line.bIsChoice && !Theme.bShowChoiceHistory) return;\n    // A cutscene shows one line at a time, like subtitles.\n    if (!Line.bIsChoice && (Theme.Transcript == TEXT(\"line\") || Line.bIsCutscene)) ClearLines();\n    if (!Line.Scene.IsEmpty() && Theme.Transcript == TEXT(\"scene\")) ClearLines();\n    if (Theme.bShowPictures && !Line.Image.IsEmpty()) ShowPicture(Line.Image);\n    if (Theme.bShowPortraits && !Line.bIsChoice && (!Line.SpeakerId.IsEmpty() || !Theme.bKeepPortraitForNarration)) ShowPortrait(Line.SpeakerId);\n\n    UVerticalBox* Entry = WidgetTree->ConstructWidget<UVerticalBox>();\n    const int32 Size = FontSize();\n    if (Theme.bShowSceneHeadings && !Line.Scene.IsEmpty())\n    {\n        UTextBlock* Heading = Text(Theme.bSceneUppercase ? Line.Scene.ToUpper() : Line.Scene, FontSize(Theme.SceneScale), Theme.SceneColour, TEXT(\"Bold\"));\n        Heading->SetJustification(Justify(Theme.TextAlign));\n        Entry->AddChildToVerticalBox(Heading)->SetPadding(FMargin(0, 0, 0, Size * 0.3f));\n    }\n    FString Body = Line.Text;\n    if (Line.bIsChoice) Body = FString(TEXT(\"\\u203A \")) + Line.Text;\n    else if (!Line.Speaker.IsEmpty() && Theme.bShowSpeakers)\n    {\n        const FString Name = Theme.bSpeakerUppercase ? Line.Speaker.ToUpper() : Line.Speaker;\n        const FString Paren = Theme.bShowParentheticals && !Line.Paren.IsEmpty() ? FString::Printf(TEXT(\" (%s)\"), *Line.Paren) : FString();\n        if (Theme.SpeakerStyle == TEXT(\"inline\")) Body = FString::Printf(TEXT(\"<b>%s</b>%s: %s\"), *Name, *Paren, *Line.Text);\n        else\n        {\n            UTextBlock* Speaker = Text(Name + Paren, FontSize(Theme.SpeakerScale), Theme.SpeakerColour, TEXT(\"Bold\"));\n            Speaker->SetJustification(Justify(Theme.TextAlign));\n            Entry->AddChildToVerticalBox(Speaker);\n        }\n    }\n    const FLinearColor Colour = Line.bIsChoice || Line.bIsTransition ? Theme.Muted : Theme.Text;\n    const bool bTypeIt = bType && !Line.bIsChoice && Theme.CharactersPerSecond > 0 && UNarrativeSettings::SpeedMultiplier() > 0.f;\n    URichTextBlock* Said = Rich(ToRichMarkup(bTypeIt ? FString() : Body), Size, Colour);\n    Entry->AddChildToVerticalBox(Said);\n    Lines->AddChildToVerticalBox(Entry)->SetPadding(FMargin(0, 0, 0, Size * Theme.ParagraphSpacing));\n    if (bTypeIt)\n    {\n        TypingBlock = Said;\n        TypingText = Body;\n        TypingShown = 0;\n        TypingClock = 0.f;\n    }\n    if (bType && Theme.LineFade > 0.f)\n    {\n        Entry->SetRenderOpacity(0.f);\n        Fading.Add(Entry);\n        FadeSeconds.Add(Theme.LineFade);\n    }\n    Scroll->ScrollToEnd();\n    ScrollFrames = 3;\n}\n\nvoid UNarrativeStoryWidget::ShowPicture(const FString& File)\n{\n    UTexture2D* Texture = UNarrativeBridgeComponent::LoadPicture(File);\n    if (!Texture) return;\n    Picture->SetBrushFromTexture(Texture, true);\n    PictureBox->SetVisibility(ESlateVisibility::HitTestInvisible);\n    Dim->SetVisibility(Theme.PictureDim > 0.f ? ESlateVisibility::HitTestInvisible : ESlateVisibility::Collapsed);\n    if (Theme.PictureFade > 0.f)\n    {\n        PictureBox->SetRenderOpacity(0.f);\n        Fading.Add(PictureBox);\n        FadeSeconds.Add(Theme.PictureFade);\n    }\n}\n\nvoid UNarrativeStoryWidget::ShowPortrait(const FString& SpeakerId)\n{\n    UTexture2D* Texture = SpeakerId.IsEmpty() ? nullptr : UNarrativeBridgeComponent::LoadPortrait(SpeakerId);\n    if (!Texture)\n    {\n        if (SpeakerId.IsEmpty() && Theme.bKeepPortraitForNarration) return;\n        Portrait->SetVisibility(ESlateVisibility::Collapsed);\n        PortraitSpeaker.Reset();\n        return;\n    }\n    if (SpeakerId == PortraitSpeaker && Portrait->GetVisibility() != ESlateVisibility::Collapsed) return;\n    // Taking turns: each new speaker stands on the other side.\n    if (Theme.PortraitSide == TEXT(\"alternate\")) bPortraitRight = PortraitSpeaker.IsEmpty() ? false : !bPortraitRight;\n    else bPortraitRight = Theme.PortraitSide == TEXT(\"right\");\n    PortraitSpeaker = SpeakerId;\n    const float Height = Theme.PortraitHeight;\n    const float Width = Height * Texture->GetSizeX() / FMath::Max(1, Texture->GetSizeY());\n    Portrait->SetBrushFromTexture(Texture, false);\n    Portrait->SetDesiredSizeOverride(FVector2D(Width, Height));\n    Portrait->SetRenderScale(FVector2D(bPortraitRight && Theme.bPortraitMirrorRight ? -1.f : 1.f, 1.f));\n    if (UCanvasPanelSlot* Place = Cast<UCanvasPanelSlot>(Portrait->Slot))\n    {\n        const FVector4 Rect = UNarrativeThemeLibrary::PanelRect(Theme);\n        const float X = bPortraitRight ? Rect.Z : Rect.X;\n        Place->SetAnchors(FAnchors(X, Rect.Y, X, Rect.Y));\n        Place->SetAlignment(FVector2D(bPortraitRight ? 1.f : 0.f, 1.f));\n    }\n    Portrait->SetVisibility(ESlateVisibility::HitTestInvisible);\n    if (Theme.PortraitFade > 0.f)\n    {\n        Portrait->SetRenderOpacity(0.f);\n        Fading.Add(Portrait);\n        FadeSeconds.Add(Theme.PortraitFade);\n    }\n}\n\nvoid UNarrativeStoryWidget::ClearPrompt()\n{\n    if (Choices) Choices->ClearChildren();\n    ChoiceButtons.Reset();\n    ContinueButton = nullptr;\n    AutoAdvanceLeft = -1.f;\n}\n\nvoid UNarrativeStoryWidget::ShowPrompt()\n{\n    ClearPrompt();\n    bPromptShown = true;\n    if (!Story) return;\n    switch (Prompt)\n    {\n    case EPrompt::Exit:\n        // The game plays until it resumes the dialogue.\n        SetVisibility(ESlateVisibility::Collapsed);\n        break;\n    case EPrompt::Continue:\n    {\n        const FString Label = T(Theme.ContinueLabel) + (Theme.bContinueArrow ? TEXT(\"  \\u203A\") : TEXT(\"\"));\n        ContinueButton = Button(Choices, Label, [this] { GoOn(); });\n        const bool bAuto = UNarrativeSettings::GetAutoAdvance() == ENarrativeAutoAdvance::On || (UNarrativeSettings::GetAutoAdvance() == ENarrativeAutoAdvance::AsDesigned && Theme.bAutoAdvance);\n        if (bAuto) AutoAdvanceLeft = Theme.AutoAdvanceDelay;\n        break;\n    }\n    case EPrompt::Choices:\n    {\n        const TArray<FString> Labels = Story->GetChoices();\n        for (int32 i = 0; i < Labels.Num(); ++i)\n        {\n            const FString Label = Theme.bShowChoiceNumbers && i < 9 ? FString::Printf(TEXT(\"%d.  %s\"), i + 1, *Labels[i]) : Labels[i];\n            // A choice taken before (in this read or an earlier one) is greyed out, still clickable.\n            ChoiceButtons.Add(Button(Choices, Label, [this, i] { Pick(i); }, true, 1.f, Story->WasChosen(i)));\n        }\n        if (Theme.bShowLockedChoices)\n            for (const FNarrativeLockedChoice& L : Story->GetLockedChoices())\n                Button(Choices, FString::Printf(TEXT(\"%s  \\u00B7  %s %s\"), *L.Text, *T(Theme.LockedLabel), *L.Needs), nullptr, false);\n        break;\n    }\n    case EPrompt::Ended:\n    {\n        UTextBlock* End = Text(FString::Printf(TEXT(\"\\u2014 %s \\u2014\"), *T(Theme.EndLabel)), FontSize(), Theme.Accent, TEXT(\"Bold\"));\n        End->SetJustification(ETextJustify::Center);\n        Choices->AddChildToVerticalBox(End)->SetHorizontalAlignment(HAlign_Fill);\n        break;\n    }\n    default:\n        break;\n    }\n}\n\n// ---- Story events: lines wait their turn, then the choices ------------------------------------\n\nvoid UNarrativeStoryWidget::HandleLine(const FNarrativeLine& Line)\n{\n    Pending.Add(Line);\n}\n\nvoid UNarrativeStoryWidget::HandleChoices(const TArray<FString>& InChoices) { Prompt = EPrompt::Choices; bPromptShown = false; }\nvoid UNarrativeStoryWidget::HandleContinue() { Prompt = EPrompt::Continue; bPromptShown = false; }\nvoid UNarrativeStoryWidget::HandleEnded() { Prompt = EPrompt::Ended; bPromptShown = false; }\nvoid UNarrativeStoryWidget::HandleExit(const FString& ExitName) { Prompt = EPrompt::Exit; bPromptShown = false; }\n\nvoid UNarrativeStoryWidget::HandleResumed()\n{\n    SetVisibility(ESlateVisibility::SelfHitTestInvisible);\n}\n\nvoid UNarrativeStoryWidget::HandleRestarted()\n{\n    ClearLines();\n    ClearPrompt();\n    Pending.Reset();\n    CutsceneLeft = -1.f;\n    Prompt = EPrompt::None;\n    if (Portrait) Portrait->SetVisibility(ESlateVisibility::Collapsed);\n    PortraitSpeaker.Reset();\n    SetVisibility(ESlateVisibility::SelfHitTestInvisible);\n}\n\nvoid UNarrativeStoryWidget::HandleStatus(const FString& Message)\n{\n    if (StatusText) StatusText->SetText(FText::FromString(Message));\n}\n\nvoid UNarrativeStoryWidget::NativeTick(const FGeometry& MyGeometry, float InDeltaTime)\n{\n    Super::NativeTick(MyGeometry, InDeltaTime);\n    // The newest line stays in view: scrolled again once it (or the choices under it) has been laid out.\n    if (ScrollFrames > 0 && Scroll) { Scroll->ScrollToEnd(); --ScrollFrames; }\n    for (int32 i = Fading.Num() - 1; i >= 0; --i)\n    {\n        UWidget* W = Fading[i];\n        const float Opacity = W ? FMath::Min(1.f, W->GetRenderOpacity() + InDeltaTime / FMath::Max(0.01f, FadeSeconds[i])) : 1.f;\n        if (W) W->SetRenderOpacity(Opacity);\n        if (Opacity >= 1.f) { Fading.RemoveAt(i); FadeSeconds.RemoveAt(i); }\n    }\n    if (TypingBlock)\n    {\n        // The typewriter: letters a second from the theme, faster or slower with the player's Typing speed.\n        TypingClock += InDeltaTime * Theme.CharactersPerSecond * UNarrativeSettings::SpeedMultiplier();\n        const int32 Total = VisibleLength(TypingText);\n        bool bChanged = false;\n        while (TypingClock >= 1.f && TypingShown < Total)\n        {\n            TypingClock -= 1.f;\n            ++TypingShown;\n            bChanged = true;\n            const FString Shown = UNarrativeBridgeComponent::PlainText(VisiblePrefix(TypingText, TypingShown));\n            if (Theme.PunctuationPause > 0.f && Shown.Len() > 0 && EndsSentence(Shown[Shown.Len() - 1]) && TypingShown < Total)\n                TypingClock -= Theme.PunctuationPause * Theme.CharactersPerSecond * UNarrativeSettings::SpeedMultiplier();\n        }\n        if (bChanged) { TypingBlock->SetText(FText::FromString(ToRichMarkup(VisiblePrefix(TypingText, TypingShown)))); ScrollFrames = 2; }\n        if (TypingShown >= Total) TypingBlock = nullptr;\n        return;\n    }\n    if (CutsceneLeft >= 0.f)\n    {\n        // A cutscene line stays long enough to read, then the story goes on by itself.\n        if (!bMenuOpen && !bCutsceneWaits) CutsceneLeft -= InDeltaTime;\n        if (CutsceneLeft >= 0.f) return;\n        EndCutsceneLine();\n    }\n    if (Pending.Num() > 0)\n    {\n        const FNarrativeLine Next = Pending[0];\n        Pending.RemoveAt(0);\n        ShowLine(Next, true);\n        if (Next.bIsCutscene)\n        {\n            // 1.2 s + 0.055 s a letter, 2 to 9 s, as in Narrative Bridge's other readers; Skip goes on now.\n            CutsceneLeft = FMath::Clamp(1.2f + UNarrativeBridgeComponent::PlainText(Next.Text).Len() * 0.055f, 2.f, 9.f);\n            bCutsceneWaits = UNarrativeSettings::GetAutoAdvance() == ENarrativeAutoAdvance::Off;\n            ClearPrompt();\n            ContinueButton = Button(Choices, T(Words.Skip) + TEXT(\"  \\u203A\"), [this] { EndCutsceneLine(); });\n        }\n        return;\n    }\n    if (Prompt != EPrompt::None && !bPromptShown) { ShowPrompt(); ScrollFrames = 3; }\n    if (AutoAdvanceLeft >= 0.f && !bMenuOpen)\n    {\n        AutoAdvanceLeft -= InDeltaTime;\n        if (AutoAdvanceLeft < 0.f) GoOn();\n    }\n}\n\nvoid UNarrativeStoryWidget::FinishTyping()\n{\n    if (!TypingBlock) return;\n    TypingBlock->SetText(FText::FromString(ToRichMarkup(TypingText)));\n    TypingBlock = nullptr;\n}\n\nvoid UNarrativeStoryWidget::ChooseByKey(int32 Index)\n{\n    if (ChoiceButtons.IsValidIndex(Index) && !TypingBlock && Pending.Num() == 0) Pick(Index);\n}\n\nvoid UNarrativeStoryWidget::Pick(int32 Index)\n{\n    if (!Story) return;\n    const TArray<FString> Labels = Story->GetChoices();\n    if (!Labels.IsValidIndex(Index)) return;\n    FNarrativeLine Chosen;\n    Chosen.Text = Labels[Index];\n    Chosen.bIsChoice = true;\n    ClearPrompt();\n    Prompt = EPrompt::None;\n    ShowLine(Chosen, false);\n    Story->Choose(Index);\n}\n\nvoid UNarrativeStoryWidget::EndCutsceneLine()\n{\n    if (CutsceneLeft < 0.f) return;\n    CutsceneLeft = -1.f;\n    ClearPrompt();\n}\n\nvoid UNarrativeStoryWidget::GoOn()\n{\n    if (!Story || !Story->IsWaitingForContinue()) return;\n    ClearPrompt();\n    Prompt = EPrompt::None;\n    Story->Continue();\n}\n\nFReply UNarrativeStoryWidget::NativeOnKeyDown(const FGeometry& InGeometry, const FKeyEvent& InKeyEvent)\n{\n    const FKey Key = InKeyEvent.GetKey();\n    if (Key == EKeys::Escape && bMenuOpen) { CloseMenu(); return FReply::Handled(); }\n    if (!bKeyboardShortcuts || bMenuOpen || !Story) return Super::NativeOnKeyDown(InGeometry, InKeyEvent);\n    static const FKey Numbers[] = { EKeys::One, EKeys::Two, EKeys::Three, EKeys::Four, EKeys::Five, EKeys::Six, EKeys::Seven, EKeys::Eight, EKeys::Nine };\n    for (int32 i = 0; i < 9; ++i)\n        if (Key == Numbers[i]) { ChooseByKey(i); return FReply::Handled(); }\n    if (Key == EKeys::SpaceBar || Key == EKeys::Enter || Key == EKeys::Gamepad_FaceButton_Bottom)\n    {\n        if (TypingBlock && Theme.bClickToSkip) FinishTyping();\n        else if (CutsceneLeft >= 0.f) EndCutsceneLine();\n        else if (ContinueButton && Pending.Num() == 0) GoOn();\n        return FReply::Handled();\n    }\n    return Super::NativeOnKeyDown(InGeometry, InKeyEvent);\n}\n\nFReply UNarrativeStoryWidget::NativeOnMouseButtonDown(const FGeometry& InGeometry, const FPointerEvent& InMouseEvent)\n{\n    // A click on the story finishes the line being typed.\n    if (TypingBlock && Theme.bClickToSkip) { FinishTyping(); return FReply::Handled(); }\n    return Super::NativeOnMouseButtonDown(InGeometry, InMouseEvent);\n}\n\n// ---- The Settings and save-slot menus ----------------------------------------------------------\n\nvoid UNarrativeStoryWidget::OpenSettings()\n{\n    bMenuOpen = true;\n    bMenuSlots = false;\n    BuildMenu();\n}\n\nvoid UNarrativeStoryWidget::OpenSaveSlots(bool bSaving)\n{\n    if (!Story || !Story->IsStarted()) return;\n    bMenuOpen = true;\n    bMenuSlots = true;\n    bMenuSaving = bSaving;\n    BuildMenu();\n}\n\nvoid UNarrativeStoryWidget::CloseMenu()\n{\n    bMenuOpen = false;\n    if (MenuList) MenuList->ClearChildren();\n    if (MenuLayer) MenuLayer->SetVisibility(ESlateVisibility::Collapsed);\n}\n\nvoid UNarrativeStoryWidget::BuildMenu()\n{\n    MenuList->ClearChildren();\n    MenuLayer->SetVisibility(bMenuOpen ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);\n    if (!bMenuOpen) return;\n    if (bMenuSlots) { BuildSlots(bMenuSaving); return; }\n    UTextBlock* Title = Text(T(Words.Title), FontSize(), Theme.Accent, TEXT(\"Bold\"));\n    Title->SetJustification(ETextJustify::Center);\n    MenuList->AddChildToVerticalBox(Title)->SetPadding(FMargin(0, 0, 0, FontSize(0.5f)));\n    const FString Sep = TEXT(\":  \");\n    const ENarrativeTypingSpeed Speed = UNarrativeSettings::GetTypingSpeed();\n    const FString SpeedWord = Speed == ENarrativeTypingSpeed::Slow ? Words.Slow : Speed == ENarrativeTypingSpeed::Fast ? Words.Fast : Speed == ENarrativeTypingSpeed::Instant ? Words.Instant : Words.Normal;\n    const ENarrativeAutoAdvance Auto = UNarrativeSettings::GetAutoAdvance();\n    const FString AutoWord = Auto == ENarrativeAutoAdvance::On ? Words.On : Auto == ENarrativeAutoAdvance::Off ? Words.Off : Words.AsDesigned;\n    // Each change rebuilds the panel (UNarrativeSettings::OnChanged), so the menu opens again on the same rows.\n    auto Keep = [this](TFunction<void()> Change) { return [this, Change] { Change(); OpenSettings(); }; };\n    Button(MenuList, T(Words.TextSize) + Sep + FString::Printf(TEXT(\"%d%%\"), FMath::RoundToInt(UNarrativeSettings::GetTextScale() * 100.f)), Keep([] { UNarrativeSettings::SetTextScale(UNarrativeSettings::Next(UNarrativeSettings::TextScales(), UNarrativeSettings::GetTextScale())); }));\n    Button(MenuList, T(Words.TypingSpeed) + Sep + T(SpeedWord), Keep([Speed] { UNarrativeSettings::SetTypingSpeed(static_cast<ENarrativeTypingSpeed>((static_cast<int32>(Speed) + 1) % 4)); }));\n    Button(MenuList, T(Words.AutoAdvance) + Sep + T(AutoWord), Keep([Auto] { UNarrativeSettings::SetAutoAdvance(static_cast<ENarrativeAutoAdvance>((static_cast<int32>(Auto) + 1) % 3)); }));\n    Button(MenuList, T(Words.HighContrast) + Sep + (UNarrativeSettings::GetHighContrast() ? T(Words.On) : T(Words.Off)), Keep([] { UNarrativeSettings::SetHighContrast(!UNarrativeSettings::GetHighContrast()); }));\n    Button(MenuList, T(Words.VoiceVolume) + Sep + FString::Printf(TEXT(\"%d%%\"), FMath::RoundToInt(UNarrativeSettings::GetVoiceVolume() * 100.f)), Keep([] { UNarrativeSettings::SetVoiceVolume(UNarrativeSettings::Next(UNarrativeSettings::VoiceVolumes(), UNarrativeSettings::GetVoiceVolume())); }));\n    const TArray<FString> Languages = UNarrativeLocalization::GetLanguages();\n    if (Languages.Num() > 0)\n        Button(MenuList, T(Words.Language) + Sep + UNarrativeLocalization::DisplayName(UNarrativeLocalization::GetLanguage()), Keep([Languages]\n        {\n            // \"\" (the story as written), then each language in the sheet.\n            const int32 At = Languages.IndexOfByKey(UNarrativeLocalization::GetLanguage());\n            UNarrativeLocalization::SetLanguage(At + 1 < Languages.Num() ? Languages[At + 1] : FString());\n        }));\n    Button(MenuList, T(Words.Reset), Keep([] { UNarrativeSettings::ResetSettings(); }));\n    Button(MenuList, T(Words.Close), [this] { CloseMenu(); });\n}\n\nvoid UNarrativeStoryWidget::BuildSlots(bool bSaving)\n{\n    UTextBlock* Title = Text(bSaving ? T(Words.SaveTitle) : T(Words.LoadTitle), FontSize(), Theme.Accent, TEXT(\"Bold\"));\n    Title->SetJustification(ETextJustify::Center);\n    MenuList->AddChildToVerticalBox(Title)->SetPadding(FMargin(0, 0, 0, FontSize(0.5f)));\n    const FString Dot = TEXT(\"  \\u00B7  \");\n    for (const FNarrativeSlotInfo& Info : Story->GetSlots())\n    {\n        // The autosave can be loaded, not saved over.\n        if (bSaving && Info.Slot == UNarrativeBridgeComponent::AutosaveSlot) continue;\n        const FString Name = Info.Slot == UNarrativeBridgeComponent::AutosaveSlot ? T(Words.Autosave) : FString::Printf(TEXT(\"%s %d\"), *T(Words.Slot), Info.Slot);\n        const FString Label = !Info.bExists ? Name + Dot + T(Words.Empty)\n            : Name + Dot + Info.PassageTitle + Dot + (Info.SavedAt + (FDateTime::Now() - FDateTime::UtcNow())).ToString(TEXT(\"%Y-%m-%d %H:%M\")) + (Info.bOtherVersion ? FString::Printf(TEXT(\"  (%s)\"), *T(Words.OlderVersion)) : FString());\n        const int32 N = Info.Slot;\n        Button(MenuList, Label, [this, N, bSaving]\n        {\n            CloseMenu();\n            if (!Story) return;\n            if (bSaving) Story->SaveToSlot(N);\n            else Story->LoadFromSlot(N);\n        }, bSaving || Info.bExists);\n    }\n    Button(MenuList, T(Words.Close), [this] { CloseMenu(); });\n}\n";

/** templates/unreal/Widget.h */
export const WIDGET_H = "// Generated by Narrative Bridge. The story panel: a UMG widget built in C++ from a Narrative Theme.\n#pragma once\n\n#include \"CoreMinimal.h\"\n#include \"Blueprint/UserWidget.h\"\n#include \"Components/Button.h\"\n#include \"NarrativeBridgeTypes.h\"\n#include \"NarrativeTheme.h\"\n#include \"NarrativeStoryWidget.generated.h\"\n\nclass UBorder;\nclass UCanvasPanel;\nclass UDataTable;\nclass UHorizontalBox;\nclass UImage;\nclass UNarrativeBridgeComponent;\nclass URichTextBlock;\nclass UScaleBox;\nclass UScrollBox;\nclass UTextBlock;\nclass UVerticalBox;\n\n/** A button of the story panel that runs a bit of code when clicked. */\nUCLASS()\nclass __API__ UNarrativePanelButton : public UButton\n{\n    GENERATED_BODY()\n\npublic:\n    TFunction<void()> Action;\n\n    void Bind() { OnClicked.AddUniqueDynamic(this, &UNarrativePanelButton::Run); }\n\nprivate:\n    UFUNCTION()\n    void Run() { if (Action) Action(); }\n};\n\n/** The words of the panel's Settings and save-slot menus, to change or translate them (Translations.csv has them too). */\nUSTRUCT(BlueprintType)\nstruct FNarrativePanelWords\n{\n    GENERATED_BODY()\n\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Title = TEXT(\"Settings\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString TextSize = TEXT(\"Text size\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString TypingSpeed = TEXT(\"Typing speed\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString AutoAdvance = TEXT(\"Go on by itself\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString HighContrast = TEXT(\"High contrast\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString VoiceVolume = TEXT(\"Voice volume\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Language = TEXT(\"Language\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Slow = TEXT(\"Slow\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Normal = TEXT(\"Normal\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Fast = TEXT(\"Fast\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Instant = TEXT(\"Instant\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString AsDesigned = TEXT(\"As designed\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString On = TEXT(\"On\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Off = TEXT(\"Off\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Reset = TEXT(\"Reset\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Close = TEXT(\"Close\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString SaveTitle = TEXT(\"Save to a slot\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString LoadTitle = TEXT(\"Load a save\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Slot = TEXT(\"Slot\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Autosave = TEXT(\"Autosave\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Empty = TEXT(\"empty\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString OlderVersion = TEXT(\"earlier version\");\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\") FString Skip = TEXT(\"Skip\");\n};\n\n/**\n * The story UI: story text (scrolling, by scene, or one line at a time) typed out letter by letter, the speaking\n * character's portrait, the scene picture behind, choices (locked ones greyed out with what they need), the Continue\n * button and the ending, and a toolbar with Restart, Save, Load (save slots) and Settings. Keys: 1-9 choose, Space or\n * Return continues (or finishes the line being typed), Escape closes a menu. It steps aside at exits to the game. To\n * design your own UI instead, leave it out and use the story component's events.\n */\nUCLASS()\nclass __API__ UNarrativeStoryWidget : public UUserWidget\n{\n    GENERATED_BODY()\n\npublic:\n    /** Optional: a Narrative Theme asset. Empty: the look chosen in Narrative Bridge (Theme.json). */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TObjectPtr<UNarrativeThemeAsset> ThemeAsset;\n\n    /** Optional: the font family to use (a Font asset with Regular, Bold and Italic typefaces). Empty: the engine's Roboto. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    TObjectPtr<UObject> FontFamily;\n\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    FNarrativePanelWords Words;\n\n    /** Keys 1-9 choose, Space or Return continues. */\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = \"Narrative Bridge\")\n    bool bKeyboardShortcuts = true;\n\n    /** Draws this story (and everything it has shown so far). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void SetStory(UNarrativeBridgeComponent* InStory);\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    UNarrativeBridgeComponent* GetStory() const { return Story; }\n\n    /** Builds the panel again from the theme (after changing ThemeAsset or its settings). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void Rebuild();\n\n    /** Shows the rest of the line being typed at once. */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void FinishTyping();\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool IsTyping() const { return TypingBlock != nullptr; }\n\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void OpenSettings();\n\n    /** Opens the save-slot menu, to save into a slot or to load one (the autosave first). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void OpenSaveSlots(bool bSaving);\n\n    /** Closes whichever menu is open (Settings or the save slots). */\n    UFUNCTION(BlueprintCallable, Category = \"Narrative Bridge\")\n    void CloseMenu();\n\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    bool IsMenuOpen() const { return bMenuOpen; }\n\n    /** The theme in use (with the player's High contrast setting applied). */\n    UFUNCTION(BlueprintPure, Category = \"Narrative Bridge\")\n    FNarrativeTheme GetTheme() const { return Theme; }\n\n    /** The visible part of a line: its first Count letters, with the emphasis tags around them kept and closed. */\n    static FString VisiblePrefix(const FString& Text, int32 Count);\n\n    /** How many letters a reader sees in a line (its emphasis tags left out). */\n    static int32 VisibleLength(const FString& Text);\n\n    /** A line's emphasis (<i>, <b>, <u>) as Rich Text Block markup; any other < is shown as written. */\n    static FString ToRichMarkup(const FString& Text);\n\nprotected:\n    virtual TSharedRef<SWidget> RebuildWidget() override;\n    virtual void NativeConstruct() override;\n    virtual void NativeDestruct() override;\n    virtual void NativeTick(const FGeometry& MyGeometry, float InDeltaTime) override;\n    virtual FReply NativeOnKeyDown(const FGeometry& InGeometry, const FKeyEvent& InKeyEvent) override;\n    virtual FReply NativeOnMouseButtonDown(const FGeometry& InGeometry, const FPointerEvent& InMouseEvent) override;\n\nprivate:\n    enum class EPrompt : uint8 { None, Choices, Continue, Ended, Exit };\n\n    UFUNCTION() void HandleLine(const FNarrativeLine& Line);\n    UFUNCTION() void HandleChoices(const TArray<FString>& Choices);\n    UFUNCTION() void HandleContinue();\n    UFUNCTION() void HandleEnded();\n    UFUNCTION() void HandleExit(const FString& ExitName);\n    UFUNCTION() void HandleResumed();\n    UFUNCTION() void HandleRestarted();\n    UFUNCTION() void HandleStatus(const FString& Message);\n\n    void Bind(bool bOn);\n    void LoadTheme();\n    void Layout();\n    void Redraw();\n    void ClearLines();\n    void ShowLine(const FNarrativeLine& Line, bool bType);\n    void ShowPrompt();\n    void ClearPrompt();\n    void ShowPicture(const FString& File);\n    void ShowPortrait(const FString& SpeakerId);\n    void BuildMenu();\n    void BuildSlots(bool bSaving);\n    void ChooseByKey(int32 Index);\n    /** Takes a choice: shows it in the transcript (when the theme keeps them), then lets the story go on. */\n    void Pick(int32 Index);\n    void GoOn();\n    /** A cutscene line has been read (or skipped): the next line, or the choices, may come. */\n    void EndCutsceneLine();\n    FString T(const FString& Source) const;\n    int32 FontSize(float Scale = 1.f) const;\n    FSlateFontInfo Font(int32 Size, const TCHAR* Typeface) const;\n    UDataTable* Styles(int32 Size, const FLinearColor& Colour);\n    UTextBlock* Text(const FString& Content, int32 Size, const FLinearColor& Colour, const TCHAR* Typeface = TEXT(\"Regular\"));\n    URichTextBlock* Rich(const FString& Markup, int32 Size, const FLinearColor& Colour);\n    UNarrativePanelButton* Button(UVerticalBox* Into, const FString& Label, TFunction<void()> Action, bool bEnabled = true, float Scale = 1.f, bool bChosen = false);\n    UNarrativePanelButton* ToolButton(const FString& Label, TFunction<void()> Action);\n    FLinearColor Faded(const FLinearColor& Colour, float Alpha) const { return FLinearColor(Colour.R, Colour.G, Colour.B, Alpha); }\n\n    UPROPERTY(Transient) TObjectPtr<UNarrativeBridgeComponent> Story;\n    UPROPERTY(Transient) TObjectPtr<UCanvasPanel> Root;\n    UPROPERTY(Transient) TObjectPtr<UScaleBox> PictureBox;\n    UPROPERTY(Transient) TObjectPtr<UImage> Picture;\n    UPROPERTY(Transient) TObjectPtr<UImage> Dim;\n    UPROPERTY(Transient) TObjectPtr<UImage> Portrait;\n    UPROPERTY(Transient) TObjectPtr<UBorder> Panel;\n    UPROPERTY(Transient) TObjectPtr<UScrollBox> Scroll;\n    UPROPERTY(Transient) TObjectPtr<UVerticalBox> Lines;\n    UPROPERTY(Transient) TObjectPtr<UVerticalBox> Choices;\n    UPROPERTY(Transient) TObjectPtr<UHorizontalBox> Toolbar;\n    UPROPERTY(Transient) TObjectPtr<UTextBlock> StatusText;\n    UPROPERTY(Transient) TObjectPtr<UBorder> MenuLayer;\n    UPROPERTY(Transient) TObjectPtr<UVerticalBox> MenuList;\n    UPROPERTY(Transient) TObjectPtr<URichTextBlock> TypingBlock;\n    UPROPERTY(Transient) TArray<TObjectPtr<UNarrativePanelButton>> ChoiceButtons;\n    UPROPERTY(Transient) TObjectPtr<UNarrativePanelButton> ContinueButton;\n    UPROPERTY(Transient) TMap<FString, TObjectPtr<UDataTable>> StyleTables;\n    /** Widgets fading in (lines, the picture, the portrait) and how long each fade lasts. */\n    UPROPERTY(Transient) TArray<TObjectPtr<UWidget>> Fading;\n\n    FNarrativeTheme Theme;\n    TArray<float> FadeSeconds;\n    TArray<FNarrativeLine> Pending;\n    EPrompt Prompt = EPrompt::None;\n    FString TypingText;\n    int32 TypingShown = 0;\n    float TypingClock = 0.f;\n    float PauseLeft = 0.f;\n    float AutoAdvanceLeft = -1.f;\n    /** Seconds the cutscene line on screen stays (-1: none); it waits for Skip when the player turned Go on by itself Off. */\n    float CutsceneLeft = -1.f;\n    bool bCutsceneWaits = false;\n    FString PortraitSpeaker;\n    bool bPortraitRight = false;\n    bool bMenuOpen = false;\n    bool bMenuSaving = false;\n    bool bMenuSlots = false;\n    bool bPromptShown = false;\n    /** Frames left to keep the text scrolled to its newest line: a new line only has its size once Slate has laid it out. */\n    int32 ScrollFrames = 0;\n    FDelegateHandle SettingsHandle;\n    FDelegateHandle LanguageHandle;\n};\n";
